insert into public.courses (id, slug, title, subtitle, description, level, order_index, is_premium, status, source, target_language, source_language) values ('4f87da5a-f490-5052-ab6c-669fe28c60fa', 'spanish-a1', 'Spanish A1 · First Steps', 'From zero to your first real conversations', 'Greetings, the sounds of Spanish, ser and estar, numbers and age, your family and daily routine, telling the time, ordering at a bar, shopping and asking for directions. Free and complete.', 'A1', 7, false, 'published', 'complementary', 'es', 'en') on conflict (id) do nothing;
insert into public.course_units (id, course_id, title, description, order_index, status) values ('c17d191d-da7b-5dcc-9f40-5651cbc3bf46', '4f87da5a-f490-5052-ab6c-669fe28c60fa', 'Sounds and greetings', 'Say hello, sound clear and get the basics of gender from day one.', 0, 'published') on conflict (id) do nothing;
insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('1eaae33a-5536-54d5-b008-fac1cb02b133', 'c17d191d-da7b-5dcc-9f40-5651cbc3bf46', 'es-hola', '¡Hola! Greetings and introductions', 'Hello and goodbye at any time of day, “Me llamo…” and “Mucho gusto”.', array['Greet people at any time of day', 'Say your name and ask someone theirs', 'Choose between tú and usted']::text[], 0, 10, 50, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1127e815-0551-586c-b60d-ea99ec8d5748', '1eaae33a-5536-54d5-b008-fac1cb02b133', 0, 'text', 'How this course works', '{"md":"Every lesson follows the same cycle: you **understand** the rule (explained in English), you **listen** to real phrases (tap the speaker), you **practise** with short exercises and you **speak** out loud with the microphone. In square brackets you''ll see a **pronunciation guide**: the syllable in CAPITALS is the stressed one. Spanish vowels are always short and pure: **ah, eh, ee, oh, oo**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a1f4a2f5-773f-53b6-8927-3c2f054e512c', '1eaae33a-5536-54d5-b008-fac1cb02b133', 1, 'example', 'Greetings people really use', '{"items":[{"ru":"¡Hola!","es":"Hello! / Hi! · [OH-lah]"},{"ru":"¡Buenos días!","es":"Good morning! · [BWEH-nohs DEE-ahs]"},{"ru":"¡Buenas tardes!","es":"Good afternoon! (until about 8 pm) · [BWEH-nahs TAR-dehs]"},{"ru":"¡Buenas noches!","es":"Good evening! / Good night! · [BWEH-nahs NOH-chehs]"},{"ru":"¿Qué tal?","es":"How''s it going? · [keh TAHL]"},{"ru":"¡Adiós! ¡Hasta luego!","es":"Goodbye! See you later! · [ah-DYOHS · AHS-tah LWEH-goh]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d7cabc6b-a2f3-5551-b9f7-1011da3a23ba', '1eaae33a-5536-54d5-b008-fac1cb02b133', 2, 'tip', 'Silent h and upside-down marks', '{"md":"The **h** in Spanish is always silent: **hola** sounds like [OH-lah], never “hoh-la”. Questions and exclamations open with an upside-down mark: **¿Qué tal?** **¡Hola!** It warns the reader early, because Spanish questions often have the same word order as statements."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e8bd4f36-ee09-5e21-9e55-466aa599e3e6', '1eaae33a-5536-54d5-b008-fac1cb02b133', 3, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"¡Buenas tardes!","lang":"es"}'::jsonb, 'Buenas tardes = good afternoon. Note: buenos días (masculine, día) but buenas tardes / buenas noches (feminine).', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('68d89f58-3672-54de-9d09-a3113b4204ab', 'e8bd4f36-ee09-5e21-9e55-466aa599e3e6', '¡Buenas tardes!', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e96f4e04-6b36-5d07-9b35-186d1b2db2fe', 'e8bd4f36-ee09-5e21-9e55-466aa599e3e6', '¡Buenas noches!', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('80c973c5-b226-55e2-8896-f3533502163d', 'e8bd4f36-ee09-5e21-9e55-466aa599e3e6', '¡Buenos días!', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e8bd4f36-ee09-5e21-9e55-466aa599e3e6', '{"correct":"¡Buenas tardes!"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ae2650dd-0310-52fb-9d4e-7b0df80d12a8', '1eaae33a-5536-54d5-b008-fac1cb02b133', 4, 'grammar', 'Introducing yourself: Me llamo…', '{"md":"The most natural way to say your name is **Me llamo** + name: **Me llamo Emma.** [meh YAH-moh] — literally “I call myself Emma”. You can also say **Soy Emma** (I''m Emma). To ask: **¿Cómo te llamas?** [KOH-moh teh YAH-mahs] — literally “How do you call yourself?”. When you meet someone: **Mucho gusto** [MOO-choh GOOS-toh] or **Encantado** (if you''re a man) / **Encantada** (if you''re a woman). The answer: **Igualmente** [ee-gwahl-MEHN-teh] — likewise."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ad6ed814-de57-5172-bcad-7a89c3579b06', '1eaae33a-5536-54d5-b008-fac1cb02b133', 5, 'dialogue', 'First day at the language school', '{"lines":[{"speaker":"Pablo","ru":"¡Hola! Me llamo Pablo. ¿Cómo te llamas?","es":"Hi! My name''s Pablo. What''s your name?"},{"speaker":"Emma","ru":"Hola, Pablo. Me llamo Emma.","es":"Hi, Pablo. My name''s Emma."},{"speaker":"Pablo","ru":"Mucho gusto, Emma.","es":"Nice to meet you, Emma."},{"speaker":"Emma","ru":"Encantada. ¿Qué tal?","es":"Nice to meet you. How''s it going?"},{"speaker":"Pablo","ru":"Muy bien, gracias. ¿Y tú?","es":"Very well, thanks. And you?"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2893bec4-6ad9-56f0-9748-58443095e9cd', '1eaae33a-5536-54d5-b008-fac1cb02b133', 6, 'multiple_choice', 'vocabulary', 'You''re a woman and someone introduces themselves. What do you say?', '', '{"lang":"es"}'::jsonb, 'Encantado/encantada agrees with the speaker: a woman says encantada, a man says encantado. Mucho gusto works for everyone.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('90cbe8c9-84c4-56d9-8acd-bee384d86f75', '2893bec4-6ad9-56f0-9748-58443095e9cd', 'Encantada.', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ab50caa5-e89d-5053-a799-dd0994656133', '2893bec4-6ad9-56f0-9748-58443095e9cd', 'Encantado.', 1) on conflict (id) do nothing;
