insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('fdbde079-da1d-590a-9b94-4c818971dc23', '1eaae33a-5536-54d5-b008-fac1cb02b133', 7, 'grammar', 'grammar', '___ te llamas?', '', '{"lang":"es"}'::jsonb, 'Spanish asks “how do you call yourself?”: ¿Cómo te llamas? Saying “¿Qué es tu nombre?” is a typical English-speaker mistake. (¿Cuál es tu nombre? is also correct, especially in Latin America, but ¿Cómo te llamas? is what you hear most.)', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('38f781d9-d34b-534f-b5bd-8673362b6e47', 'fdbde079-da1d-590a-9b94-4c818971dc23', '¿Cómo', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('137aefd9-ee9a-539b-b6cd-deee054ca14c', 'fdbde079-da1d-590a-9b94-4c818971dc23', '¿Qué', 1) on conflict (id) do nothing;
