insert into public.exercise_solutions (exercise_id, solution) values ('fdbde079-da1d-590a-9b94-4c818971dc23', '{"correct":"¿Cómo"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f56373e9-8cea-5b54-95f0-369a600be666', '1eaae33a-5536-54d5-b008-fac1cb02b133', 8, 'grammar', 'Tú or usted?', '{"md":"Spanish has two words for “you”. **Tú** [too] is informal: friends, family, people your age, children. **Usted** [oos-TEHD] is polite: older people, officials, customers. **¿Cómo estás?** (tú) — **¿Cómo está usted?** (usted). In Spain people switch to tú very quickly; in much of Latin America usted is used more often. When in doubt with a stranger, start with usted."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d07e58da-0e69-52aa-9605-a28ff54e5457', '1eaae33a-5536-54d5-b008-fac1cb02b133', 9, 'match_pairs', 'vocabulary', 'Match each phrase with its meaning.', '', '{"left":["¿Qué tal?","Igualmente.","Hasta luego.","Gracias.","Adiós."],"right":["See you later.","Likewise.","How''s it going?","Goodbye.","Thank you."],"lang":"es"}'::jsonb, 'Everyday greetings and goodbyes.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('d07e58da-0e69-52aa-9605-a28ff54e5457', '{"pairs":{"¿Qué tal?":"How''s it going?","Igualmente.":"Likewise.","Hasta luego.":"See you later.","Gracias.":"Thank you.","Adiós.":"Goodbye."}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f0ba76f0-f865-560d-b349-e95feb94ea07', '1eaae33a-5536-54d5-b008-fac1cb02b133', 10, 'true_false', 'vocabulary', 'True or false?', '“Buenas noches” can be used when you arrive somewhere in the evening, not only when you leave.', '{"lang":"es"}'::jsonb, 'Unlike “good night” in English, buenas noches works both to say hello and goodbye in the evening.', 10) on conflict (id) do nothing;
