insert into public.exercise_solutions (exercise_id, solution) values ('9e6b911f-89be-52ae-8b86-edbd28ea6a7e', '{"correct":"good morning"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b2476af2-dc02-5b51-8ce3-323798013b0d', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 0, 'text', 'Spanish is read as it''s written', '{"md":"Good news: Spanish spelling is almost perfectly regular. Once you know about **ten rules**, you can read any word aloud correctly, even one you''ve never seen. And there are only **five vowel sounds** (English has around twelve)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d9e8d3a8-c626-5e2d-b782-221e6cf2316c', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 1, 'grammar', '1 · Five pure vowels', '{"md":"**a** [ah], **e** [eh], **i** [ee], **o** [oh], **u** [oo]. They are short and **pure**: your mouth doesn''t move while you say them. English speakers tend to glide: “no” becomes “noh-oo”. In Spanish **no** is a crisp [noh]. And never reduce an unstressed vowel to “uh”: **banana** is [bah-NAH-nah], not “buh-NAN-uh”."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fe93a1e7-dbe6-5ddc-bef2-c8cd9bc0e14b', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 2, 'table', 'Vowels in words', '{"headers":["Vowel","Example","Sounds like"],"rows":[["a","casa (house)","[KAH-sah]"],["e","mesa (table)","[MEH-sah]"],["i","sí (yes)","[SEE]"],["o","todo (everything)","[TOH-doh]"],["u","uno (one)","[OO-noh]"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1aa9779d-99ac-5ec8-a4a6-6735348a9528', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 3, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"mesa","lang":"es"}'::jsonb, 'mesa [MEH-sah] = table; misa = mass (church); masa = dough. One vowel changes the word.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b8432cc7-a209-54c0-96ad-430ae2474004', '1aa9779d-99ac-5ec8-a4a6-6735348a9528', 'mesa', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e427778a-4494-5cce-a9d1-e2fedd79a48c', '1aa9779d-99ac-5ec8-a4a6-6735348a9528', 'misa', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('96297585-cdf1-52c2-96b0-57dcf9d64ac7', '1aa9779d-99ac-5ec8-a4a6-6735348a9528', 'masa', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('1aa9779d-99ac-5ec8-a4a6-6735348a9528', '{"correct":"mesa"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cfb8bcea-5cb6-552e-b550-dd1e02f9bd29', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 4, 'grammar', '2 · r and rr', '{"md":"A single **r** between vowels is a quick tap of the tongue, like the “tt” in American “butter” or “water”: **pero** [PEH-roh] (but). A double **rr**, and any **r at the start of a word**, is rolled: **perro** [PEH-rroh] (dog), **rojo** [RROH-hoh] (red). Can''t roll it yet? Keep practising “butter-butter-butter” fast — and meanwhile, a long tap is still understood."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('64e0ac16-fc81-515f-a180-74f1cc5e97e1', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 5, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"perro","lang":"es"}'::jsonb, 'perro, with a rolled rr = dog. pero, with a tap = but.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('96839b2d-007c-530e-aa2c-bdaf78b7e3f9', '64e0ac16-fc81-515f-a180-74f1cc5e97e1', 'perro', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4b3c3d30-dab1-5ae3-9f12-fc8f628cc1b6', '64e0ac16-fc81-515f-a180-74f1cc5e97e1', 'pero', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('64e0ac16-fc81-515f-a180-74f1cc5e97e1', '{"correct":"perro"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2ba46259-8c6b-511e-80fe-13be7eacdeb2', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 6, 'grammar', '3 · ñ, ll and y', '{"md":"**ñ** sounds like “ny” in “canyon”: **España** [ehs-PAH-nyah], **año** [AH-nyoh] (year). Never skip the tilde: **ano** means “anus”, so “tengo treinta anos” is a classic embarrassing mistake! **ll** and **y** both sound like the “y” in “yes”: **me llamo** [meh YAH-moh], **yo** [yoh]. (In Argentina and Uruguay they sound more like “sh”.)"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('269c62b7-ce2e-5865-bc07-a68ad6cd282d', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 7, 'grammar', '4 · j and g', '{"md":"**j** is a strong, breathy h from the back of the throat, like the “ch” in Scottish “loch”: **jamón** [hah-MOHN] (ham), **José** [hoh-SEH]. **g** before e or i sounds the same: **gente** [HEHN-teh] (people). Elsewhere g is hard, as in “go”: **gato** [GAH-toh]. In **gue/gui** the u is silent: **guitarra** [gee-TAH-rrah]."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('44ec8de4-fa57-54ef-9d95-d7139d17c6c9', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 8, 'grammar', '5 · b = v, z and c, qu', '{"md":"**b** and **v** sound exactly the same: **vino** [BEE-noh] (wine). **z**, and **c** before e/i, sound like “s” in Latin America and like “th” in “think” in most of Spain: **gracias** [GRAH-syahs] / [GRAH-thyahs]. Both are correct. **qu** is always a plain k: **queso** [KEH-soh] (cheese)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('215e6752-419b-5294-a1cc-3f6e7bed3c5b', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 9, 'grammar', '6 · Where''s the stress?', '{"md":"Words ending in a **vowel, n or s** are stressed on the **second-to-last** syllable: **CA-sa**, **HA-blan**. Words ending in **any other consonant** are stressed on the **last** syllable: **ho-TEL**, **ha-BLAR**. A written accent marks the exceptions: **ca-FÉ**, **te-LÉ-fo-no**, **in-GLÉS**. Accents can change meaning: **papa** (potato) / **papá** (dad), **si** (if) / **sí** (yes)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f7c41aa5-26d6-5aec-bd01-7fbb156fab4b', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 10, 'multiple_choice', 'vocabulary', 'Which word starts with a rolled rr sound?', '', '{"lang":"es"}'::jsonb, 'An r at the beginning of a word is always rolled: rojo [RROH-hoh]. In pero and caro it''s a single tap.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ded4340e-451b-5f2f-8f5f-d358d9c53147', 'f7c41aa5-26d6-5aec-bd01-7fbb156fab4b', 'rojo', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8e21d590-bfc0-5260-b97d-bbc4f1bafa60', 'f7c41aa5-26d6-5aec-bd01-7fbb156fab4b', 'pero', 1) on conflict (id) do nothing;
