insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('45836686-6386-5c44-bd75-8ce2d35ada96', '19dbb204-6102-5dc9-b4a4-9237d6ce03be', 11, 'true_false', 'speaking', 'True or false?', 'In Spanish, b and v sound the same.', '{"lang":"es"}'::jsonb, 'Yes: vino and bino would sound identical. Spelling just has to be memorised.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('45836686-6386-5c44-bd75-8ce2d35ada96', '{"value":true}'::jsonb) on conflict (exercise_id) do nothing;
