insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('fb70faab-038c-585c-be5f-4e62d0f254ad', 'c17d191d-da7b-5dcc-9f40-5651cbc3bf46', 'es-gender', 'El, la, un, una: gender and agreement', 'Every noun is masculine or feminine — and the words around it agree.', array['Use el, la, los, las, un, una', 'Make plurals', 'Make adjectives agree']::text[], 2, 12, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
