insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4fa17eb4-680e-5253-a329-85a5e2cbd9dc', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 0, 'text', 'Every noun has a gender', '{"md":"In Spanish every noun is **masculine or feminine**, even objects: **el libro** (the book) is masculine, **la mesa** (the table) is feminine. It''s not about meaning, it''s grammar — and the articles and adjectives around the noun change to match. This is the biggest new habit for English speakers, so we start early."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ed2192cc-e198-5f11-b7af-234099de9825', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 1, 'grammar', 'The basic rule', '{"md":"Nouns ending in **-o** are usually masculine: **el libro**, **el vaso**. Nouns ending in **-a** are usually feminine: **la casa**, **la mesa**. “The” has four forms and “a/some” has four too.","table":{"headers":["","Masculine","Feminine"],"rows":[["the (singular)","el libro","la casa"],["the (plural)","los libros","las casas"],["a / an","un libro","una casa"],["some","unos libros","unas casas"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9cc88be6-8c3a-5b0d-93b2-ca0d6bfafa53', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 2, 'tip', 'Learn every noun with its article', '{"md":"Some common words break the rule: **el día** (day), **el mapa**, **el problema**, **el idioma** (language) are masculine; **la mano** (hand), **la foto**, **la radio** are feminine. Words in **-ción** and **-dad** are always feminine: **la canción** (song), **la ciudad** (city). For words ending in **-e** or a consonant, just memorise: **el coche** (car), **la noche** (night), **el hotel**, **la flor** (flower). Tip: always learn “el día”, never just “día”."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('aad3f04e-7c70-5038-9af2-0bcec1226bb7', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 3, 'grammar', 'grammar', '___ problema', '', '{"lang":"es"}'::jsonb, 'Problema ends in -a but is masculine: el problema. Same with el día, el mapa, el idioma.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('9c73d0d8-fd6f-5bb0-8aa4-cf7c3faaeded', 'aad3f04e-7c70-5038-9af2-0bcec1226bb7', 'el', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('2d223a18-9509-588d-970b-59d3d9cbae52', 'aad3f04e-7c70-5038-9af2-0bcec1226bb7', 'la', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c60136a0-35db-562b-af3b-ef7685f867e9', 'aad3f04e-7c70-5038-9af2-0bcec1226bb7', 'los', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('aad3f04e-7c70-5038-9af2-0bcec1226bb7', '{"correct":"el"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('0fc62b66-6bf3-5540-bf0f-ed4b582f1546', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 4, 'grammar', 'Plurals', '{"md":"After a **vowel**, add **-s**: libro → **libros**. After a **consonant**, add **-es**: hotel → **hoteles**, ciudad → **ciudades**. A final **z** becomes **c**: lápiz → **lápices** (pencils). A mixed group takes the masculine: **los padres** = the parents, **los niños** = the children (boys and girls)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('28dc9b82-76f4-5542-a0b7-019b000dc2e1', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 5, 'grammar', 'Adjectives agree — and usually come after', '{"md":"Adjectives change to match the noun: **un coche rojo**, **una casa roja**, **dos casas rojas**. Adjectives ending in **-e** or a consonant only change for plural: **una casa grande**, **un coche azul**, **dos coches azules**. And they normally go **after** the noun: “a red car” is **un coche rojo**, never “un rojo coche”."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('77665632-8c6a-549e-adf6-9f43e908d0af', 'fb70faab-038c-585c-be5f-4e62d0f254ad', 6, 'example', 'Agreement in action', '{"items":[{"ru":"un vaso pequeño","es":"a small glass"},{"ru":"una mesa pequeña","es":"a small table"},{"ru":"los libros nuevos","es":"the new books"},{"ru":"las ciudades bonitas","es":"the pretty cities"},{"ru":"un hotel grande","es":"a big hotel"}]}'::jsonb) on conflict (id) do nothing;
