insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('df8b97a6-20ad-51a5-bee1-646105c67984', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 0, 'text', 'Two verbs for “to be”', '{"md":"Spanish splits English “to be” into two verbs: **ser** and **estar**. This lesson is about **ser**: it describes what someone or something **is** — identity, origin, nationality, profession, character. Next lesson we''ll meet estar."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('78f7de93-26b7-5d6c-827a-cf3fd17739a7', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 1, 'grammar', 'Ser in the present', '{"md":"Learn it as a chant: soy, eres, es, somos, sois, son.","table":{"headers":["Person","Ser","Sounds like"],"rows":[["yo (I)","soy","[SOY]"],["tú (you, informal)","eres","[EH-rehs]"],["él / ella / usted (he, she, you formal)","es","[EHS]"],["nosotros / nosotras (we)","somos","[SOH-mohs]"],["vosotros / vosotras (you all, Spain)","sois","[SOYS]"],["ellos / ellas / ustedes (they, you all)","son","[SOHN]"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6d701570-e890-55ee-91d6-027329f023f5', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 2, 'tip', 'Vosotros vs ustedes', '{"md":"**Vosotros** (you all, informal) is only used in Spain. In Latin America **ustedes** is used for any group, formal or informal: **¿Ustedes son de aquí?** You need to recognise vosotros, but ustedes is understood everywhere."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d61de069-ab1b-5ac3-9a9a-7b9fd57cf355', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 3, 'tip', 'Drop the pronoun', '{"md":"The verb ending already tells you who: **soy** can only be “I am”. So Spanish speakers say **Soy de Londres**, not “Yo soy de Londres” every time. Using yo all the time sounds heavy or overly emphatic; keep it for contrast: **Yo soy inglés, pero ella es irlandesa.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d1f2bbd3-f9d8-5fd5-849f-e64bb4b66608', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 4, 'example', 'Ser in real sentences', '{"items":[{"ru":"Soy de Manchester.","es":"I''m from Manchester."},{"ru":"¿De dónde eres?","es":"Where are you from?"},{"ru":"Es profesora.","es":"She''s a teacher."},{"ru":"Somos estudiantes.","es":"We''re students."},{"ru":"Mi ciudad es muy bonita.","es":"My city is very pretty."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('78db6c81-80c5-53a3-ad26-4395937e15e3', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 5, 'tip', 'No “a” with jobs', '{"md":"With professions, Spanish drops the article: **Soy médico** (I''m a doctor), **Es enfermera** (she''s a nurse). “Soy un médico” is a typical English-speaker mistake. Jobs agree too: **el profesor / la profesora**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a31e0f36-04ef-57bc-89cc-f6c6508e7689', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 6, 'grammar', 'Nationalities: lowercase and with gender', '{"md":"Nationalities and languages are written **without a capital letter**: **inglés** (English). Most have a feminine form: **inglés → inglesa**, **americano → americana**, **irlandés → irlandesa**, **escocés → escocesa**, **australiano → australiana**. Those ending in -e don''t change: **canadiense**, **estadounidense** (from the USA)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1dc0a855-1964-5e23-9dc9-fb225a94272f', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 7, 'grammar', 'grammar', 'Ella es ___. (English)', '', '{"lang":"es"}'::jsonb, 'Feminine form, and lowercase: Ella es inglesa.', 10) on conflict (id) do nothing;
