insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5aa5a201-eddd-5cc9-a91c-94f6c7d33e2f', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 9, 'dialogue', 'At a party in Madrid', '{"lines":[{"speaker":"Lucía","ru":"¿De dónde eres?","es":"Where are you from?"},{"speaker":"Kate","ru":"Soy de Dublín. Soy irlandesa. ¿Y tú?","es":"I''m from Dublin. I''m Irish. And you?"},{"speaker":"Lucía","ru":"Soy de Sevilla. ¿A qué te dedicas?","es":"I''m from Seville. What do you do?"},{"speaker":"Kate","ru":"Soy profesora de inglés.","es":"I''m an English teacher."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('99fa40de-cdbe-59a6-8d43-fa01e6c8628e', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 10, 'reading_comprehension', 'reading', 'What is Sara''s job?', '', '{"text":"Hola, me llamo Daniel. Soy de Toronto, soy canadiense. Soy ingeniero y mi mujer, Sara, es médica. Somos muy simpáticos.","lang":"es"}'::jsonb, 'Sara es médica = Sara is a doctor. Daniel es ingeniero.', 10) on conflict (id) do nothing;
