insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('8d1babf1-371b-5e6c-8495-278a7e777cdf', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 13, 'pronunciation', 'speaking', 'Say out loud: “I''m from New York. I''m American.”', '', '{"audio_text":"Soy de Nueva York. Soy estadounidense.","lang":"es"}'::jsonb, '[soy deh NWEH-bah YORK. soy ehs-tah-doo-nee-DEHN-seh]. Americano/americana is also common.', 10) on conflict (id) do nothing;
