insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1268a2b3-e7bb-595b-ad08-88ebd0cad218', 'c04dc24d-bf22-5f67-8c83-b82528709a5a', 1000, 'tip', '💪 Final practice', '{"md":"Now put the new words to work: **match them, hear them, recognize them and say them aloud**. That''s how they go from “I''ve seen them” to “I know them”."}'::jsonb) on conflict (id) do nothing;
