insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('5c62db03-655b-587f-a0a7-a47462230335', 'c885a1dd-a666-5239-8ddf-d04dabab3586', 'es-estar', 'Estar: how you feel and where things are', 'Estar for states, feelings and location — and ser vs estar.', array['Conjugate estar', 'Say how you feel', 'Choose between ser and estar']::text[], 1, 12, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
