insert into public.exercise_solutions (exercise_id, solution) values ('1e13d322-38ee-53d6-851f-84d4d755e9f7', '{"correct":"Spain"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('897493be-c070-5f10-84c9-c25b33d6f359', '5c62db03-655b-587f-a0a7-a47462230335', 0, 'text', 'The other “to be”', '{"md":"**Estar** describes **how** something is right now (states, feelings, conditions) and **where** it is. A rhyme to remember it: *“How you feel and where you are, that is when you use estar.”*"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2c1cfe78-785b-55e4-a0aa-5582fe7f1edd', '5c62db03-655b-587f-a0a7-a47462230335', 1, 'grammar', 'Estar in the present', '{"md":"Notice the written accents on estás, está, están: the stress falls on the last syllable.","table":{"headers":["Person","Estar","Sounds like"],"rows":[["yo","estoy","[ehs-TOY]"],["tú","estás","[ehs-TAHS]"],["él / ella / usted","está","[ehs-TAH]"],["nosotros / nosotras","estamos","[ehs-TAH-mohs]"],["vosotros / vosotras (Spain)","estáis","[ehs-TAHYS]"],["ellos / ellas / ustedes","están","[ehs-TAHN]"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5d555862-5532-53bc-b75f-615f5f7753c1', '5c62db03-655b-587f-a0a7-a47462230335', 2, 'example', 'Estar in real sentences', '{"items":[{"ru":"¿Cómo estás? — Estoy bien.","es":"How are you? — I''m fine."},{"ru":"Estoy muy cansada.","es":"I''m very tired. (woman speaking)"},{"ru":"Madrid está en el centro de España.","es":"Madrid is in the centre of Spain."},{"ru":"El café está frío.","es":"The coffee is cold."},{"ru":"Estamos en casa.","es":"We''re at home."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('db0a4f51-23b4-5cd1-9f8f-896aaccb14f9', '5c62db03-655b-587f-a0a7-a47462230335', 3, 'grammar', 'Ser or estar?', '{"md":"**Ser** = what something **is**: identity, origin, job, nationality, personality. **Estar** = **how** or **where** it is: mood, health, temporary state, location. Some adjectives change meaning: **Es aburrido** (he''s boring) / **Está aburrido** (he''s bored). **Es listo** (he''s clever) / **Está listo** (he''s ready)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2e7a2be5-26db-540a-9722-e71bc8f69512', '5c62db03-655b-587f-a0a7-a47462230335', 4, 'table', 'Same adjective, different verb', '{"headers":["With ser","With estar"],"rows":[["Es aburrido. (He''s boring.)","Está aburrido. (He''s bored.)"],["Es listo. (He''s clever.)","Está listo. (He''s ready.)"],["Es malo. (He''s bad / evil.)","Está malo. (He''s ill. / It tastes bad.)"],["Es guapa. (She''s pretty.)","Está guapa. (She looks pretty today.)"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('0b271f66-6a58-53cf-bff4-0d46f7848e92', '5c62db03-655b-587f-a0a7-a47462230335', 5, 'grammar', 'grammar', 'Madrid ___ en España.', '', '{"lang":"es"}'::jsonb, 'Location of a place or thing → estar.', 10) on conflict (id) do nothing;
