insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2fc07959-1aa5-5ba8-9c27-128090a6efdc', '5c62db03-655b-587f-a0a7-a47462230335', 8, 'tip', 'False friends: embarazada and constipado', '{"md":"**Estoy embarazada** means “I''m **pregnant**”, not embarrassed! For embarrassment say **¡Qué vergüenza!** (How embarrassing!) or **Me da vergüenza** (I feel embarrassed). And in Spain **estoy constipado** means “I have a **cold**” — constipated is **estreñido**. Two classic mistakes worth avoiding."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1d0bdc08-51f3-58d9-824a-d984898683a2', '5c62db03-655b-587f-a0a7-a47462230335', 9, 'true_false', 'vocabulary', 'True or false?', '“Estoy embarazada” means “I''m embarrassed”.', '{"lang":"es"}'::jsonb, 'It means “I''m pregnant”. Embarrassed: ¡Qué vergüenza! / Me da vergüenza.', 10) on conflict (id) do nothing;
