insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('5677fd65-acc9-5f7b-9e27-02750890d81a', 'c885a1dd-a666-5239-8ddf-d04dabab3586', 'es-numbers-age', 'Numbers, age and tener', '0 to 100, how old you are, and the things you “have” in Spanish.', array['Count to 100', 'Say your age correctly', 'Say you''re hungry, cold or in a hurry']::text[], 2, 12, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
