insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('93e21eca-f482-58d5-9fb1-a9f024ba844c', '5677fd65-acc9-5f7b-9e27-02750890d81a', 0, 'example', '0 to 10', '{"items":[{"ru":"cero, uno, dos","es":"0, 1, 2 · [SEH-roh, OO-noh, DOHS]"},{"ru":"tres, cuatro, cinco","es":"3, 4, 5 · [TREHS, KWAH-troh, SEEN-koh]"},{"ru":"seis, siete, ocho","es":"6, 7, 8 · [SAYS, SYEH-teh, OH-choh]"},{"ru":"nueve, diez","es":"9, 10 · [NWEH-beh, DYEHS]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('220438ea-e984-5dfa-8182-f09b3473d3c7', '5677fd65-acc9-5f7b-9e27-02750890d81a', 1, 'grammar', '11 to 29', '{"md":"**11–15** are special: **once, doce, trece, catorce, quince**. From **16** to **19** they''re written as one word: **dieciséis, diecisiete, dieciocho, diecinueve** (“ten-and-six”…). **20** is **veinte**, and **21–29** are also one word: **veintiuno, veintidós, veintitrés**…"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('3c8cfdc7-6a75-594b-a10a-68a3f199ca28', '5677fd65-acc9-5f7b-9e27-02750890d81a', 2, 'grammar', '30 to 100', '{"md":"Tens: **treinta, cuarenta, cincuenta, sesenta, setenta, ochenta, noventa**, and **cien** (100). From 31 on, use **y** (and) and write three words: **treinta y uno**, **cuarenta y cinco**, **noventa y nueve**. Careful with **sesenta** (60) and **setenta** (70): sesenta has an **s** like seis."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b9a92415-ff97-5d4e-9351-ef884a91e964', '5677fd65-acc9-5f7b-9e27-02750890d81a', 3, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"sesenta","lang":"es"}'::jsonb, 'sesenta = 60 (like seis); setenta = 70 (like siete).', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c553dabd-c116-5090-a45b-e1d8f9d029ff', 'b9a92415-ff97-5d4e-9351-ef884a91e964', 'sesenta', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c6c396f6-cc74-5be3-983e-6b27a5bb6951', 'b9a92415-ff97-5d4e-9351-ef884a91e964', 'setenta', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('101c75ac-9798-573f-aa4d-36962d9a702b', 'b9a92415-ff97-5d4e-9351-ef884a91e964', 'seis', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('b9a92415-ff97-5d4e-9351-ef884a91e964', '{"correct":"sesenta"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5f4b0391-afc8-5419-822b-c84dd8473eff', '5677fd65-acc9-5f7b-9e27-02750890d81a', 4, 'grammar', 'Your age: you “have” years', '{"md":"In Spanish you don''t “are” an age, you **have** years: **Tengo veinticinco años** — I''m 25. Saying “Soy 25” is the classic English-speaker mistake. To ask: **¿Cuántos años tienes?** [KWAHN-tohs AH-nyohs TYEH-nehs]. And remember the ñ in **años**!","table":{"headers":["Person","Tener (to have)"],"rows":[["yo","tengo"],["tú","tienes"],["él / ella / usted","tiene"],["nosotros / nosotras","tenemos"],["vosotros / vosotras (Spain)","tenéis"],["ellos / ellas / ustedes","tienen"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('10d04a33-e93c-56f5-8c9d-4d0a595827dc', '5677fd65-acc9-5f7b-9e27-02750890d81a', 5, 'grammar', 'grammar', 'Mi hermano ___ treinta años.', '', '{"lang":"es"}'::jsonb, 'Age always takes tener: tiene treinta años.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('55400de2-850d-59a1-a595-54040d08a7a7', '10d04a33-e93c-56f5-8c9d-4d0a595827dc', 'tiene', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('223e0e76-a693-5bca-a0ca-73590753c1ea', '10d04a33-e93c-56f5-8c9d-4d0a595827dc', 'es', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('3e1aca48-f18f-5196-8201-71700bd943ae', '10d04a33-e93c-56f5-8c9d-4d0a595827dc', 'está', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('10d04a33-e93c-56f5-8c9d-4d0a595827dc', '{"correct":"tiene"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('97834d9b-174f-5f0d-9b67-1bb221210795', '5677fd65-acc9-5f7b-9e27-02750890d81a', 6, 'tip', 'More things you “have” in Spanish', '{"md":"Many feelings that use “to be” in English use **tener** in Spanish: **tengo hambre** (I''m hungry), **tengo sed** (I''m thirsty), **tengo frío** (I''m cold), **tengo calor** (I''m hot), **tengo sueño** (I''m sleepy), **tengo miedo** (I''m scared), **tengo prisa** (I''m in a hurry), **tengo razón** (I''m right). To say “very”, use **mucho/mucha**, not muy: **tengo mucha hambre**, **tengo mucho frío**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('273f915d-5e50-5b71-99a3-c4533b32f563', '5677fd65-acc9-5f7b-9e27-02750890d81a', 7, 'grammar', 'grammar', 'How do you say “I''m hungry”?', '', '{"lang":"es"}'::jsonb, 'Hunger is something you have: tengo hambre.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b9d00a08-0c1e-5f51-8f9e-328b774502a9', '273f915d-5e50-5b71-99a3-c4533b32f563', 'Tengo hambre.', 0) on conflict (id) do nothing;
