insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cd4971c8-4f98-5d83-8357-02706d79bcc2', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 0, 'example', 'The family', '{"items":[{"ru":"el padre / la madre","es":"father / mother"},{"ru":"el hermano / la hermana","es":"brother / sister"},{"ru":"el hijo / la hija","es":"son / daughter"},{"ru":"el abuelo / la abuela","es":"grandfather / grandmother"},{"ru":"el marido / la mujer","es":"husband / wife (also el esposo / la esposa)"},{"ru":"el tío / la tía","es":"uncle / aunt"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ad8b624c-35b1-5312-bd05-8f4f6f519718', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 1, 'tip', 'The masculine plural covers both', '{"md":"**los padres** = parents (father + mother), **los hermanos** = brothers and sisters (siblings), **los hijos** = children (sons and daughters), **los abuelos** = grandparents. False friend: **los parientes** means **relatives**, not parents."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c6c6b669-7ade-5c2d-a2fa-803b6ae75e30', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 2, 'grammar', 'Mi, tu, su…', '{"md":"Possessives agree with the **thing owned**, not with the owner: **mi hermano**, **mis hermanos**. **Su** is very flexible: his, her, its, their, and your (usted). Context makes it clear: **Ana y su marido** = Ana and her husband.","table":{"headers":["English","One thing","Several things"],"rows":[["my","mi","mis"],["your (tú)","tu","tus"],["his / her / your (usted)","su","sus"],["our","nuestro / nuestra","nuestros / nuestras"],["their / your (ustedes)","su","sus"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('cb595d99-dffc-5b34-9ee2-27b99b81acd0', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 3, 'grammar', 'grammar', 'Ana vive con ___ hermanos.', '', '{"lang":"es"}'::jsonb, 'Hermanos is plural, so su → sus: her brothers.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ff8c048e-6804-5703-b4d4-ccf0078fb26f', 'cb595d99-dffc-5b34-9ee2-27b99b81acd0', 'sus', 0) on conflict (id) do nothing;
