insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('35bd2870-f217-5ecc-b505-df7211b121ef', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 4, 'grammar', 'No ’s in Spanish: use de', '{"md":"Spanish has no ’s. You say “the car **of** my father”: **el coche de mi padre**, **la casa de Ana**. **de + el** becomes **del**: **el perro del vecino** (the neighbour''s dog)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('debe4628-8c61-530a-b6c4-a37a020ad269', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 5, 'multiple_choice', 'vocabulary', 'How do you say “my father''s car”?', '', '{"lang":"es"}'::jsonb, 'Thing + de + owner: el coche de mi padre.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b562e207-256f-531a-b671-9170b74c6f0f', 'debe4628-8c61-530a-b6c4-a37a020ad269', 'el coche de mi padre', 0) on conflict (id) do nothing;
