insert into public.exercise_solutions (exercise_id, solution) values ('debe4628-8c61-530a-b6c4-a37a020ad269', '{"correct":"el coche de mi padre"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6ad88a86-f2b0-52ed-bac7-55cb2a9dcf26', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 6, 'grammar', 'Hay: there is / there are', '{"md":"**Hay** [AHY] means both “there is” and “there are” and never changes: **Hay una cocina.** **Hay dos baños.** Question: **¿Hay jardín?** (Is there a garden?). Negative: **No hay ascensor.** (There''s no lift.)"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cc43e7eb-fa26-567b-bd4f-d4355fb0b349', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 7, 'example', 'Rooms in the house', '{"items":[{"ru":"el salón","es":"the living room (Lat. Am. la sala)"},{"ru":"la cocina","es":"the kitchen"},{"ru":"el dormitorio / la habitación","es":"the bedroom"},{"ru":"el baño","es":"the bathroom"},{"ru":"el piso","es":"the flat, apartment (Lat. Am. el departamento / el apartamento)"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('28d63840-8326-553e-9aca-15c9e7e63580', '84b5ef85-10d4-57bf-ab93-828907fcc4e1', 8, 'reading_comprehension', 'reading', 'How many bedrooms are there in the flat?', '', '{"text":"Vivo con mi marido y mis dos hijos en un piso en Valencia. En el piso hay tres habitaciones, una cocina grande y un baño. Mi hermana vive muy cerca.","lang":"es"}'::jsonb, 'Hay tres habitaciones = there are three bedrooms.', 10) on conflict (id) do nothing;
