insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('71328251-2e95-546a-a739-481048a38c8b', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 0, 'text', 'One tense, three English ones', '{"md":"The Spanish present covers **I work**, **I''m working** and **I do work**. Verbs end in **-ar**, **-er** or **-ir**; you remove that ending and add a new one for each person. Learn three model verbs and you can use hundreds."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d6623c57-ae82-52d7-b54a-efdeb177b18f', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 1, 'table', 'Three model verbs', '{"caption":"The yo form always ends in -o.","headers":["Person","hablar (speak)","comer (eat)","vivir (live)"],"rows":[["yo","hablo","como","vivo"],["tú","hablas","comes","vives"],["él / ella / usted","habla","come","vive"],["nosotros / nosotras","hablamos","comemos","vivimos"],["vosotros / vosotras (Spain)","habláis","coméis","vivís"],["ellos / ellas / ustedes","hablan","comen","viven"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8bfbbdc8-c32f-5eae-ad7c-2624df70c350', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 2, 'tip', 'Questions without “do”', '{"md":"Spanish has no “do/does”. A question is the same sentence with rising intonation: **¿Hablas español?** = Do you speak Spanish? To say no, put **no** before the verb: **No hablo francés.** In short answers you''ll hear “no” twice: **No, no hablo francés.** And remember: no pronoun needed — **¿Vives aquí?** (Do you live here?)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('65e8a394-cabc-55e2-879c-2398dbd47d77', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 3, 'grammar', 'grammar', 'Ellos ___ en Madrid.', '', '{"lang":"es"}'::jsonb, 'Ellos → -en: viven.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e2e34dfc-7107-547b-af65-aad2df6933eb', '65e8a394-cabc-55e2-879c-2398dbd47d77', 'viven', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('9ac2be40-1ece-5dc9-a4af-a6acb7637b93', '65e8a394-cabc-55e2-879c-2398dbd47d77', 'vivimos', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('43864c29-47b5-50ba-8bb7-716ad8deed69', '65e8a394-cabc-55e2-879c-2398dbd47d77', 'vive', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('65e8a394-cabc-55e2-879c-2398dbd47d77', '{"correct":"viven"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e525b64d-c389-5976-9c85-f98ab244ad72', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 4, 'grammar', 'grammar', 'Do you speak Spanish?', '', '{"lang":"es"}'::jsonb, 'No helper verb: just the verb and a question mark.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e2710663-4f9f-5489-8410-99367d156cc4', 'e525b64d-c389-5976-9c85-f98ab244ad72', '¿Hablas español?', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d8619805-3437-570b-b5e1-cdf9f38202d3', 'e525b64d-c389-5976-9c85-f98ab244ad72', '¿Do hablas español?', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b5f1cd2c-0967-598d-a294-bac9f07b555d', 'e525b64d-c389-5976-9c85-f98ab244ad72', '¿Haces hablar español?', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e525b64d-c389-5976-9c85-f98ab244ad72', '{"correct":"¿Hablas español?"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e6826915-4e13-5a2a-b04e-bd36a82716c9', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 5, 'grammar', 'Routine verbs with me, te, se', '{"md":"Many routine verbs are **reflexive** — you do them to yourself: **levantarse** (to get up), **ducharse** (to shower), **acostarse** (to go to bed). Put **me, te, se, nos, os, se** before the verb: **me levanto**, **te duchas**, **se acuesta**. Some common verbs change their vowel: **acostarse → me acuesto**, **volver → vuelvo** (I come back), **empezar → empiezo** (I start). Learn them as fixed chunks for now."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('81c51c9b-b10e-513b-8e32-d81f49d92e82', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 6, 'example', 'A normal day', '{"items":[{"ru":"Me levanto a las siete.","es":"I get up at seven."},{"ru":"Desayuno café con tostadas.","es":"I have coffee and toast for breakfast."},{"ru":"Trabajo en una oficina.","es":"I work in an office."},{"ru":"Como a las dos.","es":"I have lunch at two."},{"ru":"Vuelvo a casa a las seis.","es":"I go back home at six."},{"ru":"Ceno y veo la tele.","es":"I have dinner and watch TV."},{"ru":"Me acuesto a las once.","es":"I go to bed at eleven."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f1827ce8-846c-5893-83e3-b456a22fd413', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 7, 'tip', 'Meals', '{"md":"**desayunar** = to have breakfast, **comer** = to eat and also to have lunch (the main meal, around 2 pm in Spain), **cenar** = to have dinner (in Spain often at 9 pm or later). In parts of Latin America, **almorzar** is used for lunch."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('284cf96c-47b8-5de2-a5d8-83bebec161f2', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 8, 'fill_blank', 'grammar', 'I work in a hospital: Yo ___ en un hospital.', '', '{"sentence":"Yo ___ en un hospital.","keyboard":true,"lang":"es"}'::jsonb, 'Trabajar → yo trabajo.', 10) on conflict (id) do nothing;
