insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('18dcfa92-8d83-5430-b5cd-1dc0db2229ba', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 10, 'reading_comprehension', 'reading', 'When does Laura sleep?', '', '{"text":"Laura es enfermera. Trabaja por la noche y duerme por la mañana. Se levanta a las tres de la tarde, come y lee un poco. No ve la tele.","lang":"es"}'::jsonb, 'Duerme por la mañana = she sleeps in the morning.', 10) on conflict (id) do nothing;
