insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('688c34d6-0577-5a1f-9495-1c308f051750', 'e8d98c29-eb83-554a-9ce6-7b9349956e59', 13, 'pronunciation', 'speaking', 'Describe your morning: “I get up at seven and I have coffee for breakfast.”', '', '{"audio_text":"Me levanto a las siete y desayuno café.","lang":"es"}'::jsonb, '[meh leh-BAHN-toh ah lahs SYEH-teh ee deh-sah-YOO-noh kah-FEH].', 10) on conflict (id) do nothing;
