insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('b1753b10-1dab-5298-89aa-3442adf44f44', 'a6dff4d4-d376-562e-a73e-01ffabfb26b8', 'es-time-days', 'Telling the time and the days of the week', '¿Qué hora es?, a las…, the days and how often you do things.', array['Tell the time', 'Say when you do things', 'Talk about frequency']::text[], 2, 12, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
