insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3aa630d2-de9b-5915-a203-01db27a81623', 'b1753b10-1dab-5298-89aa-3442adf44f44', -98, 'multiple_choice', 'vocabulary', 'What does “cien” mean?', '', '{"lang":"es"}'::jsonb, '«cien» = one hundred.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('34d8b0fa-39d6-5bec-b21e-9f2ff540de2a', '3aa630d2-de9b-5915-a203-01db27a81623', 'to have', 0) on conflict (id) do nothing;
