insert into public.exercise_options (id, exercise_id, label, order_index) values ('83b2e286-e6e2-53ab-a368-69bc5697046e', '3aa630d2-de9b-5915-a203-01db27a81623', 'how old are you?', 2) on conflict (id) do nothing;
