insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c3a6f018-49e3-523f-b35f-42ee6b0207c5', 'b1753b10-1dab-5298-89aa-3442adf44f44', 0, 'grammar', '¿Qué hora es?', '{"md":"**¿Qué hora es?** [keh OH-rah ehs] = What time is it? Use **es la** for one o''clock and **son las** for all the others: **Es la una.** **Son las dos.** **Son las diez.** Then add minutes with **y** (past) or **menos** (to): **y cuarto** (quarter past), **y media** (half past), **menos cuarto** (quarter to)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('38e5f60d-3a59-5df9-aaff-ebc46a534cb9', 'b1753b10-1dab-5298-89aa-3442adf44f44', 1, 'example', 'What time is it?', '{"items":[{"ru":"Es la una.","es":"It''s one o''clock."},{"ru":"Son las tres y cuarto.","es":"It''s quarter past three."},{"ru":"Son las cinco y media.","es":"It''s half past five."},{"ru":"Son las ocho menos cuarto.","es":"It''s quarter to eight."},{"ru":"Son las nueve y diez.","es":"It''s ten past nine."},{"ru":"Es mediodía.","es":"It''s midday."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('9b0647b7-b5fa-552e-967c-a8b242a43304', 'b1753b10-1dab-5298-89aa-3442adf44f44', 2, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"Son las cinco y media.","lang":"es"}'::jsonb, 'Cinco y media = half past five.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('85e28660-dbda-5819-a156-a630db5c1523', '9b0647b7-b5fa-552e-967c-a8b242a43304', 'Son las cinco y media.', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('0078be85-72f4-5888-8cbd-4c1e922476a7', '9b0647b7-b5fa-552e-967c-a8b242a43304', 'Son las seis y media.', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d164ab91-7a2d-5f03-9217-bc3e900e2195', '9b0647b7-b5fa-552e-967c-a8b242a43304', 'Son las cinco menos cuarto.', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('9b0647b7-b5fa-552e-967c-a8b242a43304', '{"correct":"Son las cinco y media."}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f964e0cd-09fe-5ebb-a44d-edaebeb387cb', 'b1753b10-1dab-5298-89aa-3442adf44f44', 3, 'grammar', 'grammar', '___ la una y diez.', '', '{"lang":"es"}'::jsonb, 'One o''clock is singular: es la una. All the other hours: son las…', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ff19bf54-a649-5b3b-bbd6-8397c9940b83', 'f964e0cd-09fe-5ebb-a44d-edaebeb387cb', 'Es', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('00e7d932-6ec4-5ddb-857e-900bc661c3e8', 'f964e0cd-09fe-5ebb-a44d-edaebeb387cb', 'Son', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c9364561-44a8-522b-bbed-ac4560a36a59', 'f964e0cd-09fe-5ebb-a44d-edaebeb387cb', 'Está', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f964e0cd-09fe-5ebb-a44d-edaebeb387cb', '{"correct":"Es"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('055cc986-c3d8-5b95-88bd-92f7de72dcb5', 'b1753b10-1dab-5298-89aa-3442adf44f44', 4, 'grammar', 'At what time?', '{"md":"**¿A qué hora…?** = At what time…? Answer with **a la / a las**: **a la una**, **a las ocho**. Add the part of the day: **de la mañana** (in the morning), **de la tarde** (in the afternoon/evening), **de la noche** (at night): **a las diez de la noche** = at 10 pm. Timetables often use the 24-hour clock: **a las 20:30** (veinte treinta)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('040c63a6-0340-540d-94aa-0396ac583892', 'b1753b10-1dab-5298-89aa-3442adf44f44', 5, 'example', 'The days (lowercase!)', '{"items":[{"ru":"lunes, martes, miércoles","es":"Monday, Tuesday, Wednesday · [LOO-nehs, MAR-tehs, MYEHR-koh-lehs]"},{"ru":"jueves, viernes","es":"Thursday, Friday · [HWEH-behs, BYEHR-nehs]"},{"ru":"sábado, domingo","es":"Saturday, Sunday · [SAH-bah-doh, doh-MEEN-goh]"},{"ru":"el fin de semana","es":"the weekend"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('04da1dec-5388-56a4-bb00-a6c6d81ad7ec', 'b1753b10-1dab-5298-89aa-3442adf44f44', 6, 'tip', '“On Monday” = el lunes', '{"md":"No preposition with days: **el lunes** = on Monday (this Monday), **los lunes** = on Mondays (every Monday). Saying “en lunes” is a typical mistake. Days and months are written in lowercase: **el sábado 3 de mayo**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e1a19866-c959-592b-b040-8555a06348f1', 'b1753b10-1dab-5298-89aa-3442adf44f44', 7, 'grammar', 'grammar', 'I work on Saturdays.', '', '{"lang":"es"}'::jsonb, 'Every Saturday → los sábados, no preposition.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('f250e9d8-1576-5de6-845d-a2ae324fc77c', 'e1a19866-c959-592b-b040-8555a06348f1', 'Trabajo los sábados.', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('672940ab-795a-5d6c-bc17-136034e51888', 'e1a19866-c959-592b-b040-8555a06348f1', 'Trabajo en sábados.', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('3e336b23-bdd5-564c-9253-b6bc752c84fc', 'e1a19866-c959-592b-b040-8555a06348f1', 'Trabajo el sábados.', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e1a19866-c959-592b-b040-8555a06348f1', '{"correct":"Trabajo los sábados."}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c7adac18-a13c-5a06-abeb-25161de1de44', 'b1753b10-1dab-5298-89aa-3442adf44f44', 8, 'grammar', 'How often?', '{"md":"**siempre** (always), **normalmente** (usually), **a veces** (sometimes), **nunca** (never), **todos los días** (every day). **Nunca** can go before the verb, or after it with **no** in front — Spanish loves double negatives: **Nunca trabajo los domingos** = **No trabajo nunca los domingos**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('aabb3961-5dd4-5a7d-848e-d55513714c11', 'b1753b10-1dab-5298-89aa-3442adf44f44', 9, 'true_false', 'grammar', 'True or false?', '“Son las una” is correct.', '{"lang":"es"}'::jsonb, 'One o''clock is singular: es la una.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('aabb3961-5dd4-5a7d-848e-d55513714c11', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('0a3cc61b-5c42-5ffc-a24e-fc3431ec6a25', 'b1753b10-1dab-5298-89aa-3442adf44f44', 10, 'match_pairs', 'vocabulary', 'Match the days.', '', '{"left":["lunes","miércoles","jueves","viernes","domingo"],"right":["Thursday","Wednesday","Monday","Sunday","Friday"],"lang":"es"}'::jsonb, 'Martes and miércoles are easy to mix up: martes is Tuesday.', 10) on conflict (id) do nothing;
