insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d57b598b-7acb-5755-a2a0-c419a430d14e', 'b1753b10-1dab-5298-89aa-3442adf44f44', 11, 'fill_blank', 'grammar', 'It''s 3:15 — Son las tres y ___.', '', '{"sentence":"Son las tres y ___.","keyboard":true,"lang":"es"}'::jsonb, 'Y cuarto (quarter past) or y quince — both are correct.', 10) on conflict (id) do nothing;
