insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('91cffdfb-a4ee-5ed9-8e76-574647ddfdd0', 'b1753b10-1dab-5298-89aa-3442adf44f44', 13, 'pronunciation', 'speaking', 'Ask and answer: “What time do you start? I start at nine.”', '', '{"audio_text":"¿A qué hora empiezas? Empiezo a las nueve.","lang":"es"}'::jsonb, '[ah keh OH-rah ehm-PYEH-sahs? ehm-PYEH-soh ah lahs NWEH-beh].', 10) on conflict (id) do nothing;
