insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ab5f2877-6625-5725-9b59-add71d122256', 'b1753b10-1dab-5298-89aa-3442adf44f44', 1000, 'tip', '💪 Final practice', '{"md":"Now put the new words to work: **match them, hear them, recognize them and say them aloud**. That''s how they go from “I''ve seen them” to “I know them”."}'::jsonb) on conflict (id) do nothing;
