insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('065cc111-c029-5623-87e2-26766e4a2333', '39d7c3f4-e9cc-51b8-850c-cccfcbc84c8c', 'es-bar', 'At the bar and the restaurant', 'Order politely, ask for the bill and say what you like with gustar.', array['Order food and drinks', 'Ask for the bill', 'Use me gusta and me gustan']::text[], 0, 12, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
