insert into public.exercise_options (id, exercise_id, label, order_index) values ('990ae2f9-8271-51d5-b14d-d3da6c91eeaa', '1f85ef27-d103-5bba-b18a-6531eceea717', 'sister', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('5696206d-8327-5516-831a-6fb066eca052', '1f85ef27-d103-5bba-b18a-6531eceea717', 'husband', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('1f85ef27-d103-5bba-b18a-6531eceea717', '{"correct":"sister"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('bbf447ea-c305-5afd-9f03-7f29bba3a77b', '065cc111-c029-5623-87e2-26766e4a2333', 0, 'grammar', 'Ordering politely', '{"md":"The most useful formulas: **Quería…** (I''d like… — very polite), **¿Me pone…?** (Can I have…? — very common in Spain), **¿Me da…?** (Can you give me…?), **Para mí…** (For me…). **Quiero** (I want) is fine with **por favor**, but quería sounds softer. And always: **por favor** [pohr fah-BOHR] and **gracias**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6a0356b3-18e3-549e-ba63-64d98972b200', '065cc111-c029-5623-87e2-26766e4a2333', 1, 'example', 'At the bar', '{"items":[{"ru":"un café solo","es":"an espresso"},{"ru":"un café con leche","es":"a white coffee"},{"ru":"una cerveza / una caña","es":"a beer / a small draught beer (Spain)"},{"ru":"un vaso de agua","es":"a glass of water"},{"ru":"un zumo de naranja","es":"an orange juice (Lat. Am. un jugo)"},{"ru":"una tapa de tortilla","es":"a small portion of Spanish omelette"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e7760ebf-955e-5fa8-aeef-18b7411a431b', '065cc111-c029-5623-87e2-26766e4a2333', 2, 'dialogue', 'At a bar in Granada', '{"lines":[{"speaker":"Camarero","ru":"Hola, buenas. ¿Qué le pongo?","es":"Hello. What can I get you?"},{"speaker":"Tom","ru":"¿Me pone una caña, por favor?","es":"Can I have a small beer, please?"},{"speaker":"Camarero","ru":"¿Algo más?","es":"Anything else?"},{"speaker":"Tom","ru":"Sí, una tapa de tortilla. ¿Cuánto es?","es":"Yes, a portion of omelette. How much is it?"},{"speaker":"Camarero","ru":"Son cuatro euros.","es":"That''s four euros."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d3af54ad-ce89-529a-9ea5-31179cc6f7a1', '065cc111-c029-5623-87e2-26766e4a2333', 3, 'grammar', 'At the restaurant', '{"md":"**¿Tienen mesa para dos?** (Do you have a table for two?) · **La carta, por favor.** (The menu, please.) · **el menú del día** = set lunch menu, with **de primero** (first course), **de segundo** (main course) and **de postre** (dessert). To finish: **La cuenta, por favor.** (The bill, please.)"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b83fdf97-2724-5f2b-bdd3-26fc8edbd546', '065cc111-c029-5623-87e2-26766e4a2333', 4, 'tip', 'False friends at the table', '{"md":"**La carta** is the menu, not a card. **Preservativo** means **condom** — preservatives are **conservantes**! Don''t ask if the food has “preservativos”. And **la cuenta** is the bill, **la factura** is a formal invoice."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('61bcb171-f425-52fd-a641-05f0a17bde71', '065cc111-c029-5623-87e2-26766e4a2333', 5, 'multiple_choice', 'vocabulary', 'You want to pay. What do you say?', '', '{"lang":"es"}'::jsonb, 'La cuenta = the bill in a bar or restaurant. El billete = ticket or banknote.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('184d4b96-87c8-5313-994b-153fddd081ca', '61bcb171-f425-52fd-a641-05f0a17bde71', 'La cuenta, por favor.', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4f75cb4f-f51e-53ae-9fc6-58e6528531dc', '61bcb171-f425-52fd-a641-05f0a17bde71', 'La factura, por favor.', 1) on conflict (id) do nothing;
