insert into public.exercise_solutions (exercise_id, solution) values ('61bcb171-f425-52fd-a641-05f0a17bde71', '{"correct":"La cuenta, por favor."}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d80bed1f-7136-5571-8df2-62d67ae94b58', '065cc111-c029-5623-87e2-26766e4a2333', 6, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"¿Me pone una caña, por favor?","lang":"es"}'::jsonb, 'Una caña = a small draught beer in Spain. Mind the ñ: cama is a bed!', 10) on conflict (id) do nothing;
