insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('db4015a5-9903-587f-86f1-821a88755b3b', '065cc111-c029-5623-87e2-26766e4a2333', 7, 'match_pairs', 'vocabulary', 'Match the food.', '', '{"left":["el pan","el pollo","el pescado","la carne","el postre"],"right":["fish","chicken","bread","dessert","meat"],"lang":"es"}'::jsonb, 'Basic words for any menu.', 10) on conflict (id) do nothing;
