insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d14aa8ba-c335-5143-bdf5-df7ee4abbc78', '065cc111-c029-5623-87e2-26766e4a2333', 8, 'grammar', 'Gustar: “it pleases me”', '{"md":"Spanish says what you like the other way round: **Me gusta el café** = literally “coffee pleases me”. The thing liked is the subject, so with a **plural** thing the verb is plural: **Me gustan las tapas.** With an action, singular: **Me gusta viajar.** Ask with **¿Te gusta…?** “Yo gusto el café” is a typical mistake.","table":{"headers":["","One thing / action","Several things"],"rows":[["I like","me gusta","me gustan"],["you like (tú)","te gusta","te gustan"],["he / she / you (usted) like(s)","le gusta","le gustan"],["we like","nos gusta","nos gustan"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b77495c2-ae76-5e88-98c4-ba3a4d410447', '065cc111-c029-5623-87e2-26766e4a2333', 9, 'grammar', 'grammar', 'Me ___ las tapas.', '', '{"lang":"es"}'::jsonb, 'Las tapas is plural → me gustan.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('0381cec0-f310-5ccb-b3a9-683ae0c71017', 'b77495c2-ae76-5e88-98c4-ba3a4d410447', 'gustan', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('7f17c391-877f-5439-93a0-8644f321211f', 'b77495c2-ae76-5e88-98c4-ba3a4d410447', 'gusta', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('2b6e9909-797a-5c79-8f47-105e409c5c4c', 'b77495c2-ae76-5e88-98c4-ba3a4d410447', 'gusto', 2) on conflict (id) do nothing;
