insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('dae29828-167c-5634-867d-1d74bcced5b7', '065cc111-c029-5623-87e2-26766e4a2333', 10, 'true_false', 'grammar', 'True or false?', '“Me gusta” changes to “me gustan” when the thing you like is plural.', '{"lang":"es"}'::jsonb, 'Gustar agrees with the thing liked: me gusta el pescado, me gustan las patatas.', 10) on conflict (id) do nothing;
