insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('858e93d8-2441-5db5-b526-e6407ca58f9f', '39d7c3f4-e9cc-51b8-850c-cccfcbc84c8c', 'es-shopping', 'Shopping: how much is it?', 'Prices, this and that, colours and sizes, paying by card.', array['Ask for prices', 'Use este, esta, ese, esa', 'Buy clothes in your size']::text[], 1, 12, 80, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('41e63910-781a-5340-a8ab-b07a400d18d4', '858e93d8-2441-5db5-b526-e6407ca58f9f', -100, 'tip', '🔁 Warm-up', '{"md":"Before you start, **recall** two words from earlier lessons. Remembering right when you''re about to forget is what makes vocabulary stick."}'::jsonb) on conflict (id) do nothing;
