insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5ef26ffe-7436-50e7-843a-385e8bb6028d', '858e93d8-2441-5db5-b526-e6407ca58f9f', -98, 'multiple_choice', 'vocabulary', 'What does “levantarse” mean?', '', '{"lang":"es"}'::jsonb, '«levantarse» = to get up.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('618706b6-368a-5384-a21c-d00ab709ed0b', '5ef26ffe-7436-50e7-843a-385e8bb6028d', 'to go to bed (me acuesto)', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('41b365d9-82b4-52e7-9d1c-038747d60068', '5ef26ffe-7436-50e7-843a-385e8bb6028d', 'to get up', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8a1fa9f6-6493-54da-b1ca-69d7aeb75f8f', '5ef26ffe-7436-50e7-843a-385e8bb6028d', 'to have breakfast', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('5ef26ffe-7436-50e7-843a-385e8bb6028d', '{"correct":"to get up"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9829e363-8e7c-59cd-b93e-5d43a3d7a4e0', '858e93d8-2441-5db5-b526-e6407ca58f9f', 0, 'grammar', '¿Cuánto cuesta?', '{"md":"**¿Cuánto cuesta?** (How much does it cost?) for one thing, **¿Cuánto cuestan?** for several. **¿Cuánto es?** = How much is it (all together)? Prices: **Cuesta tres euros con cincuenta** (€3.50) or simply **tres cincuenta**. Note: **cuesta** comes from **costar** — the o changes to ue."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('362f189c-63a5-5353-8c6b-95aaad040bd5', '858e93d8-2441-5db5-b526-e6407ca58f9f', 1, 'example', 'Useful shop phrases', '{"items":[{"ru":"¿Tiene esta camiseta en azul?","es":"Do you have this T-shirt in blue?"},{"ru":"Solo estoy mirando, gracias.","es":"I''m just looking, thanks."},{"ru":"¿Me la puedo probar?","es":"Can I try it on?"},{"ru":"¿Puedo pagar con tarjeta?","es":"Can I pay by card?"},{"ru":"En efectivo.","es":"In cash."},{"ru":"Me lo llevo.","es":"I''ll take it."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4be783fb-1646-59fd-9ace-ecffe3d8ddbe', '858e93d8-2441-5db5-b526-e6407ca58f9f', 2, 'grammar', 'This and that', '{"md":"**This**: **este** (m), **esta** (f), **estos** (m pl), **estas** (f pl). **That**: **ese**, **esa**, **esos**, **esas**. They agree with the noun: **este jersey**, **esta camiseta**, **estos zapatos**, **esas gafas**. Don''t confuse **esta** (this, f) with **está** (is, from estar)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e41e255d-b8cb-5640-b75c-e7c34295b16e', '858e93d8-2441-5db5-b526-e6407ca58f9f', 3, 'grammar', 'grammar', '___ zapatos son muy bonitos.', '', '{"lang":"es"}'::jsonb, 'Zapatos is masculine plural → estos.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('f7d15020-ae1a-5560-86eb-ead709c4b76f', 'e41e255d-b8cb-5640-b75c-e7c34295b16e', 'Estos', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('92eeadc0-f450-5e24-8ed5-e2601161b7ee', 'e41e255d-b8cb-5640-b75c-e7c34295b16e', 'Estas', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d298a2c1-a2d4-5e95-8930-c73ec8db2de4', 'e41e255d-b8cb-5640-b75c-e7c34295b16e', 'Este', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e41e255d-b8cb-5640-b75c-e7c34295b16e', '{"correct":"Estos"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('924af2c7-80d6-5d4b-832f-dd66df947cbf', '858e93d8-2441-5db5-b526-e6407ca58f9f', 4, 'grammar', 'Colours and sizes agree too', '{"md":"Colours are adjectives, so they agree: **una camiseta blanca**, **unos pantalones negros**. Colours ending in **-e** or a consonant only change in the plural: **una falda verde**, **dos camisas azules**. Clothes size is **la talla**: **¿Qué talla tiene?** (What size are you?). Shoe size is **el número**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f9056ef6-cd00-5653-aaa2-bbdd460cec5a', '858e93d8-2441-5db5-b526-e6407ca58f9f', 5, 'table', 'Basic colours', '{"headers":["Masculine","Feminine","English"],"rows":[["blanco","blanca","white"],["negro","negra","black"],["rojo","roja","red"],["amarillo","amarilla","yellow"],["verde","verde","green"],["azul","azul","blue"],["gris","gris","grey"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9624ddc7-e23e-5fa6-805a-dec72cff963d', '858e93d8-2441-5db5-b526-e6407ca58f9f', 6, 'tip', 'False friends in the shop', '{"md":"**La librería** is a **bookshop** — a library is **la biblioteca**. **El éxito** means **success** — the exit is **la salida**. **La ropa** means **clothes**, not rope. And **largo** means **long**: “large” is **grande**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('28068030-569b-51f1-9630-d350104d92a5', '858e93d8-2441-5db5-b526-e6407ca58f9f', 7, 'true_false', 'vocabulary', 'True or false?', '“Éxito” means “exit”.', '{"lang":"es"}'::jsonb, 'Éxito = success. Exit = salida.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('28068030-569b-51f1-9630-d350104d92a5', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('72b18dc9-6430-5294-a000-ca8cecd15eab', '858e93d8-2441-5db5-b526-e6407ca58f9f', 8, 'dialogue', 'In a clothes shop', '{"lines":[{"speaker":"Dependienta","ru":"Hola, ¿qué desea?","es":"Hello, can I help you?"},{"speaker":"Sam","ru":"¿Tiene esta camiseta en la talla M?","es":"Do you have this T-shirt in a medium?"},{"speaker":"Dependienta","ru":"Sí, aquí tiene. ¿De qué color?","es":"Yes, here you are. What colour?"},{"speaker":"Sam","ru":"Negra, por favor. ¿Cuánto cuesta?","es":"Black, please. How much is it?"},{"speaker":"Dependienta","ru":"Quince euros.","es":"Fifteen euros."},{"speaker":"Sam","ru":"Vale, me la llevo. ¿Puedo pagar con tarjeta?","es":"OK, I''ll take it. Can I pay by card?"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('284a3a37-ec0d-56d6-a4b2-ed5f6b048d72', '858e93d8-2441-5db5-b526-e6407ca58f9f', 9, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"Cuesta quince euros.","lang":"es"}'::jsonb, 'Quince = 15; cincuenta = 50; cinco = 5.', 10) on conflict (id) do nothing;
