insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('b658431a-ede9-5251-9335-211bc457a531', '39d7c3f4-e9cc-51b8-850c-cccfcbc84c8c', 'es-directions', 'Finding your way: directions', '¿Dónde está…?, hay vs está, left, right and straight on — plus an A1 review.', array['Ask where places are', 'Understand directions', 'Review the whole A1 level']::text[], 2, 13, 90, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
