insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('44426da4-19bf-5f9c-9164-f5f1ef69d357', 'b658431a-ede9-5251-9335-211bc457a531', 0, 'grammar', '¿Dónde está…? or ¿Hay…?', '{"md":"Use **estar** for the location of a **specific** place: **¿Dónde está la estación?** (Where is the station?). Use **hay** when you don''t know if one exists: **¿Hay una farmacia por aquí?** (Is there a pharmacy around here?). Notice: **hay un/una…**, but **el/la… está**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('996d5d7c-2641-5309-a767-865d7347f03c', 'b658431a-ede9-5251-9335-211bc457a531', 1, 'grammar', 'grammar', '¿___ un supermercado por aquí?', '', '{"lang":"es"}'::jsonb, 'Asking whether one exists → hay.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('81830a57-6211-5f06-9d90-339ed0933fba', '996d5d7c-2641-5309-a767-865d7347f03c', 'Hay', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('3a83842e-6f6b-5884-bc09-846f619b6eeb', '996d5d7c-2641-5309-a767-865d7347f03c', 'Está', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('59824d9c-4bb5-5a52-9a63-bbfaac8ffd0d', '996d5d7c-2641-5309-a767-865d7347f03c', 'Es', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('996d5d7c-2641-5309-a767-865d7347f03c', '{"correct":"Hay"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('22d75af6-eb08-5cd5-bba8-10f1e2590eb5', 'b658431a-ede9-5251-9335-211bc457a531', 2, 'example', 'Giving directions', '{"items":[{"ru":"Siga todo recto.","es":"Go straight on. (usted)"},{"ru":"Gire a la derecha.","es":"Turn right. (usted)"},{"ru":"Tome la primera calle a la izquierda.","es":"Take the first street on the left. (usted)"},{"ru":"Está al lado del banco.","es":"It''s next to the bank."},{"ru":"Está enfrente de la iglesia.","es":"It''s opposite the church."},{"ru":"Está en la esquina.","es":"It''s on the corner."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9b9fc018-d12f-587b-a835-22ee88098ca7', 'b658431a-ede9-5251-9335-211bc457a531', 3, 'tip', 'Derecha or derecho?', '{"md":"**a la derecha** = to the right. **todo recto** (Spain) or **derecho** (Latin America) = straight on. They sound similar, so listen carefully! With strangers, use the usted forms: **siga, gire, tome**; with friends: **sigue, gira, toma**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('60427ded-9ccb-58a5-a9ca-72bfa78bbbd6', 'b658431a-ede9-5251-9335-211bc457a531', 4, 'match_pairs', 'vocabulary', 'Match the directions.', '', '{"left":["a la derecha","a la izquierda","todo recto","cerca","lejos"],"right":["straight on","on the left","on the right","far","near"],"lang":"es"}'::jsonb, 'The basic words for finding your way.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('60427ded-9ccb-58a5-a9ca-72bfa78bbbd6', '{"pairs":{"a la derecha":"on the right","a la izquierda":"on the left","todo recto":"straight on","cerca":"near","lejos":"far"}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('7e2a9f51-0d5b-5f7f-94ba-2b16cc8b2d4c', 'b658431a-ede9-5251-9335-211bc457a531', 5, 'dialogue', 'In the street', '{"lines":[{"speaker":"Emma","ru":"Perdone, ¿dónde está el museo?","es":"Excuse me, where is the museum?"},{"speaker":"Señor","ru":"Siga todo recto y tome la segunda calle a la izquierda. Está enfrente de la catedral.","es":"Go straight on and take the second street on the left. It''s opposite the cathedral."},{"speaker":"Emma","ru":"¿Está lejos?","es":"Is it far?"},{"speaker":"Señor","ru":"No, está a cinco minutos andando.","es":"No, it''s five minutes on foot. (Lat. Am. caminando)"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('9092e93d-7fe4-5d19-a99a-e69ff00033bc', 'b658431a-ede9-5251-9335-211bc457a531', 6, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"Gire a la izquierda.","lang":"es"}'::jsonb, 'Izquierda = left; derecha = right.', 10) on conflict (id) do nothing;
