insert into public.course_units (id, course_id, title, description, order_index, status) values ('3034d28a-ddc6-55c5-aa12-c630337a2263', '3cba6a7b-a589-5bed-b73a-b6f61e33eee1', 'Звуки и приветствия', 'Здоровайся, читай по правилам и не теряй артикли.', 0, 'published') on conflict (id) do nothing;
insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('5c992864-140f-5ed1-910c-616c4451b7b4', '3034d28a-ddc6-55c5-aa12-c630337a2263', 'esru-hola', '¡Hola! Приветствия и знакомство', 'Приветствия на любое время суток, «Me llamo…», «Mucho gusto» и прощания.', array['Здороваться и прощаться', 'Называть своё имя и спрашивать чужое', 'Отвечать на «¿Qué tal?»']::text[], 0, 10, 45, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d31dfd99-0b20-50b5-b8c2-104b0f599a46', '5c992864-140f-5ed1-910c-616c4451b7b4', 0, 'text', 'Как устроен этот курс', '{"md":"Каждый урок идёт по одному циклу: ты **понимаешь** правило (объяснение на русском), **слушаешь** живые фразы (нажми на динамик), **тренируешься** в коротких упражнениях и **говоришь** вслух в микрофон. В квадратных скобках — **произношение русскими буквами** с ударением: **Hola [о́ла]**. Буква [э] — это чистое «э» без смягчения согласного: **noches [но́чэс]**, а не «ночес»."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e16b92e1-1df6-5dfb-90ff-149b0d9d9d9b', '5c992864-140f-5ed1-910c-616c4451b7b4', 1, 'example', 'Приветствия, которые используют каждый день', '{"items":[{"ru":"¡Hola!","es":"Привет! / Здравствуйте! · [о́ла]"},{"ru":"¡Buenos días!","es":"Доброе утро! (до обеда) · [буэ́нос ди́ас]"},{"ru":"¡Buenas tardes!","es":"Добрый день! (после обеда, примерно до 20–21 ч) · [буэ́нас та́рдэс]"},{"ru":"¡Buenas noches!","es":"Добрый вечер! / Спокойной ночи! · [буэ́нас но́чэс]"},{"ru":"¡Adiós!","es":"До свидания! / Пока! · [адьо́с]"},{"ru":"¡Hasta luego!","es":"Пока! До встречи! · [а́ста луэ́го]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d2188ab1-7291-533e-99e7-37114a45793d', '5c992864-140f-5ed1-910c-616c4451b7b4', 2, 'tip', 'H не читается', '{"md":"В испанском **h всегда немая**: **hola** читается [о́ла], а не «хола». Звук «х» пишется буквой **j**: **jamón [хамо́н]**. Это самая частая ошибка русскоязычных в первый день."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d4babcb5-9edc-5d96-918b-5912f755d9cb', '5c992864-140f-5ed1-910c-616c4451b7b4', 3, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"¡Buenas tardes!","lang":"es"}'::jsonb, 'Buenas tardes [буэ́нас та́рдэс] — «добрый день» после обеда.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('43375c7f-d714-5227-8050-6aabc6773e0e', 'd4babcb5-9edc-5d96-918b-5912f755d9cb', '¡Buenas tardes!', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('64d22ae4-8bc4-5c60-9f5d-62f48a672687', 'd4babcb5-9edc-5d96-918b-5912f755d9cb', '¡Buenas noches!', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b2fbfb61-dea8-51e0-80b9-bcdafdd7b381', 'd4babcb5-9edc-5d96-918b-5912f755d9cb', '¡Buenos días!', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('d4babcb5-9edc-5d96-918b-5912f755d9cb', '{"correct":"¡Buenas tardes!"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a5013e1f-7610-5ab0-8cfb-c6a254e56ea8', '5c992864-140f-5ed1-910c-616c4451b7b4', 4, 'grammar', 'Как тебя зовут?', '{"md":"Спросить имя: **¿Cómo te llamas? [ко́мо тэ я́мас]** (буквально «Как ты себя называешь?»). Ответ: **Me llamo Iván. [мэ я́мо иба́н]** Можно короче: **Soy Iván.** (Я Иван). При знакомстве говорят **Mucho gusto [му́чо гу́сто]** или **Encantado / Encantada** — мужчина говорит *encantado*, женщина *encantada*. Перевёрнутый знак **¿** в начале вопроса в испанском обязателен."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('74c3fdcc-e145-50dd-ae41-0479e16ae73c', '5c992864-140f-5ed1-910c-616c4451b7b4', 5, 'dialogue', 'Знакомство в языковой школе', '{"lines":[{"speaker":"Lucía","ru":"¡Hola! Me llamo Lucía. ¿Y tú? ¿Cómo te llamas?","es":"Привет! Меня зовут Люсия. А тебя? Как тебя зовут?"},{"speaker":"Iván","ru":"Hola, Lucía. Me llamo Iván.","es":"Привет, Люсия. Меня зовут Иван."},{"speaker":"Lucía","ru":"Mucho gusto, Iván.","es":"Очень приятно, Иван."},{"speaker":"Iván","ru":"Encantado.","es":"Взаимно. (букв. «очарован»)"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('eb9e5537-245d-5c9a-bce9-58c5002fd4d5', '5c992864-140f-5ed1-910c-616c4451b7b4', 6, 'multiple_choice', 'vocabulary', 'Тебя зовут Марина, и тебя знакомят с новым коллегой. Что ты скажешь?', '', '{"lang":"es"}'::jsonb, 'Женщина говорит encantada (окончание -a), мужчина — encantado.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e6c54efc-2602-5a28-a9c2-eedb5c4fc612', 'eb9e5537-245d-5c9a-bce9-58c5002fd4d5', 'Encantada.', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('a80be03b-258b-57f3-9e9e-9c2e8816b70d', 'eb9e5537-245d-5c9a-bce9-58c5002fd4d5', 'Encantado.', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('9349b8bf-4419-58cc-8ba6-38d378d98e4f', 'eb9e5537-245d-5c9a-bce9-58c5002fd4d5', 'Adiós.', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('eb9e5537-245d-5c9a-bce9-58c5002fd4d5', '{"correct":"Encantada."}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8438e44b-5767-5044-b664-7533544f6b06', '5c992864-140f-5ed1-910c-616c4451b7b4', 7, 'grammar', '¿Qué tal? — Как дела?', '{"md":"**¿Qué tal? [кэ таль]** — почти приветствие: отвечают коротко и возвращают вопрос. **Bien, gracias. ¿Y tú? [бьен, гра́сьяс. и ту]** · **Muy bien** (очень хорошо) · **Regular** (так себе) · **Fatal** (ужасно). Вежливый вариант: **¿Cómo está usted?** (Как вы поживаете?)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('511fb8d8-e8e5-5ddb-a756-12bf3c88d8d1', '5c992864-140f-5ed1-910c-616c4451b7b4', 8, 'tip', 'Ты или вы: tú и usted', '{"md":"**Tú** — «ты», **usted [устэ́д]** — вежливое «вы» одному человеку. В Испании на «ты» говорят гораздо чаще, чем у нас: с коллегами, ровесниками, часто даже с продавцами. **Usted** — для пожилых людей и официальных ситуаций. Важно: **usted** спрягается как «он / она»: **¿Cómo está usted?**, а не «¿Cómo estás usted?»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e64a6de2-6d0b-5fb5-b1f2-ef617f218e65', '5c992864-140f-5ed1-910c-616c4451b7b4', 9, 'match_pairs', 'vocabulary', 'Соедини фразу и её значение.', '', '{"left":["¿Qué tal?","Hasta luego","Mucho gusto","Gracias"],"right":["Пока, до встречи","Как дела?","Спасибо","Очень приятно"],"lang":"es"}'::jsonb, 'Фразы приветствия и прощания.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e64a6de2-6d0b-5fb5-b1f2-ef617f218e65', '{"pairs":{"¿Qué tal?":"Как дела?","Hasta luego":"Пока, до встречи","Mucho gusto":"Очень приятно","Gracias":"Спасибо"}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('fe013683-2194-5533-b358-9f3ff47a3399', '5c992864-140f-5ed1-910c-616c4451b7b4', 10, 'true_false', 'speaking', 'Верно или неверно?', '«Hola» читается [хо́ла].', '{"lang":"es"}'::jsonb, 'Буква h в испанском немая: [о́ла].', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('fe013683-2194-5533-b358-9f3ff47a3399', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
