insert into public.exercise_solutions (exercise_id, solution) values ('94a3c1b7-58ca-5e8f-8750-af0f6dda551c', '{"accepted":["Bien gracias y tú"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('dad63c7c-d85e-5f7c-914c-4eaec7556e1a', '5c992864-140f-5ed1-910c-616c4451b7b4', 12, 'translate', 'writing', 'Напиши по-испански: «Меня зовут Анна».', '', '{"keyboard":true,"lang":"es"}'::jsonb, 'Me llamo Ana. По-испански это имя обычно пишется с одной n.', 10) on conflict (id) do nothing;
