insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('72ca9f2a-a78a-5454-9be4-ee3e77b79133', '5c992864-140f-5ed1-910c-616c4451b7b4', 13, 'pronunciation', 'speaking', 'Представься вслух: «Привет, меня зовут Иван. Очень приятно».', '', '{"audio_text":"Hola, me llamo Iván. Mucho gusto.","lang":"es"}'::jsonb, '[о́ла, мэ я́мо иба́н. му́чо гу́сто]. Можешь назвать своё имя.', 10) on conflict (id) do nothing;
