insert into public.exercise_options (id, exercise_id, label, order_index) values ('cb0bc501-d6a2-5ec9-9876-45eb68531531', 'ffbfb029-352b-5ca0-a1e8-f9aab5bd3173', 'доброе утро', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('720841ed-eef6-522c-9655-2fd7f01bbf63', 'ffbfb029-352b-5ca0-a1e8-f9aab5bd3173', 'добрый вечер; спокойной ночи', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('ffbfb029-352b-5ca0-a1e8-f9aab5bd3173', '{"correct":"доброе утро"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5c846562-a273-5e7d-a456-5d509c61974f', '1678c454-3f68-5341-8f94-8351d0bb6b77', 0, 'text', 'Хорошая новость', '{"md":"Испанский читается **почти так, как пишется**: выучив правила, ты прочитаешь любое слово. Гласных всего **пять — a, e, i, o, u**, и они всегда звучат ясно. Но у русскоязычных есть несколько привычек, которые выдают акцент. Разберём их по порядку."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1f5b608e-5c87-5f5e-b3c4-a83e7dda4a4f', '1678c454-3f68-5341-8f94-8351d0bb6b77', 1, 'grammar', '1 · Гласные не «акают»', '{"md":"В русском безударное **о** звучит как «а»: «м**а**локо». В испанском **o всегда «о»**, а **e всегда «э»**, даже без ударения: **bonito [бони́то]**, а не «банита»; **noche [но́чэ]**, а не «ночи». Согласные перед **e** и **i** не смягчаются: **te [тэ]**, **de [дэ]**, а не «тё», «де»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('c241fa8e-b72b-578f-a870-b77095e1f59c', '1678c454-3f68-5341-8f94-8351d0bb6b77', 2, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"bonito","lang":"es"}'::jsonb, 'bonito [бони́то] — «красивый». Оба «о» звучат чётко.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('547f0627-d2e5-5fdf-a6c5-eeb1141b24df', 'c241fa8e-b72b-578f-a870-b77095e1f59c', 'bonito', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c34aa0ce-ed99-556c-b48d-9f339b88080c', 'c241fa8e-b72b-578f-a870-b77095e1f59c', 'banito', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('6eff89e4-efc8-5e67-a0ba-c4260495ee4c', 'c241fa8e-b72b-578f-a870-b77095e1f59c', 'bonita', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('c241fa8e-b72b-578f-a870-b77095e1f59c', '{"correct":"bonito"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('52f42e02-cc59-5bb0-9440-fa17b6c5c8b4', '1678c454-3f68-5341-8f94-8351d0bb6b77', 3, 'grammar', '2 · R и RR', '{"md":"**r** между гласными — **одно** короткое касание языка: **pero [пэ́ро]** (но). **rr**, а также **r в начале слова** — раскатистая, несколько ударов: **perro [пэ́рро]** (собака), **Rusia [ру́сья]**. Русское «р» где-то посередине: для **r** его нужно укоротить до одного удара, для **rr** — раскатить сильнее. Ещё пары: **caro** (дорогой) — **carro** (тележка), **cero** (ноль) — **cerro** (холм)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('633c5aed-0ed7-5be1-8be4-6f2482c546ad', '1678c454-3f68-5341-8f94-8351d0bb6b77', 4, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"perro","lang":"es"}'::jsonb, 'perro [пэ́рро] с раскатом — собака; pero — «но».', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('36a8ecfd-89fd-5962-9ca6-6d75eac8fb54', '633c5aed-0ed7-5be1-8be4-6f2482c546ad', 'perro', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ed963be7-dc9e-5034-ac25-1730da0fd31b', '633c5aed-0ed7-5be1-8be4-6f2482c546ad', 'pero', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('633c5aed-0ed7-5be1-8be4-6f2482c546ad', '{"correct":"perro"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e800456a-05ed-5c01-ba5e-29020a3b2d4c', '1678c454-3f68-5341-8f94-8351d0bb6b77', 5, 'grammar', '3 · B и V звучат одинаково', '{"md":"В испанском **b** и **v** — **один и тот же звук**. В начале фразы и после **m, n** это чёткое [б]: **vino [би́но]** (вино), **Valencia [бале́нсья]**. Между гласными губы почти не смыкаются — получается мягкое «б», похожее на «в»: **Cuba, uva** (виноград). Русского «в» с зубами на губе в испанском нет. Поэтому при диктовке уточняют: «b de Barcelona» или «v de Valencia»."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a4756dde-7bf4-5fa2-98a1-bfe90e132894', '1678c454-3f68-5341-8f94-8351d0bb6b77', 6, 'grammar', '4 · J, G, LL, Ñ, H, C, Z', '{"md":"**j** (и **g** перед e, i) — как русское «х», только глубже: **jamón [хамо́н]**, **gente [хэ́нтэ]** (люди). **h** всегда немая: **hotel [отэ́ль]**. **ll** и **y** — примерно [й]: **calle [ка́йе]** (улица), **yo [йо]** (я). **ñ** — [нь]: **España [эспа́нья]**. **c** перед e, i и **z** — [с] в Латинской Америке и [θ] (как английское th) в большей части Испании: **gracias [гра́сьяс / гра́θьяс]**. Обе нормы правильные."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('453c9b87-cc3f-5ad8-99d3-787795aab0af', '1678c454-3f68-5341-8f94-8351d0bb6b77', 7, 'match_pairs', 'reading', 'Соедини слово и его чтение.', '', '{"left":["jamón","hotel","calle","España"],"right":["[отэ́ль]","[хамо́н]","[эспа́нья]","[ка́йе]"],"lang":"es"}'::jsonb, 'j = х, h немая, ll ≈ й, ñ = нь.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('453c9b87-cc3f-5ad8-99d3-787795aab0af', '{"pairs":{"jamón":"[хамо́н]","hotel":"[отэ́ль]","calle":"[ка́йе]","España":"[эспа́нья]"}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('029acc72-daea-55fc-8ceb-cfd1ef5cd6b5', '1678c454-3f68-5341-8f94-8351d0bb6b77', 8, 'grammar', '5 · Ударение: три правила', '{"md":"1) Слово на **гласную, n или s** — ударение на **предпоследний** слог: **casa [ка́са]**, **hablan [а́блан]**. 2) Слово на **другую согласную** — на **последний**: **hablar [абла́р]**, **hotel [отэ́ль]**. 3) Если ударение нарушает эти правила, над гласной пишут **знак ударения (´)** — по-испански он называется **tilde**, и дальше мы будем звать его «тильда»: **café [кафэ́]**, **música [му́сика]**, **teléfono [тэлэ́фоно]**. Тильда меняет смысл: **papá** — папа, **papa** — картошка (в Латинской Америке)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b601a122-d4f5-58ce-bba7-127947282cb1', '1678c454-3f68-5341-8f94-8351d0bb6b77', 9, 'multiple_choice', 'reading', 'Где ударение в слове «hablar»?', '', '{"lang":"es"}'::jsonb, 'Слово кончается на r (не на гласную, n или s) → ударение на последний слог.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('5d869731-fa1b-587f-8e70-9eea343a7e25', 'b601a122-d4f5-58ce-bba7-127947282cb1', 'На последнем слоге: [абла́р]', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('0e26d0b6-2313-5453-83e6-c0bf8e398e70', 'b601a122-d4f5-58ce-bba7-127947282cb1', 'На первом слоге: [а́блар]', 1) on conflict (id) do nothing;
