insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e81ad150-4b6f-520a-adc7-b2379c7578fc', '1678c454-3f68-5341-8f94-8351d0bb6b77', 10, 'true_false', 'reading', 'Верно или неверно?', 'В слове «música» ударение падает на «u», потому что над ней стоит тильда.', '{"lang":"es"}'::jsonb, 'Тильда всегда показывает ударный слог: [му́сика].', 10) on conflict (id) do nothing;
