insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('236085fd-6268-58b4-80f2-c965beb5e104', '1678c454-3f68-5341-8f94-8351d0bb6b77', 11, 'pronunciation', 'speaking', 'Скажи с раскатом: «perro, Rusia, guitarra».', '', '{"audio_text":"Perro, Rusia, guitarra","lang":"es"}'::jsonb, '[пэ́рро, ру́сья, гита́рра]. Кончик языка вибрирует несколько раз.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('236085fd-6268-58b4-80f2-c965beb5e104', '{"accepted":["perro rusia guitarra","~perro","~rusia"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('6f391f9f-da64-5f08-a904-c674c07f6294', '1678c454-3f68-5341-8f94-8351d0bb6b77', 12, 'pronunciation', 'speaking', 'Прочитай чисто, без «аканья»: «Me llamo Olga. Hablo ruso y un poco de español».', '', '{"audio_text":"Me llamo Olga. Hablo ruso y un poco de español.","lang":"es"}'::jsonb, '[мэ я́мо о́льга. а́бло ру́со и ун по́ко дэ эспаньо́ль]. Каждое «о» — настоящее «о».', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('6f391f9f-da64-5f08-a904-c674c07f6294', '{"accepted":["me llamo olga hablo ruso y un poco de español","~hablo ruso","~un poco de español"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('11d3c028-6136-53cf-aeb8-4b26ce31060f', '1678c454-3f68-5341-8f94-8351d0bb6b77', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
