insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('1ff99157-6e30-53a5-a067-14bfeb121305', '3034d28a-ddc6-55c5-aa12-c630337a2263', 'esru-articulos', 'El, la, un, una: артикли и род', 'Зачем нужны артикли, как определить род и как образовать множественное число.', array['Ставить el, la, un, una', 'Определять род существительного', 'Образовывать множественное число']::text[], 2, 12, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2ddf250d-eea2-544f-b8ff-e1890918a2f4', '1ff99157-6e30-53a5-a067-14bfeb121305', -100, 'tip', '🔁 Разминка', '{"md":"Перед началом **вспомни** два слова из прошлых уроков. Вспоминать как раз тогда, когда слово начинает забываться, — лучший способ его закрепить."}'::jsonb) on conflict (id) do nothing;
