insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('04b94764-78c2-57ad-9009-a448f624495d', '1ff99157-6e30-53a5-a067-14bfeb121305', -98, 'multiple_choice', 'vocabulary', 'Что значит «pero»?', '', '{"lang":"es"}'::jsonb, '«pero» = но.', 10) on conflict (id) do nothing;
