insert into public.exercise_solutions (exercise_id, solution) values ('04b94764-78c2-57ad-9009-a448f624495d', '{"correct":"но"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6c6bd36e-b239-5940-b842-b68d7f2edf40', '1ff99157-6e30-53a5-a067-14bfeb121305', 0, 'text', 'Слово, которого нет в русском', '{"md":"В русском нет артиклей, поэтому для нас это главная трудность. В испанском перед существительным почти всегда стоит маленькое слово: **un libro** — какая-то книга, одна из многих; **el libro** — та самая, известная книга. Фраза без артиклей звучит как телеграмма: «Libro está en mesa» — ошибка. Правильно: **El libro está en la mesa.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('13ef86d6-c7c8-54a0-806b-6618a47eb30d', '1ff99157-6e30-53a5-a067-14bfeb121305', 1, 'table', 'Артикли', '{"caption":"unos / unas = «несколько, какие-то».","headers":["","Мужской род","Женский род"],"rows":[["Определённый (тот самый)","el libro · los libros","la mesa · las mesas"],["Неопределённый (какой-то, один)","un libro · unos libros","una mesa · unas mesas"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('208830ca-3934-5737-b392-76073ce67d02', '1ff99157-6e30-53a5-a067-14bfeb121305', 2, 'grammar', 'Un или el?', '{"md":"**Un / una** — когда предмет упоминается впервые или он «один из»: **Hay un gato en la calle.** (На улице кот). **El / la** — когда понятно, о чём речь, или предмет единственный: **El gato es negro.** (Этот кот чёрный). **el sol**, **la luna**. Ещё **el / la** нужен, когда говоришь о чём-то вообще: **Me gusta el café.** (Я люблю кофе)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f457a7e3-99db-5f71-8a0b-58996a20402c', '1ff99157-6e30-53a5-a067-14bfeb121305', 3, 'grammar', 'grammar', 'Вставь артикли: «Tengo ___ hermano y ___ hermana».', '', '{"lang":"es"}'::jsonb, 'Брат и сестра упоминаются впервые → неопределённый артикль: un hermano (м. р.), una hermana (ж. р.).', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('291b7b6a-0e1d-58c0-8bc5-c35e993190dd', 'f457a7e3-99db-5f71-8a0b-58996a20402c', 'un / una', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e9dd3032-10a0-59cb-a594-acb4c783ff49', 'f457a7e3-99db-5f71-8a0b-58996a20402c', 'el / la', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('18d74be3-b95c-5079-bc37-4ecec27fbf8c', 'f457a7e3-99db-5f71-8a0b-58996a20402c', 'una / un', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f457a7e3-99db-5f71-8a0b-58996a20402c', '{"correct":"un / una"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('44d2c217-5d63-5256-ae4f-58cd922e762a', '1ff99157-6e30-53a5-a067-14bfeb121305', 4, 'grammar', 'Как узнать род', '{"md":"Обычно на **-o** — мужской (**el libro**), на **-a** — женский (**la casa**). На **-ción** и **-dad** — женский: **la estación**, **la ciudad**. Исключения надо запомнить: **el día** (день), **el problema**, **el mapa**, **el idioma** — мужской род; **la mano** (рука), **la foto** — женский. Среднего рода у существительных в испанском нет."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8a7b5481-4f0a-564d-afb9-c77774ea82db', '1ff99157-6e30-53a5-a067-14bfeb121305', 5, 'tip', 'Род не совпадает с русским', '{"md":"Не переноси род из русского! **el coche** (машина — у нас «она»), **la leche** (молоко — у нас «оно»), **el mar** (море), **la nariz** (нос), **el árbol** (дерево). Совет: учи слово сразу с артиклем — **la leche**, а не просто «leche»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5ada2f1e-c964-54d6-93ec-3ce85f9b879c', '1ff99157-6e30-53a5-a067-14bfeb121305', 6, 'grammar', 'grammar', '___ leche está fría.', '', '{"lang":"es"}'::jsonb, 'leche — женского рода: la leche, хотя «молоко» по-русски среднего.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ba573d2d-c58f-50c5-80c8-d8a6946a9c9d', '5ada2f1e-c964-54d6-93ec-3ce85f9b879c', 'La', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('6ddc620a-719e-5765-b61d-af006895072d', '5ada2f1e-c964-54d6-93ec-3ce85f9b879c', 'El', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('cd707ba3-b432-5276-8a1f-3b0519c1c87c', '5ada2f1e-c964-54d6-93ec-3ce85f9b879c', 'Lo', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('5ada2f1e-c964-54d6-93ec-3ce85f9b879c', '{"correct":"La"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('df65848c-4855-5c05-977a-b2b442a4b5ed', '1ff99157-6e30-53a5-a067-14bfeb121305', 7, 'grammar', 'Множественное число', '{"md":"После гласной добавь **-s**: **casa → casas**. После согласной — **-es**: **ciudad → ciudades**, **hotel → hoteles**. На **-z** → **-ces**: **lápiz → lápices**. Артикль тоже меняется: **el → los**, **la → las**. Смешанная группа — мужской род: **los niños** = дети (мальчики и девочки)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('48ccd934-0fc1-515e-8360-ae9ba8a521a9', '1ff99157-6e30-53a5-a067-14bfeb121305', 8, 'fill_blank', 'grammar', 'Напиши множественное число: el hotel → los ___', '', '{"sentence":"los ___","keyboard":true,"lang":"es"}'::jsonb, 'После согласной добавляем -es: hoteles.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('48ccd934-0fc1-515e-8360-ae9ba8a521a9', '{"accepted":["hoteles"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('dcf97076-0ee8-5222-b63e-57ebe60572e7', '1ff99157-6e30-53a5-a067-14bfeb121305', 9, 'match_pairs', 'grammar', 'Соедини единственное и множественное число.', '', '{"left":["el día","la mano","la ciudad","el lápiz"],"right":["las manos","los días","los lápices","las ciudades"],"lang":"es"}'::jsonb, '-s после гласной, -es после согласной, z → c.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('dcf97076-0ee8-5222-b63e-57ebe60572e7', '{"pairs":{"el día":"los días","la mano":"las manos","la ciudad":"las ciudades","el lápiz":"los lápices"}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('56369090-ed6e-51e1-805d-131f69b3cdad', '1ff99157-6e30-53a5-a067-14bfeb121305', 10, 'true_false', 'grammar', 'Верно или неверно?', 'Слово «problema» женского рода, потому что оканчивается на -a.', '{"lang":"es"}'::jsonb, 'Это исключение: el problema. Так же el día, el mapa, el idioma.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('56369090-ed6e-51e1-805d-131f69b3cdad', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('dbf879bf-1851-5992-be31-e12897d65061', '1ff99157-6e30-53a5-a067-14bfeb121305', 11, 'reading_comprehension', 'reading', 'Что на улице Анны новое?', '', '{"text":"En la calle de Ana hay un hotel, una farmacia y dos cafés. La farmacia es nueva y los cafés son muy bonitos.","lang":"es"}'::jsonb, 'La farmacia es nueva — аптека новая.', 10) on conflict (id) do nothing;
