insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('53ae8bb5-edd3-542e-be0e-c97780d626a7', '1ff99157-6e30-53a5-a067-14bfeb121305', 13, 'pronunciation', 'speaking', 'Скажи с артиклями: «la leche, el coche, el día, la mano».', '', '{"audio_text":"La leche, el coche, el día, la mano.","lang":"es"}'::jsonb, '[ла лэ́чэ, эль ко́чэ, эль ди́а, ла ма́но]. Произноси слово вместе с артиклем — так род запомнится сам.', 10) on conflict (id) do nothing;
