insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('20fe713e-a2f5-579d-939a-447f9d35e105', '1ff99157-6e30-53a5-a067-14bfeb121305', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
