insert into public.exercise_solutions (exercise_id, solution) values ('9f52f320-2e43-52ab-aa07-8f013012e24c', '{"correct":"до свидания, пока"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ea4653ee-67b7-5f63-a53a-0988617e2e12', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 0, 'text', 'В испанском нужен глагол «быть»', '{"md":"По-русски мы говорим «Я студент», «Она из Москвы» — без глагола. В испанском глагол-связка **обязателен**: **Soy estudiante.** · **Ella es de Moscú.** А вот местоимение, наоборот, часто опускают: окончание глагола уже показывает, кто действует. **Soy Olga** звучит естественнее, чем «Yo soy Olga»."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b788def2-8261-5667-a670-52c37f2686dd', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 1, 'table', 'Ser в настоящем времени', '{"caption":"Vosotros используют только в Испании; в Латинской Америке к группе всегда обращаются ustedes.","headers":["Местоимение","Ser","Перевод"],"rows":[["yo","soy","я"],["tú","eres","ты"],["él / ella / usted","es","он / она / вы"],["nosotros / nosotras","somos","мы"],["vosotros / vosotras","sois","вы (группа, в Испании)"],["ellos / ellas / ustedes","son","они / вы (группа)"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('56597d1b-6ae0-5dc0-963d-b66e83bfc2d0', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 2, 'grammar', 'grammar', 'Ella ___ de Rusia.', '', '{"lang":"es"}'::jsonb, 'él / ella / usted → es.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('fdb86ec7-24c9-59d8-a17a-a5f627603dad', '56597d1b-6ae0-5dc0-963d-b66e83bfc2d0', 'es', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('77b87512-00cb-5618-93dd-0c4e56dabab5', '56597d1b-6ae0-5dc0-963d-b66e83bfc2d0', 'eres', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('520658a9-cc80-59b5-bf8f-543f17d09385', '56597d1b-6ae0-5dc0-963d-b66e83bfc2d0', 'son', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('56597d1b-6ae0-5dc0-963d-b66e83bfc2d0', '{"correct":"es"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('3e988dcf-a000-544b-9a24-df5a80162b69', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 3, 'grammar', 'Откуда ты: ser de', '{"md":"**¿De dónde eres? [дэ до́ндэ э́рэс]** — **Soy de Rusia.** / **Soy de San Petersburgo.** Национальность тоже с **ser**, и она меняется по роду: **Soy ruso** (говорит мужчина) / **Soy rusa** (женщина). Национальности и языки пишутся **с маленькой буквы**, как в русском: **ruso, español**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b0f1f59b-2967-5fdb-9d17-e0d58f0af522', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 4, 'table', 'Страна и национальность', '{"caption":"Если слово кончается на согласную, добавляем -a: español → española. Тильда при этом может исчезнуть: alemán → alemana.","headers":["Страна","Он","Она"],"rows":[["Rusia","ruso","rusa"],["España","español","española"],["México","mexicano","mexicana"],["Ucrania","ucraniano","ucraniana"],["Kazajistán","kazajo","kazaja"],["Alemania","alemán","alemana"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5c5fd796-93ea-50f5-ba9b-99daa4026fdb', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 5, 'grammar', 'grammar', 'Марина из России: «Marina es ___.»', '', '{"lang":"es"}'::jsonb, 'Марина — одна женщина → rusa (и с маленькой буквы).', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('2e10be8a-97b5-5deb-96f7-068e412d44fe', '5c5fd796-93ea-50f5-ba9b-99daa4026fdb', 'rusa', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('11db5f5e-c1fd-5e82-9fd8-962829037555', '5c5fd796-93ea-50f5-ba9b-99daa4026fdb', 'ruso', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('43dd0676-bb40-5dbb-963b-133681f54230', '5c5fd796-93ea-50f5-ba9b-99daa4026fdb', 'rusos', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('5c5fd796-93ea-50f5-ba9b-99daa4026fdb', '{"correct":"rusa"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('42766811-383f-5521-862c-b77f461b3d71', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 6, 'grammar', 'Профессия — без артикля', '{"md":"О профессии говорят с **ser** и **без артикля**: **Soy médico.** (Я врач). **Ella es profesora.** Артикль появляется, только если есть описание: **Es un médico muy bueno.** (Он очень хороший врач). Профессии меняются по роду: **profesor / profesora**, **médico / médica**, но **estudiante**, **periodista** одинаковы для обоих."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e5aed5d2-97fc-5602-b3d8-4f1595d09e5e', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 7, 'dialogue', 'На вечеринке', '{"lines":[{"speaker":"Carlos","ru":"¿De dónde eres?","es":"Откуда ты?"},{"speaker":"Olga","ru":"Soy de Rusia, de Kazán. ¿Y tú?","es":"Я из России, из Казани. А ты?"},{"speaker":"Carlos","ru":"Soy de Valencia. ¿Eres estudiante?","es":"Я из Валенсии. Ты студентка?"},{"speaker":"Olga","ru":"No, soy ingeniera. Trabajo en una empresa española.","es":"Нет, я инженер. Работаю в испанской компании."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('17d3ac37-d729-502e-b2bd-d9375e763679', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 8, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"Soy de Rusia.","lang":"es"}'::jsonb, 'Soy — «я есть». Обрати внимание на раскатистую r в начале слова Rusia.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('56cbffde-f0d6-50bf-a732-15dada2da44c', '17d3ac37-d729-502e-b2bd-d9375e763679', 'Soy de Rusia.', 0) on conflict (id) do nothing;
