insert into public.exercise_options (id, exercise_id, label, order_index) values ('21558bf5-4d39-50c3-a32e-778d4ef7f622', '17d3ac37-d729-502e-b2bd-d9375e763679', 'Sois de Rusia.', 2) on conflict (id) do nothing;
