insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('df54d0f8-d498-52b1-a1ea-2a3dd7199151', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 9, 'true_false', 'grammar', 'Верно или неверно?', '«Es una profesora» — естественный ответ на вопрос «Кто она по профессии?».', '{"lang":"es"}'::jsonb, 'О профессии говорят без артикля: Es profesora.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('df54d0f8-d498-52b1-a1ea-2a3dd7199151', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('89d3a6f9-8f0f-56a9-b42d-afc402a9f8b5', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 10, 'tip', 'Отрицание — просто no', '{"md":"Отрицание ставится **перед глаголом**, как «не» в русском: **No soy español. No es médico.** В ответе на вопрос «да / нет» получается два no: **No, no soy de Moscú.** Первое значит «нет», второе — «не»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('55cee1a8-fbc4-5f28-b0ec-39db7fb0011b', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 11, 'order_words', 'grammar', 'Составь фразу: «Я не испанец, я русский».', '', '{"tokens":["español","soy","No","ruso","soy"],"lang":"es"}'::jsonb, 'No soy español, soy ruso.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('55cee1a8-fbc4-5f28-b0ec-39db7fb0011b', '{"accepted":["No soy español soy ruso"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('c43cf0db-5c24-5690-bd7b-f80b3096e2d7', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 12, 'translate', 'writing', 'Напиши по-испански: «Она врач».', '', '{"keyboard":true,"lang":"es"}'::jsonb, 'Es médica (или es doctora). Без артикля!', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('c43cf0db-5c24-5690-bd7b-f80b3096e2d7', '{"accepted":["es medica","ella es medica","es doctora","ella es doctora"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b9290d8e-f799-5641-9711-4b220eb7d61c', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 13, 'pronunciation', 'speaking', 'Расскажи о себе: «Я из России. Я инженер».', '', '{"audio_text":"Soy de Rusia. Soy ingeniero.","lang":"es"}'::jsonb, '[сой дэ ру́сья. сой инхэнье́ро]. Женщина скажет «ingeniera».', 10) on conflict (id) do nothing;
