insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e6d7efa3-8342-531d-9168-82682954378f', 'e3eefa59-f50a-5606-8b25-45809e6357ce', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
