insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('623cc82b-17cc-5695-af73-c4fd632e11be', '9722f17a-bdc8-508a-bbe7-302c5e8dec2d', 'esru-estar', 'Estar: как ты и где ты', 'Estar для места и состояния и главное правило: ser или estar.', array['Спрягать estar', 'Говорить, где что находится и как ты себя чувствуешь', 'Выбирать между ser и estar']::text[], 1, 13, 80, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('374df789-6172-5288-91b9-f9efd6c32e24', '623cc82b-17cc-5695-af73-c4fd632e11be', -100, 'tip', '🔁 Разминка', '{"md":"Перед началом **вспомни** два слова из прошлых уроков. Вспоминать как раз тогда, когда слово начинает забываться, — лучший способ его закрепить."}'::jsonb) on conflict (id) do nothing;
