insert into public.exercise_solutions (exercise_id, solution) values ('f60aba52-795b-5c66-8ab0-93d0705c24e1', '{"correct":"Испания"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b861d908-cc19-579e-b1a7-8c32189bf66e', '623cc82b-17cc-5695-af73-c4fd632e11be', 0, 'text', 'Два глагола вместо одного «быть»', '{"md":"В испанском «быть» — это два глагола. **Ser** отвечает на вопрос «**кто это, какое оно по сути?**» (имя, происхождение, профессия, характер). **Estar** — «**где это и в каком состоянии сейчас?**». Для русскоязычных это главная тема уровня A1, поэтому разберём её подробно."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cbaec557-fea2-5cb3-b2b2-46aa4f32a7dc', '623cc82b-17cc-5695-af73-c4fd632e11be', 1, 'table', 'Estar в настоящем времени', '{"caption":"Ударение на последнем слоге: estás [эста́с], está [эста́]. Не забывай тильду: esta (эта) и está (находится) — разные слова.","headers":["Местоимение","Estar"],"rows":[["yo","estoy"],["tú","estás"],["él / ella / usted","está"],["nosotros / nosotras","estamos"],["vosotros / vosotras","estáis"],["ellos / ellas / ustedes","están"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('7e705bb5-5f19-5aca-a50f-37421d0442c1', '623cc82b-17cc-5695-af73-c4fd632e11be', 2, 'grammar', 'Где: estar + место', '{"md":"Местонахождение — всегда **estar**: **Estoy en casa.** (Я дома). **¿Dónde está el baño?** (Где туалет?). Даже если место постоянное, как город на карте: **Madrid está en España.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cfaae75a-12bf-5207-9074-939bf6a951d5', '623cc82b-17cc-5695-af73-c4fd632e11be', 3, 'grammar', 'Как: estar + состояние', '{"md":"Временное состояние и самочувствие — **estar**: **Estoy cansado.** (Я устал). **¿Estás bien?** (Ты в порядке?). **La sopa está fría.** (Суп остыл). А постоянные качества и характер — **ser**: **Es alto.** (Он высокий). **Es simpática.** (Она приятная)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5f7edb9a-413f-531a-b961-3c787f0a71ac', '623cc82b-17cc-5695-af73-c4fd632e11be', 4, 'table', 'Ser или estar', '{"caption":"Одно прилагательное — разный смысл!","headers":["Ser — суть","Estar — состояние, место"],"rows":[["Soy de Moscú.","Estoy en Madrid."],["Es profesor.","Está cansado."],["Es alegre. (весёлый по характеру)","Está alegre. (сейчас радуется)"],["Es aburrido. (он скучный человек)","Está aburrido. (ему скучно)"],["Es listo. (он умный)","Está listo. (он готов)"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('722ce5b7-bd0c-5f76-9614-51cd849c6862', '623cc82b-17cc-5695-af73-c4fd632e11be', 5, 'tip', 'Ловушка: aburrido и listo', '{"md":"**Es aburrido** — «он зануда», а **está aburrido** — «ему скучно». **Es listo** — «он умный», **está listo** — «он готов». Перепутаешь — можешь случайно обидеть человека."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('75ac3892-55cd-51ac-b598-ad8e0cd747a9', '623cc82b-17cc-5695-af73-c4fd632e11be', 6, 'grammar', 'grammar', '«Мне скучно» (говорит женщина): «___ aburrida.»', '', '{"lang":"es"}'::jsonb, 'Состояние сейчас → estar. «Soy aburrida» значило бы «я скучная (как человек)».', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('46c82e57-6627-5de4-b9e0-cbd601a82ee9', '75ac3892-55cd-51ac-b598-ad8e0cd747a9', 'Estoy', 0) on conflict (id) do nothing;
