insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d69ac4c4-4853-591e-a504-7cbfdbc392fd', '623cc82b-17cc-5695-af73-c4fd632e11be', 8, 'dialogue', 'Телефонный звонок', '{"lines":[{"speaker":"Pablo","ru":"¡Hola, Nadia! ¿Dónde estás?","es":"Привет, Надя! Ты где?"},{"speaker":"Nadia","ru":"Estoy en el hotel. Estoy un poco cansada.","es":"Я в гостинице. Немного устала."},{"speaker":"Pablo","ru":"¿Estás bien?","es":"Ты в порядке?"},{"speaker":"Nadia","ru":"Sí, sí. El hotel es muy bonito y está cerca del centro.","es":"Да-да. Отель очень красивый и находится рядом с центром."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('fe7a1cea-b908-59fc-857e-829755a01b3d', '623cc82b-17cc-5695-af73-c4fd632e11be', 9, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"Estoy cansada.","lang":"es"}'::jsonb, 'cansada — уставшая; casada — замужем. Прислушайся к звуку n.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('5b64da79-2109-5eb5-9225-9c1714bbe7bd', 'fe7a1cea-b908-59fc-857e-829755a01b3d', 'Estoy cansada.', 0) on conflict (id) do nothing;
