insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('74c27318-aca5-5187-9bb7-ff615a2a7d94', '623cc82b-17cc-5695-af73-c4fd632e11be', 10, 'true_false', 'grammar', 'Верно или неверно?', '«La fiesta está en mi casa» — правильно, ведь речь о месте.', '{"lang":"es"}'::jsonb, 'Исключение: события (праздник, концерт, встреча) «проходят» где-то → ser: La fiesta es en mi casa.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('74c27318-aca5-5187-9bb7-ff615a2a7d94', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2f470ee0-799d-5c26-8314-0561be49c369', '623cc82b-17cc-5695-af73-c4fd632e11be', 11, 'reading_comprehension', 'reading', 'Где сейчас Диего?', '', '{"text":"Hola, soy Diego. Soy de Málaga, pero ahora estoy en Moscú. Estoy un poco cansado porque hace mucho frío, pero estoy muy contento.","lang":"es"}'::jsonb, 'Ahora estoy en Moscú — сейчас я в Москве. Soy de Málaga — родом из Малаги.', 10) on conflict (id) do nothing;
