insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('7ce54d43-c9fc-5d06-8b6e-2172d64a3ece', '623cc82b-17cc-5695-af73-c4fd632e11be', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
