insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9791ede1-2de4-5376-87ea-41207c6ab44d', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 0, 'example', 'От 0 до 10', '{"items":[{"ru":"cero, uno, dos","es":"0, 1, 2 · [сэ́ро, у́но, дос]"},{"ru":"tres, cuatro, cinco","es":"3, 4, 5 · [трэс, куа́тро, си́нко]"},{"ru":"seis, siete, ocho","es":"6, 7, 8 · [сэйс, сье́тэ, о́чо]"},{"ru":"nueve, diez","es":"9, 10 · [нуэ́бэ, дьес]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c806daba-cbfc-5416-b5b3-bd0d20c7e470', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 1, 'grammar', 'От 11 до 100', '{"md":"**11 once, 12 doce, 13 trece, 14 catorce, 15 quince** — их надо выучить. **16–19** пишутся одним словом: **dieciséis, diecisiete…** («десять-и-шесть»). **20 veinte**, и **21–29** тоже слитно: **veintiuno, veintidós**. Дальше — три слова через **y**: **31 treinta y uno**, **45 cuarenta y cinco**. Десятки: **30 treinta, 40 cuarenta, 50 cincuenta, 60 sesenta, 70 setenta, 80 ochenta, 90 noventa, 100 cien**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('40207332-186b-5124-a6f8-930064f3f539', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 2, 'tip', 'Sesenta или setenta', '{"md":"**sesenta (60)** и **setenta (70)** звучат похоже. В 60 — **s**, как в seis; в 70 — **t**, как в siete. Эта подсказка выручает и в магазине, и при диктовке номера."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('34cbbd57-d5cb-5f09-93a8-50b7e7341e17', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 3, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"setenta","lang":"es"}'::jsonb, 'setenta — 70 (t, как в siete).', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b7b57ba8-1698-50e0-8e21-4e7fa962c2d6', '34cbbd57-d5cb-5f09-93a8-50b7e7341e17', '70', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('6536e82f-1851-5736-8154-6beb4121ea7b', '34cbbd57-d5cb-5f09-93a8-50b7e7341e17', '60', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b67f1130-0e81-521c-ba2e-cc90441a9ac3', '34cbbd57-d5cb-5f09-93a8-50b7e7341e17', '17', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('34cbbd57-d5cb-5f09-93a8-50b7e7341e17', '{"correct":"70"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('90c7c46e-a009-5f4b-ad7a-c81ce9651d41', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 4, 'grammar', 'Возраст: «я имею» годы', '{"md":"Возраст по-испански не «мне», а **«я имею»**: **Tengo 25 años.** [тэ́нго бэйнтиси́нко а́ньос]. Вопрос: **¿Cuántos años tienes?** [куа́нтос а́ньос тье́нэс]. Типичные ошибки: «Me 25 años» или «Soy 25». И следи за **ñ**: **años** — годы, а **anos** без тильды — совсем другое, неприличное слово."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b45034dc-3972-5b38-9928-d16e9fb53a70', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 5, 'table', 'Tener — иметь', '{"caption":"Неправильный глагол: формы учим наизусть. Он же значит «у меня есть»: Tengo un hermano.","headers":["Местоимение","Tener"],"rows":[["yo","tengo"],["tú","tienes"],["él / ella / usted","tiene"],["nosotros / nosotras","tenemos"],["vosotros / vosotras","tenéis"],["ellos / ellas / ustedes","tienen"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('be5dacbe-c133-5a56-885c-8d36a3513e34', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 6, 'grammar', 'grammar', 'Моему брату 30 лет: «Mi hermano ___ 30 años.»', '', '{"lang":"es"}'::jsonb, 'Возраст → tener; mi hermano = él → tiene.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('438b284f-8437-5bc2-913b-c553225f3a87', 'be5dacbe-c133-5a56-885c-8d36a3513e34', 'tiene', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('bcebb83b-c61c-5cdf-b612-8f7105bca4b3', 'be5dacbe-c133-5a56-885c-8d36a3513e34', 'es', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('6fafe38f-1a5d-53bf-ba5b-65863582d663', 'be5dacbe-c133-5a56-885c-8d36a3513e34', 'tienes', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('be5dacbe-c133-5a56-885c-8d36a3513e34', '{"correct":"tiene"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e3f50ae7-0beb-54ac-a54f-69eb5642e824', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 7, 'true_false', 'grammar', 'Верно или неверно?', '«Soy 20 años» — правильный способ сказать «Мне 20 лет».', '{"lang":"es"}'::jsonb, 'Возраст — с tener: Tengo 20 años.', 10) on conflict (id) do nothing;
