insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d175618a-ce0f-5b5d-a64f-48ccdf04472c', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 8, 'match_pairs', 'vocabulary', 'Соедини число и слово.', '', '{"left":["15","50","60","100"],"right":["cincuenta","quince","cien","sesenta"],"lang":"es"}'::jsonb, 'Особенно внимательно: sesenta (60) и setenta (70).', 10) on conflict (id) do nothing;
