insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2eeae8cd-0e09-5214-864d-8f2dd577cc02', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 9, 'grammar', 'Номер телефона', '{"md":"Номера обычно диктуют **по одной цифре, парами или тройками**: **612 34 56 78** → **seis, uno, dos — treinta y cuatro — cincuenta y seis — setenta y ocho**. Спросить: **¿Cuál es tu número de teléfono?** Ответить: **Mi número es el…**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('fe7a1728-5480-5dda-b1d3-b6cbb9edb062', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 10, 'reading_comprehension', 'reading', 'Сколько лет Софии?', '', '{"text":"Me llamo Sofía. Tengo treinta y dos años. Mi número de teléfono es el seis, cero, cero, cuarenta y cinco, diecinueve, setenta.","lang":"es"}'::jsonb, 'treinta y dos — 32.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('dd8ec9e5-232b-59ff-a47f-d01e641fc9c9', 'fe7a1728-5480-5dda-b1d3-b6cbb9edb062', '32', 0) on conflict (id) do nothing;
