insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f0a98323-5cca-5a24-a537-a4a07fe7d4f5', '55278cef-dcc4-5eb7-9560-90d7afc22bd8', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
