insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('eeb7695c-8d99-59c4-b714-8369532c30eb', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 0, 'example', 'Семья', '{"items":[{"ru":"la madre · el padre","es":"мама · папа · [ма́дрэ, па́дрэ]"},{"ru":"los padres","es":"родители"},{"ru":"el hermano · la hermana","es":"брат · сестра · [эрма́но, эрма́на]"},{"ru":"el hijo · la hija","es":"сын · дочь · [и́хо, и́ха]"},{"ru":"el abuelo · la abuela","es":"дедушка · бабушка · [абуэ́ло, абуэ́ла]"},{"ru":"el marido · la mujer","es":"муж · жена · [мари́до, мухэ́р]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d8bd253b-545f-5f75-8d74-a1813f1a18f3', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 1, 'tip', 'Los padres и los hermanos', '{"md":"Мужской род во множественном числе включает оба пола: **los padres** — это **родители** (папа и мама), **los hermanos** — **братья и сёстры**, **los hijos** — **дети** (сыновья и дочери). Вопрос **¿Tienes hermanos?** значит «У тебя есть братья или сёстры?»."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f28aa5ad-abcf-5878-83ef-2c48519352a3', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 2, 'table', 'Притяжательные', '{"caption":"tu (твой) пишется без тильды, tú (ты) — с тильдой.","headers":["Чей","Ед. число","Мн. число"],"rows":[["мой","mi hermano","mis hermanos"],["твой","tu casa","tus casas"],["его / её / их / ваш (usted)","su padre","sus padres"],["наш","nuestro hijo · nuestra hija","nuestros hijos · nuestras hijas"],["ваш (vosotros)","vuestro · vuestra","vuestros · vuestras"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('70386d9f-8f97-598e-aacd-7239fdac2170', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 3, 'grammar', 'Su — «его», «её», «их» и «ваш»', '{"md":"**Su** многозначно: **su casa** — его, её, их или ваш дом; смысл понятен из контекста. Главное: притяжательное согласуется с **предметом**, а не с владельцем: **Ana y sus hermanos** — Ана и её братья (**sus**, потому что братьев много). Отдельного слова «свой» нет — используют те же **mi, tu, su**: **Quiero mucho a mi madre.** (Я очень люблю свою маму)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3303f591-f548-506b-841c-d0df774e19e6', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 4, 'grammar', 'grammar', 'Мои родители живут в Самаре: «___ padres viven en Samara.»', '', '{"lang":"es"}'::jsonb, 'Родителей двое → mis.', 10) on conflict (id) do nothing;
