insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('56b06222-4cd3-5309-a4b8-187041d3a1d6', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 6, 'grammar', 'Машина моего отца: de', '{"md":"Родительного падежа в испанском нет. Принадлежность выражают через **de**: **el coche de mi padre** (машина моего отца), **la casa de Ana** (дом Анны). Порядок: **что + de + чьё**. **de + el = del**: **el perro del vecino** (собака соседа)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('ddfbaeb4-e679-591f-8331-746248c5fe7f', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 7, 'fill_blank', 'grammar', '«Телефон Марии»: el teléfono ___ María', '', '{"sentence":"el teléfono ___ María","keyboard":true,"lang":"es"}'::jsonb, 'Принадлежность → de: el teléfono de María.', 10) on conflict (id) do nothing;
