insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('60964a5f-4986-5c1c-8a09-9bd98dd49ae4', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 8, 'reading_comprehension', 'reading', 'Сколько лет сыну Ирины?', '', '{"text":"Me llamo Irina. Somos cuatro en mi familia: mi marido Andréi, nuestros dos hijos y yo. Nuestra hija tiene ocho años y nuestro hijo tiene cinco. Mis padres viven en Novosibirsk.","lang":"es"}'::jsonb, 'Nuestro hijo tiene cinco — нашему сыну пять.', 10) on conflict (id) do nothing;
