insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('616b78fa-56c3-5cb3-9f2c-1f131874e563', '2c8fcb86-ec8f-59b4-831a-ee02f95dcee7', 10, 'dialogue', 'Фотографии', '{"lines":[{"speaker":"Marta","ru":"¿Quién es?","es":"Кто это?"},{"speaker":"Dima","ru":"Es mi hermana Katia. Tiene veinte años.","es":"Это моя сестра Катя. Ей двадцать лет."},{"speaker":"Marta","ru":"¿Y este chico?","es":"А этот парень?"},{"speaker":"Dima","ru":"Es su novio. Es de Perú.","es":"Это её парень. Он из Перу."}]}'::jsonb) on conflict (id) do nothing;
