insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('838a1498-464e-5a68-bb95-22ce582a7a98', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 0, 'example', 'Дом и квартира', '{"items":[{"ru":"el piso / el apartamento","es":"квартира (Испания / Латинская Америка)"},{"ru":"el salón","es":"гостиная · [сало́н]"},{"ru":"el dormitorio","es":"спальня · [дормито́рьо]"},{"ru":"la cocina","es":"кухня · [коси́на]"},{"ru":"el baño","es":"ванная, туалет · [ба́ньо]"},{"ru":"la terraza","es":"балкон, терраса"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('aabd0d12-45a4-5fa3-8055-8792472d871f', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 1, 'grammar', 'Hay — «есть, имеется»', '{"md":"**Hay [ай]** — одна форма и для единственного, и для множественного числа: **Hay un sofá.** (Есть диван). **Hay dos dormitorios.** (Две спальни). Вопрос: **¿Hay ascensor?** (Есть лифт?). Отрицание: **No hay wifi.** После **hay** ставят **un / una**, число или ничего, но **никогда el / la**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8e981993-74ac-559b-8f25-d8d82ba10b9f', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 2, 'grammar', 'Hay или está', '{"md":"**Hay** сообщает, **что** где-то есть (новая информация): **Hay un banco cerca.** (Рядом есть банк). **Está** говорит, **где** находится уже известный предмет: **El banco está en la plaza.** (Банк на площади). Сравни: «Здесь есть аптека?» → **¿Hay una farmacia por aquí?**; «Где аптека?» → **¿Dónde está la farmacia?**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3400f7c9-0a3d-5430-ba95-55df18816ae4', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 3, 'grammar', 'grammar', 'En mi calle ___ un supermercado.', '', '{"lang":"es"}'::jsonb, 'Сообщаем, что он есть (впервые, с un) → hay.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8863db4f-90fb-5c53-8477-445019fbf487', '3400f7c9-0a3d-5430-ba95-55df18816ae4', 'hay', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('0c31ee4c-3937-52e2-8764-32da5a8d1707', '3400f7c9-0a3d-5430-ba95-55df18816ae4', 'está', 1) on conflict (id) do nothing;
