insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('58d84648-c010-5b17-b466-d2582daab6ab', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 7, 'reading_comprehension', 'reading', 'Где стоит телевизор?', '', '{"text":"Mi piso es pequeño, pero muy bonito. Hay un salón, un dormitorio, una cocina y un baño. En el salón hay un sofá y una mesa. La televisión está encima de una mesa pequeña, al lado de la ventana.","lang":"es"}'::jsonb, 'Encima de una mesa pequeña, al lado de la ventana.', 10) on conflict (id) do nothing;
