insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('7d6cc1d9-4cba-5802-af77-7fd8b8d81e42', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 8, 'match_pairs', 'vocabulary', 'Соедини.', '', '{"left":["la cocina","el dormitorio","la ventana","la cama"],"right":["спальня","кухня","кровать","окно"],"lang":"es"}'::jsonb, 'Учи сразу с артиклем: la cocina, el dormitorio.', 10) on conflict (id) do nothing;
