insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2aa6b6ee-d468-5cc9-a6ca-e5b740f19b76', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 9, 'fill_blank', 'grammar', 'Вставь hay или está: «Mi casa ___ en el centro.»', '', '{"sentence":"Mi casa ___ en el centro.","keyboard":true,"lang":"es"}'::jsonb, 'Мой дом — известный предмет, говорим, где он → está.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('2aa6b6ee-d468-5cc9-a6ca-e5b740f19b76', '{"accepted":["está"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c202709d-e182-5a77-ae67-cb27631a30d3', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 10, 'tip', 'Piso: квартира или этаж', '{"md":"В Испании **piso** — это и **квартира**, и **этаж**: **Vivo en un piso en el tercer piso.** (Я живу в квартире на третьем этаже). В Латинской Америке квартиру называют **apartamento** или **departamento**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5cce79ec-8333-5317-b29b-f0d4d22c32d8', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 11, 'order_words', 'grammar', 'Составь фразу: «В квартире две спальни».', '', '{"tokens":["piso","el","En","dormitorios","dos","hay"],"lang":"es"}'::jsonb, 'En el piso hay dos dormitorios.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('5cce79ec-8333-5317-b29b-f0d4d22c32d8', '{"accepted":["En el piso hay dos dormitorios"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b5e8f91c-c32f-5138-ad50-b800066e1d38', '2f0c7ff2-62f6-527c-888c-725a01658e1e', 12, 'translate', 'writing', 'Напиши по-испански: «Где кухня?»', '', '{"keyboard":true,"lang":"es"}'::jsonb, '¿Dónde está la cocina? Известный предмет → está.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('b5e8f91c-c32f-5138-ad50-b800066e1d38', '{"accepted":["donde esta la cocina"]}'::jsonb) on conflict (exercise_id) do nothing;
