insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b4d91bfc-a76f-5adc-b207-0826bd1e6d50', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 0, 'text', 'Три группы глаголов', '{"md":"У испанских глаголов три окончания инфинитива: **-ar** (hablar — говорить), **-er** (comer — есть), **-ir** (vivir — жить). Окончание меняется по лицам, как в русском «говорю, говоришь, говорит». Поэтому местоимение можно не произносить: **Hablo ruso** — я говорю по-русски."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d6acf962-9484-53b9-bfac-fe47493a07de', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 1, 'table', 'Правильные глаголы', '{"caption":"Формы на -er и -ir различаются только в nosotros и vosotros.","headers":["","hablar","comer","vivir"],"rows":[["yo","hablo","como","vivo"],["tú","hablas","comes","vives"],["él / ella / usted","habla","come","vive"],["nosotros","hablamos","comemos","vivimos"],["vosotros","habláis","coméis","vivís"],["ellos / ustedes","hablan","comen","viven"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('8de27d57-c21f-521c-989a-f920571f6e49', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 2, 'grammar', 'grammar', 'Mi hermana ___ en Barcelona. (vivir)', '', '{"lang":"es"}'::jsonb, 'mi hermana = ella → vive.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('9a1a06d0-c7b7-5511-b904-7c09c26cff3e', '8de27d57-c21f-521c-989a-f920571f6e49', 'vive', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('905f98c5-3b37-5dd6-a293-d7b719ec758f', '8de27d57-c21f-521c-989a-f920571f6e49', 'vives', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('18a07363-84b4-5fd1-8e08-4a7c640c26f6', '8de27d57-c21f-521c-989a-f920571f6e49', 'vivo', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('8de27d57-c21f-521c-989a-f920571f6e49', '{"correct":"vive"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('13826ca6-efbc-55f9-a9fa-9deac58015da', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 3, 'grammar', 'Возвратные глаголы: -se', '{"md":"Похоже на русское «-ся»: **ducharse** (принимать душ), **acostarse** (ложиться спать), **levantarse** (вставать). Частица ставится **перед** глаголом и меняется по лицам: **me levanto, te levantas, se levanta, nos levantamos, os levantáis, se levantan**. Совпадает не всегда: «вставать» без -ся, а **levantarse** — возвратный. И **acostarse** меняет корень: **me acuesto**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b6f35dcf-0ae1-56b5-b8d0-4191d6f25e60', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 4, 'example', 'Мой обычный день', '{"items":[{"ru":"Me levanto a las siete.","es":"Я встаю в семь."},{"ru":"Desayuno café con tostadas.","es":"Завтракаю кофе с тостами."},{"ru":"Trabajo de nueve a cinco.","es":"Работаю с девяти до пяти."},{"ru":"Como a las dos.","es":"Обедаю в два."},{"ru":"Ceno a las nueve.","es":"Ужинаю в девять."},{"ru":"Me acuesto a las doce.","es":"Ложусь спать в двенадцать."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('41e7dc11-ff0e-5d2f-99ca-432412ac380a', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 5, 'tip', 'Испанское расписание', '{"md":"В Испании едят поздно: **la comida** (обед, главная еда дня) — около **14:00**, **la cena** (ужин) — в **21:00–22:00**. Поэтому **comer** значит и «есть» вообще, и «обедать»."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('58aa6d94-291b-5ce9-b59c-22b7c3289e4c', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 6, 'grammar', 'Вопрос — просто интонацией', '{"md":"Как и в русском, вопрос часто отличается только интонацией: **Hablas inglés.** → **¿Hablas inglés?** Никаких вспомогательных слов. С вопросительным словом глагол идёт сразу за ним: **¿Dónde vives?** · **¿Qué comes?** · **¿A qué hora te levantas?**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('fabad993-eccf-5cfe-a758-4236ff14e4bb', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 7, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"¿A qué hora te levantas?","lang":"es"}'::jsonb, 'levantarse — вставать; acostarse — ложиться.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('effc97f5-29bf-5e78-936e-1048fb1ed644', 'fabad993-eccf-5cfe-a758-4236ff14e4bb', 'Во сколько ты встаёшь?', 0) on conflict (id) do nothing;
