insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('550d359f-ea83-5490-a4f6-bcd1bb60f0ca', 'e42bd3cd-5b48-5187-a6d5-45df3d84b203', 9, 'reading_comprehension', 'reading', 'Когда Кармен спит?', '', '{"text":"Carmen es enfermera. Trabaja por la noche y duerme por la mañana. Por la tarde estudia inglés y lee mucho. Los domingos come con sus padres.","lang":"es"}'::jsonb, 'Duerme por la mañana — спит утром: она работает ночью.', 10) on conflict (id) do nothing;
