insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('54380cbf-645d-580f-bd16-2946b55ce6f5', 'a41701ac-623f-50d3-b0c5-96993aacefde', 0, 'grammar', 'Который час?', '{"md":"**¿Qué hora es?** — **Es la una.** (Час) — единственное число только для часа. Дальше — множественное: **Son las dos. Son las ocho.** Минуты: **y cuarto** (четверть), **y media** (половина), **menos cuarto** (без четверти): **Son las tres y media** (3:30), **Son las cinco menos cuarto** (4:45). «Во сколько?» — **¿A qué hora?** — **A las nueve.**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('cdf3f195-4fe3-514c-9b1b-14205477ccb6', 'a41701ac-623f-50d3-b0c5-96993aacefde', 1, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"Son las siete y media.","lang":"es"}'::jsonb, 'Y media — половина: семь тридцать.', 10) on conflict (id) do nothing;
