insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('29f3d37d-fad2-5733-be8e-9ebddc9367ac', 'a41701ac-623f-50d3-b0c5-96993aacefde', 2, 'grammar', 'grammar', '1:00 — «___ la una.»', '', '{"lang":"es"}'::jsonb, 'Только для часа — es la una; остальные — son las…', 10) on conflict (id) do nothing;
