insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('91590c6c-92c0-5c1e-9399-1dbac8035681', 'a41701ac-623f-50d3-b0c5-96993aacefde', 3, 'example', 'Дни недели', '{"items":[{"ru":"lunes, martes, miércoles","es":"понедельник, вторник, среда · [лу́нэс, ма́ртэс, мье́рколэс]"},{"ru":"jueves, viernes","es":"четверг, пятница · [хуэ́бэс, бье́рнэс]"},{"ru":"sábado, domingo","es":"суббота, воскресенье · [са́бадо, доми́нго]"},{"ru":"el fin de semana","es":"выходные"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('39fee1e8-c8fc-53f4-836d-ee386c814202', 'a41701ac-623f-50d3-b0c5-96993aacefde', 4, 'tip', 'В понедельник — el lunes', '{"md":"Дни недели пишутся **с маленькой буквы** и употребляются **с артиклем, без предлога**: «в понедельник» — **el lunes**, а не «en lunes». «По понедельникам» — **los lunes**: **Los lunes tengo clase de español.** «В выходные» — **el fin de semana**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('63516142-8dbb-55bb-88ee-141d84a50a50', 'a41701ac-623f-50d3-b0c5-96993aacefde', 5, 'grammar', 'grammar', '«По субботам я хожу в спортзал»: «___ sábados voy al gimnasio.»', '', '{"lang":"es"}'::jsonb, 'Регулярно, каждую субботу → los sábados, без предлога.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4da02d11-7711-55ca-9c45-f4c773c6f1f6', '63516142-8dbb-55bb-88ee-141d84a50a50', 'Los', 0) on conflict (id) do nothing;
