insert into public.exercise_solutions (exercise_id, solution) values ('63516142-8dbb-55bb-88ee-141d84a50a50', '{"correct":"Los"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('3423c912-ea33-59be-8a62-ce537641d189', 'a41701ac-623f-50d3-b0c5-96993aacefde', 6, 'table', 'Как часто', '{"caption":"Эти слова можно ставить в начале фразы или после глагола: A veces como fuera. / Como fuera a veces.","headers":["Испанский","Русский"],"rows":[["siempre","всегда"],["normalmente","обычно"],["a menudo","часто"],["a veces","иногда"],["nunca","никогда"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1f429a84-3d30-531b-b271-348373eab67a', 'a41701ac-623f-50d3-b0c5-96993aacefde', 7, 'grammar', 'Двойное отрицание, как в русском', '{"md":"Испанский, как и русский, любит двойное отрицание: **No como carne nunca.** (Я никогда не ем мясо). Если **nunca** стоит перед глаголом, **no** не нужно: **Nunca como carne.** А «no nunca» подряд — ошибка."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3bbb8cdb-9300-56da-a1e4-09312a6939ab', 'a41701ac-623f-50d3-b0c5-96993aacefde', 8, 'true_false', 'grammar', 'Верно или неверно?', '«Nunca trabajo los domingos» — правильная фраза.', '{"lang":"es"}'::jsonb, 'Nunca стоит перед глаголом, поэтому no не нужно.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('3bbb8cdb-9300-56da-a1e4-09312a6939ab', '{"value":true}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('273ee47e-d425-5c27-b826-d7f2c79bd21b', 'a41701ac-623f-50d3-b0c5-96993aacefde', 9, 'reading_comprehension', 'reading', 'Что он делает по субботам?', '', '{"text":"Normalmente me levanto a las siete, pero los sábados siempre duermo hasta las diez. Nunca trabajo el fin de semana.","lang":"es"}'::jsonb, 'Los sábados siempre duermo hasta las diez.', 10) on conflict (id) do nothing;
