insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('7ee54994-f168-5e06-8b4a-cf0dc2b8cd0e', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 0, 'text', 'Вежливо, но без церемоний', '{"md":"В испанском кафе фраза **Quiero un café, por favor** (Я хочу кофе, пожалуйста) вполне нормальна. Ещё мягче — **¿Me pone un café?** (Испания) или **¿Me trae un café?** (Принесите мне кофе). Главное — не забывать **por favor** и **gracias**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e1b789f4-2247-5cc6-a580-4b93de710126', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 1, 'example', 'Фразы в кафе и ресторане', '{"items":[{"ru":"Una mesa para dos, por favor.","es":"Столик на двоих, пожалуйста."},{"ru":"¿Qué nos recomienda?","es":"Что вы нам посоветуете?"},{"ru":"Para mí, una paella.","es":"Мне паэлью."},{"ru":"¿Me pone un café con leche?","es":"Можно мне кофе с молоком?"},{"ru":"La cuenta, por favor.","es":"Счёт, пожалуйста."},{"ru":"¿Puedo pagar con tarjeta?","es":"Можно оплатить картой?"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('0440dc54-b81d-5032-bf63-e4fd91c57f31', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 2, 'tip', 'Usted — это «он» по форме', '{"md":"С **usted** глагол стоит в 3-м лице: **¿Qué quiere usted?**, **¿Me trae la cuenta?**, **¿Usted habla inglés?** Частая ошибка русскоязычных — «usted quieres», смесь «вы» и «ты». Во множественном числе **ustedes** + 3-е лицо мн. числа: **¿Qué quieren ustedes?**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('20227647-ca32-5827-951c-c6f2cbc29a8d', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 3, 'grammar', 'grammar', 'Официант спрашивает клиента: «¿Qué ___ usted?»', '', '{"lang":"es"}'::jsonb, 'usted → 3-е лицо: quiere.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d7b5b24e-aa37-5bf9-b00c-2527039700e9', '20227647-ca32-5827-951c-c6f2cbc29a8d', 'quiere', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('48b5249f-041b-56bc-85dd-3a10fc5cc1cd', '20227647-ca32-5827-951c-c6f2cbc29a8d', 'quieres', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b098c21e-19e9-534c-a3a7-ccf809f7e405', '20227647-ca32-5827-951c-c6f2cbc29a8d', 'quiero', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('20227647-ca32-5827-951c-c6f2cbc29a8d', '{"correct":"quiere"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2d1bd2c4-6e4c-5591-a184-bb808e7b043e', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 4, 'dialogue', 'В ресторане', '{"lines":[{"speaker":"Camarero","ru":"Buenas noches. ¿Qué van a tomar?","es":"Добрый вечер. Что будете заказывать?"},{"speaker":"Tú","ru":"Para mí, la sopa del día y después el pescado.","es":"Мне суп дня, а потом рыбу."},{"speaker":"Camarero","ru":"¿Y para beber?","es":"А что будете пить?"},{"speaker":"Tú","ru":"Agua sin gas, por favor.","es":"Воду без газа, пожалуйста."},{"speaker":"Camarero","ru":"Muy bien.","es":"Хорошо."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('3f2702b9-fbed-5fde-8dac-a199c9707eae', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 5, 'grammar', 'Gustar работает как «нравиться»', '{"md":"Здесь русскоязычным повезло: **gustar** устроен как «нравиться». **Me gusta el café.** (Мне нравится кофе). Глагол согласуется с тем, **что** нравится: **Me gusta la fruta**, но **Me gustan las fresas** (Мне нравится клубника — ягод много). С глаголом: **Me gusta cocinar**. «Тебе» — **te gusta**, «ему / ей / вам» — **le gusta**. И не теряй артикль: **Me gusta el té**, а не «me gusta té»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b77a7ce3-aca5-5f01-ad02-2f15ef0120ef', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 6, 'grammar', 'grammar', 'Мне нравятся помидоры: «Me ___ los tomates.»', '', '{"lang":"es"}'::jsonb, 'Помидоров много → gustan.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ce09da3e-7b84-5bfc-993c-84c547a43fc5', 'b77a7ce3-aca5-5f01-ad02-2f15ef0120ef', 'gustan', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d9b20d4f-3b7b-57d8-b1c3-013ea5ef7143', 'b77a7ce3-aca5-5f01-ad02-2f15ef0120ef', 'gusta', 1) on conflict (id) do nothing;
