insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cea39fd3-89ae-53db-a6b3-c1a2f2792485', 'f98007d1-70e2-54ec-b0eb-afe16722add8', 7, 'grammar', 'В магазине', '{"md":"**¿Cuánto cuesta?** — Сколько стоит? (одна вещь) · **¿Cuánto cuestan?** — Сколько стоят? (несколько). **Un kilo de tomates, por favor.** · **¿Algo más?** — Что-нибудь ещё? · **Nada más, gracias.** — Больше ничего, спасибо. Цена: **Son ocho euros con cincuenta.** (8,50 €)."}'::jsonb) on conflict (id) do nothing;
