insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('045032f5-0137-5f9c-9f10-7bd5407fd13e', '533a566c-8ea0-591f-b0dc-ed9fb39ae0d2', 'esru-direcciones', '¿Dónde está…? Город и итоги A1', 'Как спросить дорогу и понять ответ, глагол ir и первый взгляд на прошедшее время.', array['Спрашивать дорогу', 'Понимать указания', 'Повторить всё A1']::text[], 1, 13, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
