insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5244a07b-67a3-51a0-a8bb-a0ec64b65efd', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 0, 'grammar', 'Как спросить дорогу', '{"md":"Начни с **Perdone** (Простите — незнакомому, на «вы») или **Perdona** (на «ты»). Затем: **¿Dónde está la estación?** (Где вокзал?) или **¿Hay una farmacia por aquí?** (Здесь есть поблизости аптека?). Как в уроке про дом: **hay** — для неизвестного предмета, **está** — для известного."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8ec25567-2f38-5249-8f3d-5dad8b5d4826', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 1, 'example', 'Указания', '{"items":[{"ru":"Siga todo recto.","es":"Идите прямо."},{"ru":"Gire a la derecha.","es":"Поверните направо."},{"ru":"Gire a la izquierda.","es":"Поверните налево."},{"ru":"Está al final de la calle.","es":"Это в конце улицы."},{"ru":"Está a cinco minutos.","es":"Это в пяти минутах."},{"ru":"Está enfrente del museo.","es":"Это напротив музея."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1024f8da-7ea6-58a4-809f-42d1e31300ba', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 2, 'listen_select', 'listening', 'Послушай и выбери, что ты слышишь.', '', '{"audio_text":"Gire a la izquierda en el semáforo.","lang":"es"}'::jsonb, 'izquierda — налево, derecha — направо, semáforo — светофор.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4ed3532f-59a9-51e5-b3a2-7496ad7a612c', '1024f8da-7ea6-58a4-809f-42d1e31300ba', 'Поверните налево на светофоре', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('81bd0aba-c587-55ea-85f0-6d5560a871f3', '1024f8da-7ea6-58a4-809f-42d1e31300ba', 'Поверните направо на светофоре', 1) on conflict (id) do nothing;
