insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('85afe697-0d80-50fe-a1dc-3890575c02ca', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 3, 'grammar', 'Ir — идти и ехать', '{"md":"В русском «идти» и «ехать» — разные глаголы, а в испанском один: **ir**. **Voy a pie** (иду пешком), **Voy en metro** (еду на метро). Формы неправильные: **voy, vas, va, vamos, vais, van**. Направление — с **a**: **Voy a Madrid.** **a + el = al**: **Voy al centro.**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f16d0123-0e84-57b6-8dd9-c71b8ac67d12', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 4, 'grammar', 'grammar', 'Мы едем в центр: «Vamos ___ centro.»', '', '{"lang":"es"}'::jsonb, 'a + el всегда сливаются в al.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('410fc447-48f6-5e62-b317-405486a0c95e', 'f16d0123-0e84-57b6-8dd9-c71b8ac67d12', 'al', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('0c764993-a17b-5374-94b8-de854ebc3d42', 'f16d0123-0e84-57b6-8dd9-c71b8ac67d12', 'a el', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('067822b0-004a-5d8f-aa94-521ec0e70b38', 'f16d0123-0e84-57b6-8dd9-c71b8ac67d12', 'en el', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f16d0123-0e84-57b6-8dd9-c71b8ac67d12', '{"correct":"al"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('66446c7f-a002-513f-87bb-2f443f1535f5', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 5, 'dialogue', 'Как пройти к музею', '{"lines":[{"speaker":"Turista","ru":"Perdone, ¿dónde está el Museo del Prado?","es":"Простите, где музей Прадо?"},{"speaker":"Señora","ru":"Siga todo recto y gire a la derecha en la segunda calle.","es":"Идите прямо и на второй улице поверните направо."},{"speaker":"Turista","ru":"¿Está lejos?","es":"Это далеко?"},{"speaker":"Señora","ru":"No, está a diez minutos a pie.","es":"Нет, в десяти минутах пешком."},{"speaker":"Turista","ru":"¡Muchas gracias!","es":"Большое спасибо!"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b9e47e20-f348-59cf-abc0-071816ce9a1b', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 6, 'reading_comprehension', 'reading', 'Куда нужно повернуть?', '', '{"text":"Siga todo recto y gire a la derecha en la segunda calle. El museo está a diez minutos a pie.","lang":"es"}'::jsonb, 'Gire a la derecha en la segunda calle.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('a7fbf951-a9ca-51fe-89be-da8db82f3098', 'b9e47e20-f348-59cf-abc0-071816ce9a1b', 'Направо на второй улице', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('497632b5-0983-50b8-b984-daf91b17380e', 'b9e47e20-f348-59cf-abc0-071816ce9a1b', 'Налево на второй улице', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('6ec0e9ae-0741-5899-94ed-4d1322079b58', 'b9e47e20-f348-59cf-abc0-071816ce9a1b', 'Направо на первой улице', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('b9e47e20-f348-59cf-abc0-071816ce9a1b', '{"correct":"Направо на второй улице"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8cd9b9cf-334f-5b35-a0e9-cfc79c32a8fc', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 7, 'tip', 'Прошедшее время: не вид, а период', '{"md":"Скоро ты встретишь прошедшее время. В русском мы выбираем вид (делал / сделал), а в испанском (в Испании) важно, **закончился ли период**: **Hoy he comido paella** (Сегодня я ел паэлью — день ещё идёт) и **Ayer comí paella** (Вчера я ел паэлью — день закончился). В Латинской Америке в обоих случаях чаще говорят **comí**. Пока просто запомни эти две фразы — подробно разберём на уровне A2."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('12c94cac-2a4e-52e9-94ec-f6eddf3b98fa', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 8, 'true_false', 'grammar', 'Верно или неверно?', 'В Испании говорят «Ayer he comido paella».', '{"lang":"es"}'::jsonb, 'Ayer (вчера) — период закончился → Ayer comí paella. «He comido» — для сегодня, этой недели и т. п.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('12c94cac-2a4e-52e9-94ec-f6eddf3b98fa', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ca30d02c-7b62-5a99-860b-46af9999fa37', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 9, 'text', 'Итоги уровня A1', '{"md":"Ты уже умеешь: **здороваться** и **знакомиться**, читать по правилам и ставить **ударение**, использовать **артикли и род**, различать **ser и estar**, говорить **возраст с tener**, рассказывать о **семье**, **доме** и **распорядке дня**, называть **время и дни недели**, заказывать в **кафе** и спрашивать **дорогу**. Проверь себя на последних упражнениях!"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('eed1da29-944d-57f7-b8fd-2be90d5bc8a8', '045032f5-0137-5f9c-9f10-7bd5407fd13e', 10, 'grammar', 'grammar', 'Повторение: «Молоко холодное».', '', '{"lang":"es"}'::jsonb, 'leche — женского рода (la), а «холодное сейчас» — состояние → estar.', 10) on conflict (id) do nothing;
