insert into public.courses (id, slug, title, subtitle, description, level, order_index, is_premium, status, source, target_language, source_language) values ('0b03d4d2-0bca-5d6a-b699-428eb0bb3115', 'angliyskiy-a1', 'Английский A1 · Первые шаги', 'С нуля до первых разговоров', 'Приветствия, глагол to be, которого нет в русском, артикли a/an/the, звуки th и w, семья, распорядок дня и как вежливо заказать кофе. Бесплатно и полностью.', 'A1', 9, false, 'published', 'complementary', 'en', 'ru') on conflict (id) do nothing;
insert into public.course_units (id, course_id, title, description, order_index, status) values ('ef905aa2-4632-56f5-bacd-ba8924983bfa', '0b03d4d2-0bca-5d6a-b699-428eb0bb3115', 'Звуки и приветствия', 'Представьтесь и звучите естественно с первого дня.', 0, 'published') on conflict (id) do nothing;
insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('937fd389-295f-5052-bb59-292934163849', 'ef905aa2-4632-56f5-bacd-ba8924983bfa', 'enru-hello', 'Hello! Приветствие и знакомство', 'Нейтральные и неформальные приветствия, «I''m…» и «Nice to meet you».', array['Здороваться в любое время дня', 'Называть своё имя', 'Отвечать на «How are you?»']::text[], 0, 10, 45, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6acbf141-5e74-571a-8150-9cd199f5d5e0', '937fd389-295f-5052-bb59-292934163849', 0, 'text', 'Как устроен курс', '{"md":"Каждый урок идёт по одному циклу: вы **понимаете** правило по-русски, **слушаете** живые фразы (нажмите на динамик), **тренируетесь** в коротких упражнениях и **говорите** вслух в микрофон. В квадратных скобках — **произношение русскими буквами**: знак ́ показывает ударение, двоеточие — долгий звук, [х] — лёгкий выдох, а не хрип. Транскрипция — только подсказка: главный образец — аудио."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f74ae79e-46e0-53ef-a187-2bee04957f0a', '937fd389-295f-5052-bb59-292934163849', 1, 'example', 'Приветствия, которые реально используют', '{"items":[{"ru":"Hello!","es":"Здравствуйте! / Привет! (нейтрально) · [хэло́у]"},{"ru":"Hi!","es":"Привет! (неформально) · [хай]"},{"ru":"Good morning!","es":"Доброе утро! · [гуд мо́:нинг]"},{"ru":"Good afternoon!","es":"Добрый день! (после полудня) · [гуд а:фтэну́:н]"},{"ru":"Good evening!","es":"Добрый вечер! · [гуд и́:внинг]"},{"ru":"Goodbye! · Bye!","es":"До свидания! · Пока! · [гудба́й, бай]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9b22039a-a174-5408-8fa1-3425dc74ac8c', '937fd389-295f-5052-bb59-292934163849', 2, 'tip', 'Ты или вы? В английском — просто you', '{"md":"В английском нет разницы между «ты» и «вы»: и другу, и начальнику говорят **you** [ю:]. Вежливость передают другие средства: **please**, **thank you**, мягкий тон и вопрос вместо приказа. **Hello** подходит для любой ситуации, **Hi** — для друзей и коллег."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e8d8ea74-32e6-5e25-a948-563fd3beb9c5', '937fd389-295f-5052-bb59-292934163849', 3, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"Good afternoon!","lang":"en"}'::jsonb, 'Good afternoon — «добрый день», говорят после 12 часов.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('2115efbc-ef9d-5554-8fc3-3106ffd1a47d', 'e8d8ea74-32e6-5e25-a948-563fd3beb9c5', 'Good afternoon!', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('cc800d95-d077-5fca-bb13-f27e6161fac9', 'e8d8ea74-32e6-5e25-a948-563fd3beb9c5', 'Good evening!', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e07099a7-5b8f-5f2c-b728-a886b4bcffb4', 'e8d8ea74-32e6-5e25-a948-563fd3beb9c5', 'Good morning!', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e8d8ea74-32e6-5e25-a948-563fd3beb9c5', '{"correct":"Good afternoon!"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('47025ba9-6a0b-5e1e-8bbd-c0cddd071314', '937fd389-295f-5052-bb59-292934163849', 4, 'grammar', 'Представиться: I''m…', '{"md":"Самое естественное: **I''m** + имя: **I''m Anna.** [айм а́нна]. Можно и **My name is Anna.** Обратите внимание: в английском нельзя сказать просто «I Anna» — между «я» и именем всегда стоит глагол (**am**, сокращённо **''m**). Подробно разберём в уроке про to be. Спросить имя: **What''s your name?** [уотс ё: нэйм]. При знакомстве: **Nice to meet you!** [найс ту ми:т ю] — в ответ **Nice to meet you too!**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cfaecf24-2180-51d5-af4a-162ee188a862', '937fd389-295f-5052-bb59-292934163849', 5, 'dialogue', 'Первый день на курсах', '{"lines":[{"speaker":"Tom","ru":"Hi! I''m Tom. What''s your name?","es":"Привет! Я Том. Как тебя зовут?"},{"speaker":"Anna","ru":"Hi, Tom! I''m Anna.","es":"Привет, Том! Я Анна."},{"speaker":"Tom","ru":"Nice to meet you, Anna.","es":"Приятно познакомиться, Анна."},{"speaker":"Anna","ru":"Nice to meet you too!","es":"Мне тоже очень приятно!"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('ae24fb31-69ea-5514-837c-e7e780617f57', '937fd389-295f-5052-bb59-292934163849', 6, 'multiple_choice', 'vocabulary', 'Вас знакомят с новым человеком. Что вы скажете?', '', '{"lang":"en"}'::jsonb, 'Nice to meet you = приятно познакомиться.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('28b9dabc-e607-59d1-b7b5-44510f470014', 'ae24fb31-69ea-5514-837c-e7e780617f57', 'Nice to meet you!', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('29fbcdc5-8fbf-56cc-ac16-a2905483e1d3', 'ae24fb31-69ea-5514-837c-e7e780617f57', 'Good night!', 1) on conflict (id) do nothing;
