insert into public.exercise_solutions (exercise_id, solution) values ('ae24fb31-69ea-5514-837c-e7e780617f57', '{"correct":"Nice to meet you!"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('79b22a85-a324-5cce-a503-1cb160d76e81', '937fd389-295f-5052-bb59-292934163849', 7, 'grammar', 'How are you? — это почти приветствие', '{"md":"В русском на «Как дела?» друг может честно рассказать о проблемах. В английском **How are you?** — часть приветствия: отвечают коротко, позитивно и возвращают вопрос. **I''m fine, thanks. And you?** · **Great, thanks!** · **Not bad.** (Неплохо.) Друзья часто говорят **How''s it going?** [хауз ит го́уинг] — «Как оно?»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3b89efbf-2d07-54ef-9e01-611faf410c82', '937fd389-295f-5052-bb59-292934163849', 8, 'true_false', 'vocabulary', 'Верно или неверно?', 'На «How are you?» принято подробно рассказывать, как у вас дела.', '{"lang":"en"}'::jsonb, 'Это формула вежливости: достаточно «Fine, thanks. And you?».', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('3b89efbf-2d07-54ef-9e01-611faf410c82', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('6c05b032-563b-5de3-8b29-1f957b761944', '937fd389-295f-5052-bb59-292934163849', 9, 'match_pairs', 'vocabulary', 'Соедините фразу с переводом.', '', '{"left":["How are you?","Not bad.","See you!","Thanks!"],"right":["Неплохо.","Как дела?","Спасибо!","Увидимся!"],"lang":"en"}'::jsonb, 'Фразы для приветствия и прощания.', 10) on conflict (id) do nothing;
