insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f0c1dafb-2f17-5b63-bfe8-631044b7f6d6', '937fd389-295f-5052-bb59-292934163849', 10, 'order_words', 'grammar', 'Соберите ответ: «Хорошо, спасибо. А у тебя?»', '', '{"tokens":["thanks","fine","I''m","you","and"],"lang":"en"}'::jsonb, 'I''m fine, thanks. And you?', 10) on conflict (id) do nothing;
