insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1b29fcc8-c1dd-5e03-8fa5-be09a4875068', '937fd389-295f-5052-bb59-292934163849', 12, 'pronunciation', 'speaking', 'Представьтесь вслух: «Привет, я Анна. Приятно познакомиться».', '', '{"audio_text":"Hi, I''m Anna. Nice to meet you!","lang":"en"}'::jsonb, '[хай, айм а́нна. найс ту ми:т ю]. Можно сказать своё имя.', 10) on conflict (id) do nothing;
