insert into public.exercise_options (id, exercise_id, label, order_index) values ('f65c4a85-ab97-55b7-be19-5a3e1a46f5cf', 'a97a5f09-61f0-5216-9e5c-3f513a5a3458', 'добрый день', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('a97a5f09-61f0-5216-9e5c-3f513a5a3458', '{"correct":"привет"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('102cad6e-e8a9-5a96-8ab4-93b1452498e0', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 0, 'text', 'Почему начинаем со звуков', '{"md":"В английском около **20 гласных звуков**, а в русском — 6. Если их не различать, **sheep** (овца) и **ship** (корабль) звучат одинаково. Идеальный акцент не нужен: достаточно **пяти ключевых звуков**, чтобы вас всегда понимали."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8aba2edf-2351-5ca7-8108-442d094beee9', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 1, 'grammar', '1 · Th: язык между зубами', '{"md":"Кончик языка слегка зажат между зубами, и вы выдыхаете. Глухой звук [θ]: **think** [θинк] (думать), **three** [θри:] (три). Звонкий [ð]: **this** [ðис], **the** [ðэ], **mother** [ма́ðэ]. Типичная ошибка — заменять th на «с», «з» или «ф»: **think** превращается в **sink** (тонуть), а **three** — в **free** (бесплатный)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('9a8159eb-2ec1-57fd-964f-665f3e5b045c', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 2, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"three","lang":"en"}'::jsonb, 'three [θри:] — три; tree [три:] — дерево; free [фри:] — бесплатный.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8905620d-6b3f-5538-b02d-fa6f342cacfa', '9a8159eb-2ec1-57fd-964f-665f3e5b045c', 'three', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('00cf155d-2d1a-5ad0-a5b8-1e062e734c2a', '9a8159eb-2ec1-57fd-964f-665f3e5b045c', 'tree', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b6a11f26-d912-569e-9e1c-746940dd57a1', '9a8159eb-2ec1-57fd-964f-665f3e5b045c', 'free', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('9a8159eb-2ec1-57fd-964f-665f3e5b045c', '{"correct":"three"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b8914e5b-5fa2-5ea6-8eb2-4209d4dfe739', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 3, 'grammar', '2 · W — это не «в»', '{"md":"Русское «в» — это английское **v**: зубы касаются нижней губы (**very** [вэ́ри]). Для **w** зубы не участвуют: губы вытягиваются трубочкой и быстро раскрываются, как в начале слова «уа»: **we** [уи:], **what** [уот], **window** [уи́ндоу]. Сравните: **wine** [уайн] — вино, **vine** [вайн] — виноградная лоза."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2fe53746-bb38-5fd4-bea0-cdeee43fa64b', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 4, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"wine","lang":"en"}'::jsonb, 'wine — губы трубочкой, без касания зубов. vine — с «в».', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d22b9d6a-1587-5ab1-815f-b9ef53312521', '2fe53746-bb38-5fd4-bea0-cdeee43fa64b', 'wine', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c07b4b9b-bdfb-5e51-a313-90aee8ee77e0', '2fe53746-bb38-5fd4-bea0-cdeee43fa64b', 'vine', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('2fe53746-bb38-5fd4-bea0-cdeee43fa64b', '{"correct":"wine"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e3adfcb6-b41e-58d7-b174-967d56c2c185', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 5, 'grammar', '3 · H — лёгкий выдох, а не «х»', '{"md":"Русское «х» — шумное, с трением в горле. Английское **h** — просто выдох, как будто дышите на стекло: **hello** [хэло́у], **house** [хаус], **hot** [хот]. В словах **hour** [а́уэ] (час) и **honest** [о́нист] (честный) h вообще не читается."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('29744544-6b80-5b1f-b4e0-a1c5d37f3ba5', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 6, 'grammar', '4 · Долгие и краткие гласные', '{"md":"Долгое **ee** — напряжённое «и:», губы в улыбке: **sheep** [ши:п]. Краткое **i** — короткое и расслабленное, звучит между «и» и «ы»: **ship** [шип]. Длина звука меняет смысл слова — тяните долгие гласные смелее, чем кажется нужным."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9f620428-2694-5ac9-9ba1-e67bf1907dea', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 7, 'table', 'Пары, где длина меняет смысл', '{"headers":["Краткий","Долгий"],"rows":[["ship (корабль)","sheep (овца)"],["live (жить)","leave (уходить)"],["full (полный)","fool (дурак)"],["sit (сидеть)","seat (место, сиденье)"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('9adbe57b-8cde-596c-aae7-56e2c9a7904d', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 8, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"sheep","lang":"en"}'::jsonb, 'sheep — долгое [и:] — овца.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('e8ef2404-e2c5-5584-a61e-1c53e3ece3c7', '9adbe57b-8cde-596c-aae7-56e2c9a7904d', 'sheep', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d6ff82f1-a312-5a18-b832-23091bd2f1b7', '9adbe57b-8cde-596c-aae7-56e2c9a7904d', 'ship', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('9adbe57b-8cde-596c-aae7-56e2c9a7904d', '{"correct":"sheep"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('50baa98b-89b5-5d61-b969-ec436e06dcb6', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 9, 'grammar', '5 · Не оглушайте звонкие на конце', '{"md":"По-русски «дуб» звучит как [дуп], а «год» — как [гот]. В английском так нельзя: от звонкости зависит смысл. **bed** [бэд] — кровать, **bet** [бэт] — пари; **bag** [бэг] — сумка, **back** [бэк] — спина. Держите звонкий звук до конца, а гласную перед ним чуть удлиняйте."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f3b766a8-4d3a-50e2-b2d1-d0481a9885dc', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 10, 'true_false', 'speaking', 'Верно или неверно?', 'В слове hour (час) буква h читается.', '{"lang":"en"}'::jsonb, 'hour [а́уэ]: h немая. В hello и house она звучит.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f3b766a8-4d3a-50e2-b2d1-d0481a9885dc', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
