insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b139f500-a0e4-57bd-98c4-67109c79f89f', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 12, 'pronunciation', 'speaking', 'Скажите, держа язык между зубами: «three, thirty».', '', '{"audio_text":"Three, thirty","lang":"en"}'::jsonb, '[θри:, θё́:ти]. Кончик языка виден между зубами.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('b139f500-a0e4-57bd-98c4-67109c79f89f', '{"accepted":["three thirty","~three","~thirty"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('665bd568-eccd-5adc-a4e7-3a5b45ca35a5', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 13, 'pronunciation', 'speaking', 'Скажите, следя за w и v: «Очень хорошо, спасибо».', '', '{"audio_text":"Very well, thank you.","lang":"en"}'::jsonb, '[вэ́ри уэл, θэнк ю]. В very — «в», в well — губы трубочкой.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('665bd568-eccd-5adc-a4e7-3a5b45ca35a5', '{"accepted":["Very well, thank you"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b6ae5dcb-ece6-5a68-97ec-0f8153050a1c', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2423f5fe-60ed-56c8-8eb2-4f0b8975eead', '9c8ba2af-e496-5cf7-810e-e331e82c9d77', 1001, 'match_pairs', 'vocabulary', 'Соедини каждое слово с его значением.', '', '{"left":["think","three","this","we"],"right":["три","думать","мы","это, этот"],"lang":"en"}'::jsonb, 'Новые слова этого урока.', 10) on conflict (id) do nothing;
