insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('42be3851-440c-55d5-b656-6bcaa1770a7c', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 0, 'example', 'От 1 до 12', '{"items":[{"ru":"one, two, three","es":"1, 2, 3 · [уан, ту:, θри:]"},{"ru":"four, five, six","es":"4, 5, 6 · [фо:, файв, сикс]"},{"ru":"seven, eight, nine","es":"7, 8, 9 · [сэвн, эйт, найн]"},{"ru":"ten, eleven, twelve","es":"10, 11, 12 · [тэн, илэ́вн, туэлв]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('197956c4-f22b-5f7f-a60d-76a33d4e466e', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 1, 'grammar', 'От 13 до 100', '{"md":"С 13 до 19 добавляется **-teen** с ударением на конце: **thirteen** [θё:ти́:н], **fifteen** [фифти́:н], **nineteen**. Десятки оканчиваются на **-ty** с ударением в начале: **thirty** [θё́:ти], **fifty** [фи́фти], **ninety**. **21 = twenty-one**, **100 = one hundred** (или **a hundred**)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8d7728d4-6e64-5312-887a-ddce9f72c2b4', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 2, 'tip', 'Fifteen или fifty?', '{"md":"Самая частая путаница в магазинах. **fifteen** (15) — ударение в конце и долгое [и:]: [фифти́:н]; **fifty** (50) — ударение в начале: [фи́фти]. Не уверены — переспросите: **Sorry, fifteen or fifty?**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f7aadba2-536e-5fe7-a4f3-cbe933998889', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 3, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"fifty","lang":"en"}'::jsonb, 'fifty [фи́фти] = 50, ударение в начале.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('f6c8172d-c782-568a-85af-c48dbea259c2', 'f7aadba2-536e-5fe7-a4f3-cbe933998889', 'fifty', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('c8249d9e-bc9a-5cfc-ab9a-45522c046ebe', 'f7aadba2-536e-5fe7-a4f3-cbe933998889', 'fifteen', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f7aadba2-536e-5fe7-a4f3-cbe933998889', '{"correct":"fifty"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('26202a57-c577-59c2-9391-ff8ef2cb9fb8', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 4, 'grammar', 'Возраст: не «have», а «be»', '{"md":"По-русски «**мне** 20 лет», и хочется сказать «Me 20 years» или «I have 20 years». Так по-английски **нельзя**. Возраст — это то, кем вы **являетесь**: **I''m 20.** или **I''m 20 years old.** Короткий вариант «I''m 20 years» без **old** тоже неправильный. Вопрос: **How old are you?** [хау о́улд а: ю] — дословно «Насколько вы старый?», но это нейтральная фраза."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('4b88d5cf-0a26-5f7d-b6d9-faf82ddfb9e2', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 5, 'grammar', 'grammar', 'Мне 30 лет: «I ___ 30 years old.»', '', '{"lang":"en"}'::jsonb, 'Возраст — с to be: I am 30.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('eaa884d3-6110-5138-b29c-b7e27c5bb81d', '4b88d5cf-0a26-5f7d-b6d9-faf82ddfb9e2', 'am', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4c9fa386-f428-566d-b142-6039071f5a18', '4b88d5cf-0a26-5f7d-b6d9-faf82ddfb9e2', 'have', 1) on conflict (id) do nothing;
