insert into public.exercise_solutions (exercise_id, solution) values ('4b88d5cf-0a26-5f7d-b6d9-faf82ddfb9e2', '{"correct":"am"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5977d2c9-2a1b-546f-9318-b74e1e93e565', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 6, 'true_false', 'grammar', 'Верно или неверно?', '«I have 20 years» — правильная английская фраза.', '{"lang":"en"}'::jsonb, 'Правильно: I''m 20 (years old).', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('5977d2c9-2a1b-546f-9318-b74e1e93e565', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('846d8caa-c281-54c6-bd77-35375be2c692', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 7, 'true_false', 'grammar', 'Верно или неверно?', '«I''m 20 years» без слова old — тоже правильно.', '{"lang":"en"}'::jsonb, 'Либо I''m 20, либо I''m 20 years old. Без old фраза звучит незаконченной.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('846d8caa-c281-54c6-bd77-35375be2c692', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fe388385-cb85-5d47-bf7d-c974435ee72e', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 8, 'grammar', 'Номер телефона', '{"md":"Номер диктуют **по одной цифре**. Ноль обычно называют **oh** [оу], как букву O. Две одинаковые цифры подряд — **double**: 77 = **double seven**. **My number is 7 5 5 0 2 1** = seven, double five, oh, two, one. Номер делят на группы с паузами, а не на «сотни» и «десятки», как часто делают по-русски."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('995486ef-3c3d-5a0b-8e46-c9f53b191b41', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 9, 'reading_comprehension', 'reading', 'Какой номер продиктовали?', '', '{"text":"My number is seven, double five, oh, two, one.","lang":"en"}'::jsonb, 'double five = 55; oh = 0.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('116b3d9a-45ea-56ac-8e20-cd901d19fbf8', '995486ef-3c3d-5a0b-8e46-c9f53b191b41', '755021', 0) on conflict (id) do nothing;
