insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('01ca159f-d1ba-5344-ae35-47f8c654b263', '7e5cb208-ea89-59b1-ad0c-55f072d42f5c', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
