insert into public.exercise_options (id, exercise_id, label, order_index) values ('806fb251-df27-5994-9daa-18ef380a7655', '8d76fc0c-35e0-51c1-8020-5edf7d70bd29', 'добрый вечер', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('7c11b03d-498e-5329-8084-502442c89728', '8d76fc0c-35e0-51c1-8020-5edf7d70bd29', 'до свидания', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('8d76fc0c-35e0-51c1-8020-5edf7d70bd29', '{"correct":"добрый вечер"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('207f4f0a-6226-580d-8206-83d340dcbf9c', '5dd110ba-037d-5317-a29a-68ffeb391feb', 0, 'text', 'Где глагол?', '{"md":"По-русски мы говорим «Я студент», «Она дома», «Мы устали» — без глагола. В английском **предложение без глагола невозможно**: **I am a student. She is at home. We are tired.** Пропущенный to be — ошибка номер один у русскоговорящих: «She doctor», «I tired». Хорошая новость: в настоящем времени у него всего три формы — **am, is, are**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('696c3923-1b6e-5443-9ab3-23990ce5f9db', '5dd110ba-037d-5317-a29a-68ffeb391feb', 1, 'table', 'To be в настоящем времени', '{"caption":"В речи почти всегда используют сокращения.","headers":["Полная форма","Сокращение","Перевод"],"rows":[["I am","I''m","я (есть) …"],["you are","you''re","ты / вы …"],["he is","he''s","он …"],["she is","she''s","она …"],["it is","it''s","это / оно …"],["we are","we''re","мы …"],["they are","they''re","они …"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('63316ce0-40be-5d44-a84a-383628cb1268', '5dd110ba-037d-5317-a29a-68ffeb391feb', 2, 'grammar', 'grammar', 'She ___ a doctor.', '', '{"lang":"en"}'::jsonb, 'he / she / it → is.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d18eaf1d-3681-51d3-afcd-cd5288b9b58e', '63316ce0-40be-5d44-a84a-383628cb1268', 'is', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('eb650450-a055-5f11-81c6-3434f2a145ba', '63316ce0-40be-5d44-a84a-383628cb1268', 'are', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('a4fbfebc-2981-5d0e-a7a6-30ef84b91c5e', '63316ce0-40be-5d44-a84a-383628cb1268', 'am', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('63316ce0-40be-5d44-a84a-383628cb1268', '{"correct":"is"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('0f5c1812-78b9-5daa-aeb8-d62a27b69e17', '5dd110ba-037d-5317-a29a-68ffeb391feb', 3, 'grammar', 'Артикль a/an: «один из многих»', '{"md":"В русском артиклей нет, поэтому их легко забыть. Перед **профессией** и любым исчисляемым существительным в единственном числе нужен **a**: **I''m a student. She''s a doctor.** Перед гласным **звуком** — **an**: **an engineer**, **an actor**. Во множественном числе артикля нет: **We are students.**"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('6f12f250-4eb7-5ec3-b459-c2d5bb24d1fc', '5dd110ba-037d-5317-a29a-68ffeb391feb', 4, 'grammar', 'grammar', 'Я инженер: «I''m ___ engineer.»', '', '{"lang":"en"}'::jsonb, 'engineer начинается с гласного звука → an.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('de77ca1e-c608-5368-9f42-1d01997f2d65', '6f12f250-4eb7-5ec3-b459-c2d5bb24d1fc', 'an', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('42d7b434-78e5-5af0-bea9-6445c21db86d', '6f12f250-4eb7-5ec3-b459-c2d5bb24d1fc', 'a', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8c0f1e7f-8938-5b3b-aee7-21db220a418a', '6f12f250-4eb7-5ec3-b459-c2d5bb24d1fc', 'the', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('6f12f250-4eb7-5ec3-b459-c2d5bb24d1fc', '{"correct":"an"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('15fe6dc9-487f-5d1b-b26a-e16999e1ae9b', '5dd110ba-037d-5317-a29a-68ffeb391feb', 5, 'tip', 'It и подлежащее обязательны', '{"md":"Русские безличные предложения в английском требуют **it**: «Холодно» → **It''s cold.** «Пять часов» → **It''s five o''clock.** «Поздно» → **It''s late.** И «Он врач» нельзя сократить до «Is doctor»: подлежащее всегда на месте — **He''s a doctor.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f2f41742-c4b5-5d02-98f6-151ad6408fd3', '5dd110ba-037d-5317-a29a-68ffeb391feb', 6, 'grammar', 'Отрицание: добавьте not', '{"md":"**I''m not** · **you aren''t** · **he isn''t**. **I''m not tired.** (Я не устал.) **It isn''t expensive.** (Это не дорого.) Частая ошибка — «I don''t tired»: с прилагательными и существительными нужен **be**, а не **do**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('369b97ba-40cf-55b4-a05f-765afafdc039', '5dd110ba-037d-5317-a29a-68ffeb391feb', 7, 'grammar', 'grammar', 'Я не устал.', '', '{"lang":"en"}'::jsonb, 'С прилагательным — be + not: I''m not tired.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('83c4c03b-b88d-5820-b674-cace64fac715', '369b97ba-40cf-55b4-a05f-765afafdc039', 'I''m not tired.', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('1c9a0e82-b6e9-5967-b8cb-f90e0fcfd262', '369b97ba-40cf-55b4-a05f-765afafdc039', 'I don''t tired.', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4392d1f7-a9a3-506c-9f01-8b65890a1122', '369b97ba-40cf-55b4-a05f-765afafdc039', 'I not tired.', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('369b97ba-40cf-55b4-a05f-765afafdc039', '{"correct":"I''m not tired."}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ba2a114d-c2a8-51c1-b35c-41fecc8201ab', '5dd110ba-037d-5317-a29a-68ffeb391feb', 8, 'grammar', 'Вопрос: меняем порядок слов', '{"md":"По-русски вопрос задают интонацией: «Ты готов?». В английском глагол встаёт **перед** подлежащим: **You are ready → Are you ready?** Краткие ответы: **Yes, I am. / No, I''m not.** В кратком утвердительном ответе сокращение не используют: «Yes, I am», а не «Yes, I''m»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1936229c-0443-5dcd-ac5f-c2cb1dbc29a8', '5dd110ba-037d-5317-a29a-68ffeb391feb', 9, 'fill_blank', 'grammar', 'Её нет дома: She ___ at home.', '', '{"sentence":"She ___ at home.","keyboard":true,"lang":"en"}'::jsonb, 'She isn''t (is not) at home.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('1936229c-0443-5dcd-ac5f-c2cb1dbc29a8', '{"accepted":["isn''t","is not","isnt"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fc5dff3e-2434-5d66-9cd5-fa33bede69d7', '5dd110ba-037d-5317-a29a-68ffeb391feb', 10, 'dialogue', 'Ты готов?', '{"lines":[{"speaker":"Mia","ru":"Are you ready?","es":"Ты готов?"},{"speaker":"Leo","ru":"No, I''m not. I''m tired.","es":"Нет. Я устал."},{"speaker":"Mia","ru":"It''s late! We''re late!","es":"Уже поздно! Мы опаздываем!"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('1e1b75c4-189a-5edc-a59e-69347f6662d1', '5dd110ba-037d-5317-a29a-68ffeb391feb', 11, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"We''re late!","lang":"en"}'::jsonb, 'We''re late = мы опаздываем.', 10) on conflict (id) do nothing;
