insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b7da8b22-6179-5ff2-a5da-29b4891b7f7a', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 0, 'example', 'Семья', '{"items":[{"ru":"mother · father","es":"мать, мама · отец, папа · [ма́ðэ, фа́:ðэ]"},{"ru":"parents","es":"родители (мама и папа)"},{"ru":"sister · brother","es":"сестра · брат"},{"ru":"son · daughter","es":"сын · дочь · [сан, до́:тэ]"},{"ru":"grandmother · grandfather","es":"бабушка · дедушка"},{"ru":"husband · wife","es":"муж · жена"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2c55f12e-e833-5105-821a-39f34b2624bf', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 1, 'tip', 'Relatives — это родственники', '{"md":"**Parents** — только мама и папа. Все остальные родственники — **relatives**: тёти, дяди, двоюродные братья (**cousins**)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9c81b54d-c087-5446-8b06-c9e49b46ebed', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 2, 'table', 'Притяжательные местоимения', '{"caption":"Не меняются во множественном числе: my brothers.","headers":["Кто","Чей","Пример"],"rows":[["I","my","my sister"],["you","your","your car"],["he","his","his mother (его мама)"],["she","her","her mother (её мама)"],["we","our","our house"],["they","their","their kids"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('12584e2d-01e9-5469-8105-4be7f9fd20e1', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 3, 'grammar', 'Слова «свой» в английском нет', '{"md":"Русское «свой» переводят по владельцу: «Он любит **свою** жену» → **He loves his wife.** «Я звоню **своей** маме» → **I call my mum.** «Она продаёт **свою** машину» → **She''s selling her car.** И ещё: с местоимением артикль не нужен — не «the my sister», а **my sister**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('4af4a6af-1571-5513-909d-ec57315f6038', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 4, 'grammar', 'grammar', 'Анна и её брат: «Anna and ___ brother.»', '', '{"lang":"en"}'::jsonb, 'her — её; his — его.', 10) on conflict (id) do nothing;
