insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c1080ce7-ee74-541d-ad2a-0ef97ceabb8f', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 6, 'grammar', 'Притяжательный падеж ''s', '{"md":"По-русски владелец стоит **после**: «машина папы». В английском — **перед** вещью, с **''s**: **my dad''s car**, **Anna''s phone**. Если владельцы во множественном числе на -s, ставим только апостроф: **my parents'' house** (дом моих родителей)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('41cf23bd-e564-50b8-9bc0-2580321ce653', '22696691-0f3e-5b26-9b94-91d0c162ef5e', 7, 'order_words', 'grammar', 'Соберите: «Это дом моей сестры».', '', '{"tokens":["my","is","This","house","sister''s"],"lang":"en"}'::jsonb, 'This is my sister''s house.', 10) on conflict (id) do nothing;
