insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f7725c9a-6793-551a-9d7c-4174c5849a60', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 0, 'grammar', 'Откуда вы', '{"md":"**Where are you from?** — **I''m from Russia.** Обратите внимание: предлог **from** стоит в конце вопроса — по-английски это нормально. Город и страну соединяют так: **I''m from Kazan, in Russia.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6b414c5b-56e6-5bc0-84df-4a1ad9e48188', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 1, 'table', 'Страна, национальность, язык', '{"caption":"Национальности и языки в английском всегда пишутся с ЗАГЛАВНОЙ буквы.","headers":["Страна","Национальность","Язык"],"rows":[["Russia","Russian","Russian"],["Germany","German","German"],["France","French","French"],["Spain","Spanish","Spanish"],["the USA","American","English"],["the UK","British","English"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e7794417-ada7-596b-b425-0762557e85a9', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 2, 'tip', 'Заглавные буквы обязательны', '{"md":"По-русски «русский» и «понедельник» пишутся со строчной. В английском **национальности, языки, дни недели и месяцы** — с заглавной: **Russian, English, Monday, January**. А местоимение **I** (я) — всегда заглавная буква, даже в середине предложения."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f3dbdd0f-849a-5c86-844f-e0a7f2663f70', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 3, 'true_false', 'grammar', 'Верно или неверно?', 'В английском слово «russian» пишется со строчной буквы.', '{"lang":"en"}'::jsonb, 'Russian — с заглавной: это национальность и язык.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f3dbdd0f-849a-5c86-844f-e0a7f2663f70', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ee10c805-c8ed-5745-887e-551ed17bf293', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 4, 'grammar', 'Speak English — без «на»', '{"md":"По-русски «говорю **на** английском», и рука тянется написать «I speak on English». Так нельзя: **I speak English.** **Do you speak Russian?** А «на английском» в смысле «на каком языке» — **in English**: **Say it in English, please.** Слово **Russian** значит и «русский», и «российский»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('69db0a70-447d-56b7-abcb-1ae18908f377', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 5, 'grammar', 'grammar', 'Я говорю по-английски.', '', '{"lang":"en"}'::jsonb, 'speak + язык, без предлога и без артикля.', 10) on conflict (id) do nothing;
