insert into public.exercise_solutions (exercise_id, solution) values ('69db0a70-447d-56b7-abcb-1ae18908f377', '{"correct":"I speak English."}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('096b97ef-5d28-5cdd-a388-5909c331c005', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 6, 'dialogue', 'В аэропорту', '{"lines":[{"speaker":"Officer","ru":"Where are you from?","es":"Откуда вы?"},{"speaker":"Ivan","ru":"I''m from Russia.","es":"Я из России."},{"speaker":"Officer","ru":"Do you speak English?","es":"Вы говорите по-английски?"},{"speaker":"Ivan","ru":"A little. Can you speak more slowly, please?","es":"Немного. Говорите, пожалуйста, помедленнее."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2d36e78a-b62a-58d3-b418-c448daed5920', 'e26ba673-3dd9-5ba4-9865-014a9d03dd37', 7, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"Can you speak more slowly, please?","lang":"en"}'::jsonb, 'more slowly — помедленнее. Самая полезная фраза для начинающего.', 10) on conflict (id) do nothing;
