insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6bb99e17-75bc-5871-8d0c-30c371d3ac19', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 0, 'text', 'Для того, что происходит регулярно', '{"md":"**Present Simple** описывает привычки, распорядок и общие факты: **I work from home.** (Я работаю из дома.) **She drinks coffee every morning.** (Она пьёт кофе каждое утро.) Глагол почти не меняется — всего одно окончание."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1f3506b4-b908-51e2-98e6-08ff53ea7557', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 1, 'grammar', 'Единственное правило: -s с he, she, it', '{"md":"С **he, she, it** глагол получает **-s**: **I work → she works**. После -o, -sh, -ch, -x — **-es** (**goes, watches**). Согласная + y → **-ies** (**study → studies**). Исключение: **have → has**."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5e778d0d-863f-568d-8471-6714048725b8', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 2, 'table', 'Work в Present Simple', '{"headers":["Лицо","Глагол"],"rows":[["I / you / we / they","work"],["he / she / it","works"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('52328ff2-8569-5efa-840f-055c742c3ed3', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 3, 'grammar', 'grammar', 'My brother ___ in a bank.', '', '{"lang":"en"}'::jsonb, 'my brother = he → works.', 10) on conflict (id) do nothing;
