insert into public.exercise_solutions (exercise_id, solution) values ('6af1aa4f-3a93-5441-9602-cc698b6111b8', '{"correct":"has"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6d3d8dcb-4a6e-5902-ac23-ca199b1d2af9', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 6, 'tip', 'Как звучит -s', '{"md":"Русскоговорящие часто «проглатывают» -s, а носители сразу это слышат. После глухих звуков — **[с]**: **works** [уё:кс]; после звонких — **[з]**: **plays** [плэйз]; после s, sh, ch — **[из]**: **watches** [уо́чиз]."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('542033b5-e284-5ed2-af61-39ceece737b4', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 7, 'grammar', 'Simple или Continuous?', '{"md":"В русском одно настоящее время: «я работаю». В английском два. **I work** — обычно, регулярно (**every day, usually**). **I''m working** — прямо сейчас (**now, at the moment**): am/is/are + глагол с **-ing**. **I work in a bank, but now I''m working from home.** Ошибка «I am work» — смешение двух времён."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('de80e2bf-8897-5c27-9d47-4a7a948c7ad9', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 8, 'grammar', 'grammar', 'Сейчас я читаю.', '', '{"lang":"en"}'::jsonb, 'Прямо сейчас → am + -ing.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('00ac1375-8bb0-5deb-b0d2-c34c2f4213d5', 'de80e2bf-8897-5c27-9d47-4a7a948c7ad9', 'I''m reading now.', 0) on conflict (id) do nothing;
