insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('23d9e5a5-eac7-57c9-ac65-bf13fb948b64', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 10, 'example', 'Распорядок дня', '{"items":[{"ru":"I wake up at seven.","es":"Я просыпаюсь в семь."},{"ru":"I have breakfast.","es":"Я завтракаю."},{"ru":"I work from home.","es":"Я работаю из дома."},{"ru":"I go to bed at eleven.","es":"Я ложусь спать в одиннадцать."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d65be582-0de7-5e3d-80a2-62ac2748bbe1', '4017af46-fa60-5bb0-b67e-1c7d41f74ffe', 11, 'fill_blank', 'grammar', 'Она учит английский: She ___ English.', '', '{"sentence":"She ___ English.","keyboard":true,"lang":"en"}'::jsonb, 'study → studies (или learns).', 10) on conflict (id) do nothing;
