insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('1d57e595-86d9-5f99-9735-a91558ed28e0', '4bd230b7-d5f7-593c-b5e1-2b9bac6737a6', 'enru-do-does', 'Вопросы и отрицания: do и does', 'Вспомогательный глагол do/does и почему пропадает -s.', array['Задавать вопросы в Present Simple', 'Отрицать с don''t и doesn''t', 'Не путать do и be']::text[], 1, 13, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
