insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('99a07766-a24b-56fc-9c62-f1c7086fdfdc', '1d57e595-86d9-5f99-9735-a91558ed28e0', 0, 'text', 'Вспомогательный глагол', '{"md":"По-русски вопрос задают интонацией: «Ты работаешь здесь?». По-английски «You work here?» звучит как удивлённое переспрашивание. Для вопросов и отрицаний в Present Simple нужен **помощник**: **do** (или **does** с he, she, it)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d12987de-9104-5ddb-a3c1-30e0909e3ec9', '1d57e595-86d9-5f99-9735-a91558ed28e0', 1, 'table', 'Do и does', '{"headers":["","I / you / we / they","he / she / it"],"rows":[["Вопрос","Do you work?","Does she work?"],["Отрицание","I don''t work.","She doesn''t work."],["Краткий ответ","Yes, I do. / No, I don''t.","Yes, she does. / No, she doesn''t."]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4548d6df-3a0a-56b5-be37-fb43b07d324c', '1d57e595-86d9-5f99-9735-a91558ed28e0', 2, 'tip', '-s ставится только один раз', '{"md":"Если уже есть **does** или **doesn''t**, основной глагол возвращается к начальной форме: **Does she work?** (не «does she works»). **He doesn''t like coffee.** (не «doesn''t likes»)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('b0cf9312-b688-57e8-a308-e645354ec5e3', '1d57e595-86d9-5f99-9735-a91558ed28e0', 3, 'grammar', 'grammar', '___ your sister live in London?', '', '{"lang":"en"}'::jsonb, 'your sister = she → Does.', 10) on conflict (id) do nothing;
