insert into public.exercise_solutions (exercise_id, solution) values ('c3cdba18-56e4-5e34-95f4-f43d80c7bf8c', '{"correct":"don''t"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c9cdf7a7-db2d-57bd-95f6-3c41d644095e', '1d57e595-86d9-5f99-9735-a91558ed28e0', 6, 'tip', 'Do или be?', '{"md":"Если в предложении **действие** (work, like, live) — помощник **do**. Если **состояние или признак** (tired, hungry, a student, at home) — **be**. Поэтому «Ты голоден?» — **Are you hungry?**, а не «Do you hungry?»; «Я не устал» — **I''m not tired**, а не «I don''t tired»."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3990e96f-d045-5d04-a263-1828deaa3394', '1d57e595-86d9-5f99-9735-a91558ed28e0', 7, 'grammar', 'grammar', 'Ты голоден? «___ you hungry?»', '', '{"lang":"en"}'::jsonb, 'hungry — признак, значит be: Are you hungry?', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('9289b554-9c9f-59c3-bf56-80a4eaedf266', '3990e96f-d045-5d04-a263-1828deaa3394', 'Are', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('36b7eb2b-fec9-56ed-a232-6d19e1326805', '3990e96f-d045-5d04-a263-1828deaa3394', 'Do', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('bee11fe4-a157-5222-88fd-606aec20d349', '3990e96f-d045-5d04-a263-1828deaa3394', 'Does', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('3990e96f-d045-5d04-a263-1828deaa3394', '{"correct":"Are"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4837ed6c-5861-5e2d-81f5-c7f42d9389af', '1d57e595-86d9-5f99-9735-a91558ed28e0', 8, 'grammar', 'Вопросы с вопросительным словом', '{"md":"В русском порядок слов свободный: «Где ты живёшь?», «Ты где живёшь?». В английском он **жёсткий**: вопросительное слово + do/does + подлежащее + глагол. **What do you do?** (Кем вы работаете?) · **Where do you live?** (Где вы живёте?) · **What time does the shop open?** (Во сколько открывается магазин?)"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('f7db0693-889d-5e83-bc4a-86a01a04630d', '1d57e595-86d9-5f99-9735-a91558ed28e0', 9, 'order_words', 'grammar', 'Соберите вопрос: «Где ты живёшь?»', '', '{"tokens":["do","Where","live","you"],"lang":"en"}'::jsonb, 'Where do you live?', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('f7db0693-889d-5e83-bc4a-86a01a04630d', '{"accepted":["Where do you live"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('0858d146-8173-58ac-a398-ef711384818b', '1d57e595-86d9-5f99-9735-a91558ed28e0', 10, 'dialogue', 'Знакомство с коллегой', '{"lines":[{"speaker":"Sam","ru":"What do you do?","es":"Кем ты работаешь?"},{"speaker":"Olga","ru":"I''m a designer. I work from home.","es":"Я дизайнер. Работаю из дома."},{"speaker":"Sam","ru":"Do you like it?","es":"Тебе нравится?"},{"speaker":"Olga","ru":"Yes, I do! But I don''t like meetings.","es":"Да! Но не люблю совещания."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2a9e7316-83f4-55c7-8139-a8112ac4b069', '1d57e595-86d9-5f99-9735-a91558ed28e0', 11, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"Does he speak Russian?","lang":"en"}'::jsonb, 'Обратите внимание: does + he.', 10) on conflict (id) do nothing;
