insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('58c2badc-bc5b-5a0a-ae82-11267384f24c', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 0, 'grammar', 'Который час?', '{"md":"**What time is it?** — **It''s ten o''clock** (ровно десять). **It''s half past ten** (10:30). **It''s quarter to eleven** (без четверти одиннадцать, 10:45). В жизни часто говорят как на электронных часах: **It''s ten thirty**, **It''s ten forty-five**. Вместо 24-часового формата — **a.m.** (до полудня) и **p.m.** (после): **9 p.m.** = 21:00."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e3a3c893-864f-534a-b964-718ac7c62dc1', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 1, 'tip', 'Половина восьмого ≠ half past eight', '{"md":"Ловушка для русскоговорящих: «половина **восьмого**» — это 7:30, а по-английски считают от **прошедшего** часа: **half past seven** (дословно «полчаса после семи»). Так же «четверть девятого» (8:15) — **quarter past eight**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('a3059700-324d-5d6f-bf89-a971e790ed4b', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 2, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"It''s half past seven.","lang":"en"}'::jsonb, 'half past seven = 7:30, «половина восьмого».', 10) on conflict (id) do nothing;
