insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c01f7bc7-278c-5b79-9d1c-7493237962c0', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 7, 'grammar', 'Как часто?', '{"md":"**always** (всегда) · **usually** (обычно) · **sometimes** (иногда) · **never** (никогда). Ставятся **перед смысловым глаголом**: **I usually work from home.** Но **после to be**: **I''m always tired.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('01a670b2-57a6-5759-8633-c07e267f0ba4', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 8, 'tip', 'Never — без второго «не»', '{"md":"По-русски «Я **никогда не** ем мясо» — два отрицания. По-английски только одно: **I never eat meat.** Фраза «I never don''t eat» — ошибка."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('d811671c-9352-5b9f-9083-3c41528ba6f3', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 9, 'grammar', 'grammar', 'Я никогда не ем мясо.', '', '{"lang":"en"}'::jsonb, 'Одно отрицание, never — перед глаголом.', 10) on conflict (id) do nothing;
