insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('3a0e9aad-17e0-544d-bd2c-f87ca330af30', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 10, 'example', 'Дни недели', '{"items":[{"ru":"Monday, Tuesday, Wednesday","es":"понедельник, вторник, среда · [ма́ндэй, тью́:здэй, уэ́нздэй]"},{"ru":"Thursday, Friday","es":"четверг, пятница · [θё́:здэй, фра́йдэй]"},{"ru":"Saturday, Sunday","es":"суббота, воскресенье · [сэ́тэдэй, са́ндэй]"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('dacd7fd6-c5a3-5089-8884-2671339a890e', '6b1a2462-ee30-570d-b1dc-1c899c213e21', 11, 'reading_comprehension', 'reading', 'Что автор всегда делает по субботам?', '', '{"text":"I usually get up at seven. On Saturdays I always sleep late. I never work on Sundays.","lang":"en"}'::jsonb, 'On Saturdays I always sleep late.', 10) on conflict (id) do nothing;
