insert into public.exercise_options (id, exercise_id, label, order_index) values ('a58d7c2b-4b70-5843-b6f0-597a32121387', 'cc2668e2-e72a-5668-9bfd-e30e7e30f51c', 'спать', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('cc2668e2-e72a-5668-9bfd-e30e7e30f51c', '{"correct":"смотреть"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b427a1c7-6db1-5d7a-8167-4db2bdc810ce', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 0, 'text', 'Вежливость — в форме вопроса', '{"md":"По-русски «Дайте, пожалуйста, кофе» — вполне вежливо. По-английски **Give me a coffee** звучит резко, даже с please. Естественно говорить **Can I have…?** или **I''d like…** (я бы хотел) и не забывать **please** и **thank you** — англоговорящие используют их гораздо чаще, чем мы."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d82d6f74-bc64-5d42-a37d-6fd123eefe84', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 1, 'example', 'Фразы для заказа', '{"items":[{"ru":"Can I have a coffee, please?","es":"Можно мне кофе, пожалуйста?"},{"ru":"I''d like a sandwich, please.","es":"Я бы хотел сэндвич, пожалуйста."},{"ru":"For here or to go?","es":"Здесь или с собой?"},{"ru":"To go, please.","es":"С собой, пожалуйста."},{"ru":"Can I pay by card?","es":"Можно оплатить картой?"},{"ru":"Here you are.","es":"Вот, пожалуйста. (когда что-то даёте)"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('827fc2b2-b418-53c0-9bb1-16c9db625cdc', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 2, 'multiple_choice', 'vocabulary', 'Какой вариант самый вежливый?', '', '{"lang":"en"}'::jsonb, 'Can I have…, please? — стандартная вежливая формула.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d5132c36-ebcd-5b4d-96b3-0291ad1aaee2', '827fc2b2-b418-53c0-9bb1-16c9db625cdc', 'Can I have a tea, please?', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('2272f9fa-72a7-5edf-ac20-fc90c11bc375', '827fc2b2-b418-53c0-9bb1-16c9db625cdc', 'Give me a tea.', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d52c3d05-9e0d-5478-8c1a-93da8545ed56', '827fc2b2-b418-53c0-9bb1-16c9db625cdc', 'I want tea.', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('827fc2b2-b418-53c0-9bb1-16c9db625cdc', '{"correct":"Can I have a tea, please?"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('7010e023-e3ae-5795-8dcc-1c27b186318a', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 3, 'grammar', 'I''d like и Would you like…?', '{"md":"**I''d like** = I would like (я бы хотел). Пригодится в магазине, ресторане, отеле: **I''d like a room for two nights.** Когда предлагают: **Would you like some water?** (Хотите воды?) — отвечайте **Yes, please.** или **No, thank you.** Одно «Yes» без please звучит грубовато."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('c868f31e-1aef-5166-a433-9e52a0ab0027', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 4, 'grammar', 'grammar', 'Я бы хотел воды: «I''d ___ some water, please.»', '', '{"lang":"en"}'::jsonb, 'I''d like + что-то.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('951b9a6e-992e-5322-8bd5-6e76565ac07c', 'c868f31e-1aef-5166-a433-9e52a0ab0027', 'like', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('3cff4d96-1555-5e34-a271-b69a75de1709', 'c868f31e-1aef-5166-a433-9e52a0ab0027', 'likes', 1) on conflict (id) do nothing;
