insert into public.exercise_solutions (exercise_id, solution) values ('c868f31e-1aef-5166-a433-9e52a0ab0027', '{"correct":"like"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1933ad03-a932-5305-9257-844a37eadff5', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 5, 'tip', 'A coffee, two coffees', '{"md":"В кафе напиток считают порциями: **a coffee** = одна чашка кофе, **two coffees** = две чашки. А когда говорите о напитке вообще, артикль не нужен: **I like coffee.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('aba7c5a2-cc63-5a33-8be0-f99ee8860e09', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 6, 'dialogue', 'Кофе с собой', '{"lines":[{"speaker":"Barista","ru":"Hi! What can I get you?","es":"Здравствуйте! Что для вас?"},{"speaker":"You","ru":"Can I have a latte, please?","es":"Можно мне латте, пожалуйста?"},{"speaker":"Barista","ru":"Sure. For here or to go?","es":"Конечно. Здесь или с собой?"},{"speaker":"You","ru":"To go, please. Can I pay by card?","es":"С собой. Можно картой?"},{"speaker":"Barista","ru":"Of course. That''s four fifty.","es":"Конечно. С вас четыре пятьдесят."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('394ebd39-f84f-5f2a-beb9-5094c03bd115', 'c7658042-0ae6-58ab-864c-a4d761c54a42', 7, 'listen_select', 'listening', 'Послушайте и выберите, что вы слышите.', '', '{"audio_text":"For here or to go?","lang":"en"}'::jsonb, 'Этот вопрос вам зададут в любой кофейне.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('44058dcc-7525-5ac8-b547-ceb73152759b', '394ebd39-f84f-5f2a-beb9-5094c03bd115', 'For here or to go?', 0) on conflict (id) do nothing;
