insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6cf06a98-b341-5b31-9ac0-f45a906f4b9a', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 0, 'grammar', 'Есть: there is / there are', '{"md":"По-русски «В комнате диван» или «Рядом есть банк». По-английски сначала **there is / there are**, потом **что**, потом **где**: **There''s a bank near here.** (Рядом есть банк.) **There are two supermarkets.** Вопрос: **Is there a pharmacy near here?** — **Yes, there is. / No, there isn''t.**"}'::jsonb) on conflict (id) do nothing;
