insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5a9a3fde-7c79-5485-a756-ad7c5f25584d', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 4, 'tip', 'Сначала a, потом the', '{"md":"Когда предмет упоминается **впервые** — **a**: **There''s a bank near here.** Когда уже понятно, о каком речь, — **the**: **The bank is open until six.** Так же «тот самый, единственный»: **the station**, **the park** (в этом районе)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ab28c1d5-c272-5954-9a98-564e9b9957b6', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 5, 'table', 'Предлоги места', '{"headers":["Английский","Русский"],"rows":[["next to","рядом с"],["opposite","напротив"],["between","между"],["on the corner","на углу"],["on the left / right","слева / справа"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('b6b9b6c8-9a81-56aa-bd39-9783d060306b', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 6, 'example', 'Как пройти', '{"items":[{"ru":"Excuse me, where''s the station?","es":"Извините, где вокзал?"},{"ru":"Go straight on.","es":"Идите прямо."},{"ru":"Turn left at the bank.","es":"У банка поверните налево."},{"ru":"It''s on your right.","es":"Это справа от вас."},{"ru":"It''s five minutes on foot.","es":"Это пять минут пешком."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5cb4d183-dfac-5aad-bc4f-8108a771d333', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 7, 'listen_select', 'listening', 'Послушайте и выберите перевод.', '', '{"audio_text":"Turn right at the corner.","lang":"en"}'::jsonb, 'right — направо; left — налево.', 10) on conflict (id) do nothing;
