insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('f2140a6a-0af8-5cb2-87bc-1db0bb0edc0e', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 8, 'tip', 'Excuse me или Sorry?', '{"md":"По-русски «извините» говорят и до, и после. В английском **Excuse me** — **до**: чтобы привлечь внимание или пройти. **Sorry** — **после** ошибки или чтобы переспросить: **Sorry?** = «Простите, что вы сказали?»"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('a91ebba0-5e79-5c2a-890f-62c7600c6a21', 'a4d5990f-c587-5ecc-b9eb-0b346f9a55b0', 9, 'multiple_choice', 'vocabulary', 'Вы хотите спросить прохожего о дороге. Начните с…', '', '{"lang":"en"}'::jsonb, 'Excuse me — вежливо привлечь внимание.', 10) on conflict (id) do nothing;
