insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('aef666b0-f8a4-557e-97e9-76af5430d3e5', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 0, 'grammar', 'Не так, как в русском', '{"md":"По-русски «**Мне** нравится кофе» — кофе здесь подлежащее. В английском прямо: **I like coffee** (я люблю кофе). Поэтому: **She likes music.** (Ей нравится музыка.) **Do you like sushi?** И никакого «Me like» — только **I like**."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('bc87298c-6e54-54ab-8fd8-222bfd64f29c', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 1, 'grammar', 'grammar', 'Ему нравится футбол: «He ___ football.»', '', '{"lang":"en"}'::jsonb, 'He → likes.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('bb5acd5f-03ca-5f81-af86-7ce76f0da596', 'bc87298c-6e54-54ab-8fd8-222bfd64f29c', 'likes', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8aa8ac37-aec2-595b-a87e-654f48da6ab4', 'bc87298c-6e54-54ab-8fd8-222bfd64f29c', 'like', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('6c5654cc-cd18-5953-9dd9-334bc0537cec', 'bc87298c-6e54-54ab-8fd8-222bfd64f29c', 'is like', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('bc87298c-6e54-54ab-8fd8-222bfd64f29c', '{"correct":"likes"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('dab0acd2-bf2f-5796-998f-d12d7114bc5f', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 2, 'grammar', 'Like + -ing и I''d like to', '{"md":"О занятиях говорят с **-ing**: **I like reading.** (Я люблю читать.) **I love travelling.** (Обожаю путешествовать.) **I hate getting up early.** (Терпеть не могу рано вставать.) А конкретное желание — **I''d like to** + глагол: **I''d like to travel to London.** (Я бы хотел поехать в Лондон.)"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('2bb431fd-d1df-50f4-b9fe-dd86fee93715', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 3, 'grammar', 'grammar', 'Я обожаю готовить: «I love ___.»', '', '{"lang":"en"}'::jsonb, 'love + -ing.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('cbbf4875-746d-5664-924d-40e00a451ab0', '2bb431fd-d1df-50f4-b9fe-dd86fee93715', 'cooking', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('da351621-6147-53a3-9be3-194364127e7b', '2bb431fd-d1df-50f4-b9fe-dd86fee93715', 'cook', 1) on conflict (id) do nothing;
