insert into public.exercise_solutions (exercise_id, solution) values ('2bb431fd-d1df-50f4-b9fe-dd86fee93715', '{"correct":"cooking"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4dde4721-0177-5a8c-be89-33b43e5e0ad7', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 4, 'table', 'От «обожаю» до «терпеть не могу»', '{"headers":["Английский","Русский"],"rows":[["I love…","Я обожаю…"],["I like…","Мне нравится…"],["I don''t mind…","Я не против…"],["I don''t like…","Мне не нравится…"],["I hate…","Терпеть не могу…"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('c1e17efe-ec0e-56c7-b78a-087141183b76', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 5, 'dialogue', 'Планы на выходные', '{"lines":[{"speaker":"Ella","ru":"What do you like doing at the weekend?","es":"Что ты любишь делать на выходных?"},{"speaker":"Max","ru":"I love going to the beach. And you?","es":"Обожаю ходить на пляж. А ты?"},{"speaker":"Ella","ru":"I don''t like the sun. I like watching series at home.","es":"Я не люблю солнце. Люблю смотреть сериалы дома."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3a779c6a-1dd3-53fe-8cf0-c538063604ca', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 6, 'listen_select', 'listening', 'Послушайте и выберите перевод.', '', '{"audio_text":"I don''t mind waiting.","lang":"en"}'::jsonb, 'I don''t mind = я не против.', 10) on conflict (id) do nothing;
