insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8a9902aa-6425-512d-9ea9-bd37da90547a', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 7, 'text', 'Повторение A1', '{"md":"Вы уже умеете: **здороваться** (Hello, Nice to meet you), **представляться** (I''m…, I''m from…), говорить **возраст** с to be, не забывать **am/is/are** и артикль **a/an**, рассказывать о **семье** с his/her, использовать **Present Simple** с -s и отличать его от «прямо сейчас», задавать вопросы с **do/does**, называть **время** с at/on/in, **заказывать** с Can I have…? и говорить **there is/are**. Проверьте себя в последних упражнениях."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('efc44e9c-1d4b-5a36-9ddc-951c2baf1970', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 8, 'grammar', 'grammar', 'Повторение: «Я студент».', '', '{"lang":"en"}'::jsonb, 'Нужны и to be, и артикль a.', 10) on conflict (id) do nothing;
