insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('14749b06-c2e3-51d5-a05d-f8e8289d1c11', '5644d5a8-303b-5eb3-9a9d-492fb72b7989', 1000, 'tip', '💪 Итоговая практика', '{"md":"Теперь поработай с новыми словами: **сопоставь, послушай, узнай и произнеси вслух**. Так слова переходят из «где-то встречались» в «точно знаю»."}'::jsonb) on conflict (id) do nothing;
