insert into public.courses (id, slug, title, subtitle, description, level, order_index, is_premium, status, source, target_language, source_language) values ('988c9084-1f86-5563-b356-509abf187418', 'russian-first-steps', 'Russian · First Steps', 'From the Cyrillic alphabet to your first real conversations', 'Read Cyrillic in two lessons, say words with the right stress, introduce yourself, talk about what you have, count, say where things are and use your first verbs. Free and complete.', 'A1', 10, false, 'published', 'complementary', 'ru', 'en') on conflict (id) do nothing;
