insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', '48d102cb-02c8-5e9e-b0a3-9007a502eb1f', 'ruen-look-alikes', 'Cyrillic 1: Friends and false friends', 'Letters that look and sound like English, and the ones that look English but aren''t.', array['Read 12 Cyrillic letters', 'Avoid the false friends Р, Н, В, С, У, Х', 'Read your first Russian words']::text[], 0, 10, 45, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('14cdea95-74b0-51ea-b264-d7e30746fdc3', 'cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', 0, 'text', 'How this course works', '{"md":"Every lesson follows the same cycle: you **understand** the rule in English, **listen** to real Russian (tap the speaker), **practise** with short exercises and **speak** aloud into the microphone. In brackets you''ll see the pronunciation in English spelling: the syllable in **CAPITALS** is the stressed one, and an apostrophe '' means a soft consonant. The Russian alphabet, **Cyrillic**, has 33 letters, but you already know more of them than you think."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ce60e0a4-340e-5c1d-86b8-60bd9b2912aa', 'cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', 1, 'example', 'Five true friends: they look and sound like English', '{"items":[{"ru":"А а","es":"[a] as in «father»"},{"ru":"К к","es":"[k] as in «skin», without a puff of air"},{"ru":"М м","es":"[m] as in «mum»"},{"ru":"О о","es":"[o] as in «more» (when stressed)"},{"ru":"Т т","es":"[t] as in «stop», tongue touching the teeth"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('a3cb2174-076a-5b3d-8d62-e10e531541a1', 'cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', 2, 'recognize_letter', 'reading', 'Which letter sounds like [m]?', '', '{}'::jsonb, 'М м = [m], as in ма́ма [MA-ma] (mum).', 10) on conflict (id) do nothing;
