insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fbc9fb9e-f558-5ce4-94b1-c5894e2bb41e', 'cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', 5, 'table', 'Seven false friends', '{"caption":"These cause most reading mistakes at the start: read them slowly until they feel natural.","headers":["Letter","Looks like","Sounds like","Example"],"rows":[["В в","B","[v]","вот [vot] here is"],["Н н","H","[n]","нос [nos] nose"],["Р р","P","[r], rolled","рот [rot] mouth"],["С с","C","[s]","сок [sok] juice"],["У у","y","[oo] as in «food»","у́тро [OO-tra] morning"],["Х х","X","[kh] as in «loch»","хор [khor] choir"],["Е е","E","[ye] as in «yes»","нет [nyet] no"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('926849b0-5e27-5838-9abc-396d2a00762c', 'cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', 6, 'tip', 'The rolled Р and the rough Х', '{"md":"**Р** is never the English r. Flick the tip of your tongue against the ridge behind your upper teeth, like the Scottish r or the «tt» in American «butter»: **рот** [rot]. **Х** is not an h and not a k: it''s the friction sound at the back of the mouth in Scottish **loch** or German **Bach**: **хор** [khor]."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('756a6f6b-2ace-5863-819e-bfeb01e2e07c', 'cdb6f4aa-3fe5-5d08-8a8d-60c18da06af2', 7, 'match_pairs', 'reading', 'Match each letter with its sound.', '', '{"left":["Н","Р","С","В","У"],"right":["[s]","[r]","[n]","[oo]","[v]"]}'::jsonb, 'Н = n, Р = r, С = s, В = v, У = oo.', 10) on conflict (id) do nothing;
