insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5a8d9ac3-a913-5754-8659-29e1548e9ad7', '95567024-8dfc-5428-b3e9-dc180ac119c5', 0, 'text', 'The rest of the alphabet', '{"md":"The remaining letters fall into easy groups: letters with sounds you know (some borrowed from Greek), **hissing** letters for sounds English writes with two letters (sh, ch, ts), and **vowels that start with a [y]**. Two signs, **Ь** and **Ъ**, have no sound at all: you''ll meet Ь in lesson 4, and Ъ is rare (it just keeps a consonant and a [y] apart, as in **объе́кт** [ab-YEKT])."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1488b052-f2fc-563a-a9a1-3622e7c5ae67', '95567024-8dfc-5428-b3e9-dc180ac119c5', 1, 'table', 'New shapes, familiar sounds', '{"headers":["Letter","Sound","Example"],"rows":[["Б б","[b]","банк [bank] bank"],["Г г","[g], always as in «go»","гора́ [ga-RA] mountain"],["Д д","[d]","да [da] yes"],["З з","[z]","ва́за [VA-za] vase"],["И и","[ee]","и [ee] and"],["Й й","[y] as in «boy»","мой [moy] my"],["Л л","[l]","ла́мпа [LAM-pa] lamp"],["П п","[p]","па́па [PA-pa] dad"],["Ф ф","[f]","фо́то [FO-ta] photo"],["Э э","[e] as in «met»","э́то [E-ta] this"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('4d33e164-725d-53cf-bfd2-c576bc853bd1', '95567024-8dfc-5428-b3e9-dc180ac119c5', 2, 'recognize_letter', 'reading', 'Which letter sounds like [p]?', '', '{}'::jsonb, 'П = [p]: па́па [PA-pa]. Careful: Р is [r].', 10) on conflict (id) do nothing;
