insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5981ae44-8e09-52bc-97c8-75eed080bb09', '95567024-8dfc-5428-b3e9-dc180ac119c5', 3, 'table', 'The hissing letters', '{"caption":"English needs two letters for these sounds; Russian needs one.","headers":["Letter","Sound","Example"],"rows":[["Ж ж","[zh] as in «pleasure»","журна́л [zhoor-NAL] magazine"],["Ш ш","[sh] as in «shop»","шко́ла [SHKO-la] school"],["Щ щ","a long, soft [sh'']","борщ [borsh''] borscht"],["Ц ц","[ts] as in «cats»","центр [tsentr] centre"],["Ч ч","[ch] as in «cheese»","чай [chay] tea"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('db4f81d3-2bdb-5122-8351-bf7b8743ddc9', '95567024-8dfc-5428-b3e9-dc180ac119c5', 4, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"чай"}'::jsonb, 'чай [chay] = tea. дай [day] = give; чей [chey] = whose.', 10) on conflict (id) do nothing;
