insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('263bf65e-163e-5c22-93e8-482302fc2c5a', '95567024-8dfc-5428-b3e9-dc180ac119c5', 5, 'tip', 'Г is always hard, Й is never a vowel', '{"md":"**Г** always sounds like the g in **go**, never like the g in **gym**: гид [geet] (guide). **Й** is a short [y] glued to a vowel: **мой** [moy], **чай** [chay]. It never makes a syllable by itself."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d78442e6-982e-5c44-a671-13a4c171c7c9', '95567024-8dfc-5428-b3e9-dc180ac119c5', 6, 'table', 'Vowels that start with a [y]', '{"caption":"After a consonant they don''t add a [y]: they make that consonant soft (lesson 4).","headers":["Letter","Sound","Example"],"rows":[["Я я","[ya]","я [ya] I"],["Ю ю","[yoo]","ю́мор [YOO-mar] humour"],["Е е","[ye]","нет [nyet] no"],["Ё ё","[yo], always stressed","ёлка [YOL-ka] fir tree"]]}'::jsonb) on conflict (id) do nothing;
