insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('6be28cad-e711-5d71-b64d-35a4fd259b4f', '48d102cb-02c8-5e9e-b0a3-9007a502eb1f', 'ruen-stress', 'Stress and the о that sounds like а', 'One loud syllable per word, weak vowels everywhere else, and voiceless final consonants.', array['Hear and place word stress', 'Pronounce unstressed о as [a]', 'Devoice final consonants']::text[], 2, 11, 80, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('94b42862-9b13-5645-8496-0c224efbbd8b', '6be28cad-e711-5d71-b64d-35a4fd259b4f', -100, 'tip', '🔁 Warm-up', '{"md":"Before you start, **recall** two words from earlier lessons. Remembering right when you''re about to forget is what makes vocabulary stick."}'::jsonb) on conflict (id) do nothing;
