insert into public.exercise_options (id, exercise_id, label, order_index) values ('4e0ca198-ec0c-5f67-b454-3942168f536f', 'a5c37673-ce8e-5575-aa61-e7ffee1bc859', 'dad', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('a5c37673-ce8e-5575-aa61-e7ffee1bc859', '{"correct":"and"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8346c39d-bd8a-5bdd-aadd-1b3a39eb08c7', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 0, 'text', 'One syllable rules the word', '{"md":"Every Russian word has **one stressed syllable**: louder, longer and clearer than the rest. The stress can fall on any syllable and isn''t shown in normal texts, so in this course we mark it with an accent: **молоко́**. Learn each new word **with its stress**: it changes how all the other vowels sound and can even change the meaning."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('d62c5d00-ee75-5301-8e16-dd2ad77dfefe', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 1, 'example', 'Same letters, different stress', '{"items":[{"ru":"за́мок","es":"[ZA-mak] castle"},{"ru":"замо́к","es":"[za-MOK] lock"},{"ru":"пла́чу","es":"[PLA-choo] I cry"},{"ru":"плачу́","es":"[pla-CHOO] I pay"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('9e8826d7-8b4d-5121-a485-ac8dbecc00e8', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 2, 'listen_select', 'listening', 'Listen to the stress. What does the word mean?', '', '{"audio_text":"замо́к"}'::jsonb, 'замо́к [za-MOK] = lock; за́мок [ZA-mak] = castle.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('eba55586-2866-5226-a289-c4188d65a137', '9e8826d7-8b4d-5121-a485-ac8dbecc00e8', 'lock', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('5a8c1591-80ed-5b8b-b150-9390b618b2d8', '9e8826d7-8b4d-5121-a485-ac8dbecc00e8', 'castle', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('9e8826d7-8b4d-5121-a485-ac8dbecc00e8', '{"correct":"lock"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('146ee0e1-76f0-51e6-9616-e1badb08ca08', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 3, 'grammar', 'Unstressed о sounds like а', '{"md":"**О** sounds [o] **only when stressed**. Everywhere else it turns into [a], or a short [uh] further from the stress. This is the most important rule of Russian pronunciation, and spelling won''t help you: **молоко́** is said [ma-la-KO], **хорошо́** [kha-ra-SHO], **Москва́** [mas-KVA]."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('edd4dcf7-7b98-550b-9b8d-1e2782e58b01', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 4, 'table', 'Written vs. said', '{"caption":"Only the stressed о keeps its [o].","headers":["Written","Said","Meaning"],"rows":[["молоко́","[ma-la-KO]","milk"],["хорошо́","[kha-ra-SHO]","good, fine"],["Москва́","[mas-KVA]","Moscow"],["спаси́бо","[spa-SEE-ba]","thank you"],["окно́","[ak-NO]","window"],["ко́фе","[KO-fee]","coffee"]]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('746b8d30-de9f-5405-b951-cda9a874d685', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 5, 'true_false', 'speaking', 'True or false?', 'In молоко́ all three о''s sound the same.', '{}'::jsonb, 'Only the last, stressed о is [o]: [ma-la-KO]. The first two sound like [a].', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('746b8d30-de9f-5405-b951-cda9a874d685', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('87a46738-b1a5-565a-9fa5-bfb2013b7153', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 6, 'grammar', 'Е and я get weaker too', '{"md":"Unstressed **е** and **я** sound close to a short [ee]: **сестра́** [see-STRA], **река́** [ree-KA] (river), **телефо́н** [tee-lee-FON]. Stressed, they''re full [ye] and [ya]: **нет** [nyet], **я** [ya]."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('0775122e-7fee-53ef-91f0-6880002de261', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 7, 'multiple_choice', 'speaking', 'Which syllable is stressed in спаси́бо?', '', '{}'::jsonb, 'спа-СИ́-бо [spa-SEE-ba]: the final о is unstressed, so it sounds like [a].', 10) on conflict (id) do nothing;
