insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ad105f4f-e40b-519e-85dd-f813fc53d495', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 9, 'tip', 'Final consonants lose their voice', '{"md":"At the end of a word, **б, в, г, д, ж, з** are said like **п, ф, к, т, ш, с**: **хлеб** [khlyep] (bread), **го́род** [GO-rat] (city), **Ивано́в** [ee-va-NOF]. English speakers tend to keep the final [d] or [b] voiced: in Russian, let it go."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('815a8753-c5b4-5f51-a150-7a38e1cf5d0a', '6be28cad-e711-5d71-b64d-35a4fd259b4f', 10, 'match_pairs', 'reading', 'Match each word with how it sounds.', '', '{"left":["хорошо́","молоко́","хлеб","го́род"],"right":["[ma-la-KO]","[kha-ra-SHO]","[GO-rat]","[khlyep]"]}'::jsonb, 'Unstressed о → [a]; final б → [p], д → [t].', 10) on conflict (id) do nothing;
