insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5ff46dda-26c7-5a15-8ee7-cc3e3412ed87', '9b8b564e-9155-57eb-a950-4542e1ceea27', 0, 'text', 'Hard and soft', '{"md":"Most Russian consonants come in **two versions**. A **soft** consonant is said with the middle of your tongue raised towards the roof of your mouth, as if you were about to say a [y]. English has a hint of it in British **new** [nyoo] or **tune**. In Russian, hard or soft can change the whole word: **брат** [brat] = brother, **брать** [brat''] = to take."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('774a7858-cdb5-511c-9bbf-c034784787b6', '9b8b564e-9155-57eb-a950-4542e1ceea27', 1, 'table', 'Which letter shows softness?', '{"caption":"The vowel letter after a consonant tells you whether that consonant is hard or soft.","headers":["After a hard consonant","After a soft consonant"],"rows":[["а","я"],["о","ё"],["у","ю"],["э","е"],["ы","и"],["(nothing)","ь"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('bee0b7c9-26be-5558-9ec0-dd550b62d5c8', '9b8b564e-9155-57eb-a950-4542e1ceea27', 2, 'example', 'Hard or soft: listen to the difference', '{"items":[{"ru":"брат","es":"[brat] brother"},{"ru":"брать","es":"[brat''] to take"},{"ru":"лук","es":"[look] onion"},{"ru":"люк","es":"[lyook] hatch, manhole"},{"ru":"был","es":"[bɨl] (he) was"},{"ru":"бил","es":"[beel] (he) hit"}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('6e793d25-e84e-5c92-b36d-fc734e78c50f', '9b8b564e-9155-57eb-a950-4542e1ceea27', 3, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"брать"}'::jsonb, 'брать [brat''] ends in a soft т: the middle of your tongue rises towards the roof of your mouth, so it sounds almost like a short [ty]. брат [brat] = brother.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('851df16d-81c5-5f06-9a0c-5b9d5adb84d4', '6e793d25-e84e-5c92-b36d-fc734e78c50f', 'брат', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('f10555b3-8a7e-51c8-8cb1-1ab39eb0c1a5', '6e793d25-e84e-5c92-b36d-fc734e78c50f', 'брать', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('6e793d25-e84e-5c92-b36d-fc734e78c50f', '{"correct":"брать"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('cd36972c-d43d-5ad6-8255-fedd8f1d64f0', '9b8b564e-9155-57eb-a950-4542e1ceea27', 4, 'grammar', 'The soft sign Ь', '{"md":"**Ь** has no sound of its own: it makes the consonant before it soft. **мать** [mat''] (mother), **день** [dyen''] (day), **соль** [sol''] (salt). Between a consonant and a vowel it also adds a little [y]: **семья́** [seem''-YA] (family)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('03463beb-a2eb-55dc-8839-1baf7edc5550', '9b8b564e-9155-57eb-a950-4542e1ceea27', 5, 'grammar', 'Ы: the sound English doesn''t have', '{"md":"To say **ы**, start with **ee** and pull your tongue back, as if for **oo**, but keep your lips spread, not rounded. It''s a bit like the «i» in **bit** said far back in the throat. **ты** [tɨ] you, **мы** [mɨ] we, **вы** [vɨ] you (formal or plural), **сыр** [sɨr] cheese. Mixing up ы and и changes words: **был** (was) vs. **бил** (hit)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3abbee8a-4673-5e06-acf1-700875dfc3a2', '9b8b564e-9155-57eb-a950-4542e1ceea27', 6, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"был"}'::jsonb, 'был [bɨl] = (he) was; бил [beel] = (he) hit.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('ddbaaa40-f40c-5f89-973e-76e2bf02047a', '3abbee8a-4673-5e06-acf1-700875dfc3a2', 'был', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('bd35f1ed-e89c-57a5-8e23-4ce63e227197', '3abbee8a-4673-5e06-acf1-700875dfc3a2', 'бил', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('3abbee8a-4673-5e06-acf1-700875dfc3a2', '{"correct":"был"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('8ebd87b2-a14b-5491-808e-db8ae5c568f4', '9b8b564e-9155-57eb-a950-4542e1ceea27', 7, 'match_pairs', 'vocabulary', 'Match each word with its meaning.', '', '{"left":["ты","мы","сыр","мать","день"],"right":["cheese","we","you","day","mother"]}'::jsonb, 'ты = you, мы = we, сыр = cheese, мать = mother, день = day.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('8ebd87b2-a14b-5491-808e-db8ae5c568f4', '{"pairs":{"ты":"you","мы":"we","сыр":"cheese","мать":"mother","день":"day"}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5a07997b-b8f9-5359-ae9e-d7d1a5738b81', '9b8b564e-9155-57eb-a950-4542e1ceea27', 8, 'tip', 'Always hard, always soft', '{"md":"**Ж, Ш, Ц** are always hard: even written with и, they sound [ɨ]: **маши́на** [ma-SHƗ-na] (car). **Ч, Щ, Й** are always soft: **чай** [chay]. Spelling rule: after **ж, ш, ч, щ** we write **и**, never ы."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3d390762-0282-54bd-9161-d4bb6bb5a370', '9b8b564e-9155-57eb-a950-4542e1ceea27', 9, 'multiple_choice', 'reading', 'Which letter makes the consonant before it soft?', '', '{}'::jsonb, 'я, ё, ю, е, и and ь show a soft consonant; а, о, у, э, ы show a hard one.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4e8b96d6-ac4d-58aa-a96e-99f83a41bc84', '3d390762-0282-54bd-9161-d4bb6bb5a370', 'я', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('38333b33-305c-5417-bbc4-31554afa17dc', '3d390762-0282-54bd-9161-d4bb6bb5a370', 'а', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('dc32c7df-5415-51e7-b93a-263cee2d4208', '3d390762-0282-54bd-9161-d4bb6bb5a370', 'ы', 2) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('1ea652c6-a7a3-5806-ba60-f4dc82865073', '3d390762-0282-54bd-9161-d4bb6bb5a370', 'о', 3) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('3d390762-0282-54bd-9161-d4bb6bb5a370', '{"correct":"я"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('fc7db5dc-b230-586a-a0a8-0981d516bb7b', '9b8b564e-9155-57eb-a950-4542e1ceea27', 10, 'true_false', 'reading', 'True or false?', 'The soft sign Ь has its own sound.', '{}'::jsonb, 'Ь is silent: it only softens the consonant before it, as in мать [mat''].', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('fc7db5dc-b230-586a-a0a8-0981d516bb7b', '{"value":false}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('597729fd-7b3a-558d-b1a6-9ea9fbfa0e51', '9b8b564e-9155-57eb-a950-4542e1ceea27', 11, 'fill_blank', 'grammar', 'Add the letter that makes т soft: «mother» = мат___.', '', '{"sentence":"мат___","keyboard":true}'::jsonb, 'мать [mat'']: ь softens the т. Without it, мат is a different word (checkmate).', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('597729fd-7b3a-558d-b1a6-9ea9fbfa0e51', '{"accepted":["ь","мать"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('58915f92-e46d-59ee-b4a9-b5b11bc9153a', '9b8b564e-9155-57eb-a950-4542e1ceea27', 12, 'pronunciation', 'speaking', 'Say: «Мать, брат и сестра́ — семья́».', '', '{"audio_text":"Мать, брат и сестра́ — семья́."}'::jsonb, '[mat'', brat ee see-STRA — seem''-YA] = Mother, brother and sister: a family. Hear the soft т in мать and the hard т in брат.', 10) on conflict (id) do nothing;
