insert into public.exercise_options (id, exercise_id, label, order_index) values ('73bc85a8-239c-5d0e-829a-67a7b701b7d8', '77c106b9-f781-519d-bf07-6a206f96d4c5', 'photo', 0) on conflict (id) do nothing;
