insert into public.exercise_solutions (exercise_id, solution) values ('77c106b9-f781-519d-bf07-6a206f96d4c5', '{"correct":"bank"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('275bff31-9784-5c10-9ce7-dace4a4bd823', '78cef630-1655-5bb5-842c-54c9af3db6a6', 0, 'grammar', 'Two ways to say «you»', '{"md":"Russian has two words for **you**, like French or German. **ты** is for friends, family, children and people your age in relaxed settings. **вы** is for strangers, older people, colleagues and anyone you want to be polite with, and also for **more than one person**. When in doubt, use **вы**: it''s never rude."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2e85b238-bafb-5eb4-aac7-21ee9372901a', '78cef630-1655-5bb5-842c-54c9af3db6a6', 1, 'example', 'Saying hello', '{"items":[{"ru":"Здра́вствуйте!","es":"[ZDRAST-vooy-tye] Hello! (polite, to вы)"},{"ru":"Приве́т!","es":"[pree-VYET] Hi! (informal, to ты)"},{"ru":"До́брое у́тро!","es":"[DOB-ra-ye OO-tra] Good morning!"},{"ru":"До́брый день!","es":"[DOB-rɨy dyen''] Good afternoon! / Hello!"},{"ru":"До́брый ве́чер!","es":"[DOB-rɨy VYE-cheer] Good evening!"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4e05c7db-9088-5411-9af5-fa637bed993e', '78cef630-1655-5bb5-842c-54c9af3db6a6', 2, 'tip', 'The silent в in здра́вствуйте', '{"md":"Don''t let the spelling scare you: the first в is silent. Say [ZDRAST-vooy-tye]. In fast speech you''ll even hear [ZDRAS-tee]. **До́брый день** is a safe, polite alternative at any time from late morning to early evening."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e4c18e48-2a48-5bae-8c69-f93c0d9dc64d', '78cef630-1655-5bb5-842c-54c9af3db6a6', 3, 'multiple_choice', 'vocabulary', 'You meet your friend''s grandmother for the first time. What do you say?', '', '{}'::jsonb, 'An older person you don''t know → вы → Здра́вствуйте! Приве́т is only for friends; пока́ means «bye».', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('2fc50be3-d523-5f00-bf7d-caed1e3154c3', 'e4c18e48-2a48-5bae-8c69-f93c0d9dc64d', 'Здра́вствуйте!', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('68cd2b44-03a7-5147-95d2-784e0248b801', 'e4c18e48-2a48-5bae-8c69-f93c0d9dc64d', 'Приве́т!', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('1482949d-34ff-5c6c-8394-e04e6dab0588', 'e4c18e48-2a48-5bae-8c69-f93c0d9dc64d', 'Пока́!', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('e4c18e48-2a48-5bae-8c69-f93c0d9dc64d', '{"correct":"Здра́вствуйте!"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('e5436deb-9b20-526e-93aa-794957505e0e', '78cef630-1655-5bb5-842c-54c9af3db6a6', 4, 'grammar', 'Your name: меня́ зову́т…', '{"md":"Russians say **Меня́ зову́т А́нна** [mee-NYA za-VOOT AN-na], literally «Me they call Anna». To ask: **Как вас зову́т?** (polite) or **Как тебя́ зову́т?** (informal). After meeting someone: **О́чень прия́тно!** [O-cheen'' pree-YAT-na] = Nice to meet you! The reply: **Мне то́же** (me too)."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('316bf0da-a0bb-54c7-a0a5-f92071fae88a', '78cef630-1655-5bb5-842c-54c9af3db6a6', 5, 'dialogue', 'First day at a language school', '{"lines":[{"speaker":"Olga","ru":"Здра́вствуйте! Меня́ зову́т О́льга. А как вас зову́т?","es":"Hello! My name''s Olga. And what''s your name?"},{"speaker":"Tom","ru":"Меня́ зову́т Том.","es":"My name''s Tom."},{"speaker":"Olga","ru":"О́чень прия́тно, Том!","es":"Nice to meet you, Tom!"},{"speaker":"Tom","ru":"Мне то́же.","es":"Nice to meet you too."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('84287a34-1a6b-5911-8bc3-1689f60f838b', '78cef630-1655-5bb5-842c-54c9af3db6a6', 6, 'order_words', 'grammar', 'Put the words in order: «My name is Tom.»', '', '{"tokens":["зову́т","Меня́","Том"]}'::jsonb, 'Меня́ зову́т Том: «me» comes first, then «they call», then the name.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('84287a34-1a6b-5911-8bc3-1689f60f838b', '{"accepted":["Меня зовут Том"]}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('bf11394b-cecd-5460-a306-2b80dcef72fb', '78cef630-1655-5bb5-842c-54c9af3db6a6', 7, 'grammar', 'How are you?', '{"md":"**Как дела́?** [kak dee-LA] is informal; with вы say **Как у вас дела́?** Common answers: **Хорошо́, спаси́бо. А у тебя́?** (Fine, thanks. And you?) · **Норма́льно** [nar-MAL''-na] (OK) · **Отли́чно!** [at-LEECH-na] (Great!). Russians expect a real answer, so don''t use it as a quick «hi» with strangers."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('784d7bf0-6045-5261-8e5a-9dd1ebd52a4f', '78cef630-1655-5bb5-842c-54c9af3db6a6', 8, 'match_pairs', 'vocabulary', 'Match each phrase with its meaning.', '', '{"left":["Приве́т!","Пока́!","До свида́ния!","Спаси́бо!","Как дела́?"],"right":["Goodbye!","Bye!","Hi!","How are things?","Thank you!"]}'::jsonb, 'Пока́ is informal; до свида́ния [da svee-DA-nee-ya] is neutral and polite.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('784d7bf0-6045-5261-8e5a-9dd1ebd52a4f', '{"pairs":{"Приве́т!":"Hi!","Пока́!":"Bye!","До свида́ния!":"Goodbye!","Спаси́бо!":"Thank you!","Как дела́?":"How are things?"}}'::jsonb) on conflict (exercise_id) do nothing;
