insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('39faec22-aabc-5782-9287-a124a07fa7af', '78cef630-1655-5bb5-842c-54c9af3db6a6', 1001, 'match_pairs', 'vocabulary', 'Match each word to its meaning.', '', '{"left":["здра́вствуйте","приве́т","пока́","до свида́ния"],"right":["hi","hello (polite)","goodbye","bye"]}'::jsonb, 'This lesson''s new words.', 10) on conflict (id) do nothing;
