insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('0cfb1dae-ad3a-5bdb-9ff5-82b763271873', '9001237e-652a-5b11-8ed9-a500f8c5fdaa', 'ruen-eto', 'Э́то: «this is» without «is»', 'No articles, no «to be» in the present: э́то, кто? and что?', array['Say «this is…»', 'Ask who and what', 'Answer yes or no']::text[], 1, 11, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
