insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1f24de49-7f06-5d2c-af22-49391b7d6322', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 0, 'grammar', 'Three words Russian doesn''t need', '{"md":"**Э́то кот** [E-ta kot] means «This is a cat», «That''s the cat» or «It''s a cat». Russian has **no articles** (no «a», no «the») and **no «is», «am», «are» in the present**. Context does the work. It feels strange for a day, then wonderfully simple."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fe88c232-2901-59e6-9d99-2b3b0a46954f', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 1, 'example', 'Э́то…', '{"items":[{"ru":"Э́то кот.","es":"This is a cat."},{"ru":"Э́то Ива́н.","es":"This is Ivan."},{"ru":"Э́то моя́ ма́ма.","es":"This is my mum."},{"ru":"Э́то метро́.","es":"This is the metro."}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4c0d2f36-c497-570c-a6e0-6a92ef0f0969', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 2, 'grammar', 'Кто? and что?', '{"md":"**Кто э́то?** [kto E-ta] = Who is this? **Что э́то?** [shto E-ta] = What is this? Note: что is said [shto]. A yes/no question uses the **same words** as a statement; only your voice rises on the key word: **Э́то кот?** = Is this a cat?"}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('6e5858ea-aa48-51dc-a8b9-8230edf2a7a4', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 3, 'grammar', 'grammar', 'Choose the question word: «___ э́то? — Э́то Ива́н.»', '', '{}'::jsonb, 'People → кто: Кто э́то? — Э́то Ива́н.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('a25dd041-8b17-5a39-b1ea-e76b58ead7ea', '6e5858ea-aa48-51dc-a8b9-8230edf2a7a4', 'Кто', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('d696e57d-bf85-5b8f-b4f8-a87d19ae0985', '6e5858ea-aa48-51dc-a8b9-8230edf2a7a4', 'Что', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('6e5858ea-aa48-51dc-a8b9-8230edf2a7a4', '{"correct":"Кто"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('0d20cf61-3cc5-569f-b38b-6f9df2bffeb3', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 4, 'grammar', 'grammar', 'Choose the question word: «___ э́то? — Э́то кот.»', '', '{}'::jsonb, 'Animals are кто too! English says «What is it?» for a cat, but Russian asks Кто э́то?', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('4c636c95-1d34-5ecc-955e-fa9154705578', '0d20cf61-3cc5-569f-b38b-6f9df2bffeb3', 'Кто', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('763bf8fa-dcd8-5365-b146-258808314eb1', '0d20cf61-3cc5-569f-b38b-6f9df2bffeb3', 'Что', 1) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('0d20cf61-3cc5-569f-b38b-6f9df2bffeb3', '{"correct":"Кто"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ca8edd4e-6233-5125-8c22-e094c2f57260', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 5, 'tip', 'Don''t translate «is»', '{"md":"Say **Э́то кот**, never «Э́то есть кот». Between two nouns, writing uses a dash where English has «is»: **Ива́н — студе́нт** (Ivan is a student). In speech it''s just a small pause."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ebdf47a8-f3f7-50b3-a866-8b424be76854', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 6, 'grammar', 'Yes and no', '{"md":"**Да, э́то кот.** (Yes, it''s a cat.) **Нет, э́то не кот. Э́то соба́ка.** (No, it isn''t a cat. It''s a dog.) **нет** = no; **не** = not, placed right before the word it negates."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8fcb4c24-39db-5251-bd58-3b9487fbf02d', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 7, 'dialogue', 'What''s that?', '{"lines":[{"speaker":"Mila","ru":"Что э́то?","es":"What''s this?"},{"speaker":"Sam","ru":"Э́то борщ.","es":"It''s borscht."},{"speaker":"Mila","ru":"А э́то? Э́то торт?","es":"And this? Is it a cake?"},{"speaker":"Sam","ru":"Нет, э́то не торт. Э́то хлеб.","es":"No, it isn''t a cake. It''s bread."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('cc599acc-0627-58b4-994d-9de04ff18973', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 8, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"Э́то не кот."}'::jsonb, 'Э́то не кот = It isn''t a cat.', 10) on conflict (id) do nothing;
