insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('86715fde-11a2-546b-a98b-6870ea03d7a4', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 9, 'reading_comprehension', 'reading', 'What is Anna''s job?', '', '{"text":"Э́то Ива́н. Ива́н — студе́нт. А э́то А́нна. А́нна — врач. А э́то кот Ба́рсик."}'::jsonb, 'А́нна — врач = Anna is a doctor.', 10) on conflict (id) do nothing;
