insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('39ca602a-2c10-5843-bdb7-b8fc733dfce9', '0cfb1dae-ad3a-5bdb-9ff5-82b763271873', 13, 'pronunciation', 'speaking', 'Say: «Кто э́то? — Э́то мой брат».', '', '{"audio_text":"Кто э́то? — Э́то мой брат."}'::jsonb, '[kto E-ta? E-ta moy brat] = Who''s this? It''s my brother.', 10) on conflict (id) do nothing;
