insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('64f29665-73fd-5627-8792-2a6f05054a1b', '9001237e-652a-5b11-8ed9-a500f8c5fdaa', 'ruen-gender', 'He, she, it: the gender of nouns', 'Every noun is masculine, feminine or neuter, and you can usually see it in the ending.', array['Find a noun''s gender from its ending', 'Use он, она́, оно́ for things', 'Say «my»: мой, моя́, моё']::text[], 2, 12, 90, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
