insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('607f23d1-258a-504f-bc05-6e86351c469a', '64f29665-73fd-5627-8792-2a6f05054a1b', -98, 'multiple_choice', 'vocabulary', 'What does “ты” mean?', '', '{}'::jsonb, '«ты» = you (informal).', 10) on conflict (id) do nothing;
