insert into public.exercise_options (id, exercise_id, label, order_index) values ('2cf2fddf-7772-5979-ad53-d94299d8c574', '607f23d1-258a-504f-bc05-6e86351c469a', 'you (formal or plural)', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('607f23d1-258a-504f-bc05-6e86351c469a', '{"correct":"you (informal)"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('de3a8bf2-ceba-5246-b538-dd58ff4f6294', '64f29665-73fd-5627-8792-2a6f05054a1b', 0, 'text', 'Even a table has a gender', '{"md":"Every Russian noun is **masculine**, **feminine** or **neuter**, including things. A table is «he», a book is «she», a window is «it». The good news: **the ending usually tells you**, so you don''t have to memorise genders one by one."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('9d161457-2692-59ef-8ea3-020e64089ccf', '64f29665-73fd-5627-8792-2a6f05054a1b', 1, 'table', 'Spot the gender by the ending', '{"caption":"Check the last letter of the word.","headers":["Gender","Ending","Examples","Pronoun"],"rows":[["masculine","consonant, -й","дом, стол, музе́й","он (he)"],["feminine","-а, -я","кни́га, маши́на, неде́ля","она́ (she)"],["neuter","-о, -е","окно́, мо́ре, письмо́","оно́ (it)"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('bb07fcac-88d2-5b9f-a1ee-7f0efed45017', '64f29665-73fd-5627-8792-2a6f05054a1b', 2, 'tip', 'Watch out for -ь and men in -а', '{"md":"Nouns ending in **-ь** can be masculine or feminine: **день** (m), **мать** (f), **ночь** (f). Learn them with он or она́. And meaning beats ending: **па́па** (dad) and **дя́дя** (uncle) are masculine."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('3031187e-5018-5e0b-8b5c-22f72b741b9a', '64f29665-73fd-5627-8792-2a6f05054a1b', 3, 'grammar', 'grammar', 'Где ключ? — ___ здесь. (Where''s the key? It''s here.)', '', '{}'::jsonb, 'ключ ends in a consonant → masculine → он. Things are он or она́ too, not only «it».', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('b48c5cd7-58c3-563b-92b3-ec70932eff5e', '3031187e-5018-5e0b-8b5c-22f72b741b9a', 'Он', 0) on conflict (id) do nothing;
