insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fec15bbd-6bb8-5c9d-a94f-f15c5254696f', '64f29665-73fd-5627-8792-2a6f05054a1b', 5, 'grammar', 'My: мой, моя́, моё', '{"md":"The word for **my** agrees with the gender of the thing, not with you. The same goes for **your** (informal): твой, твоя́, твоё.","table":{"headers":["Gender","my","your","Example"],"rows":[["masculine","мой","твой","мой дом"],["feminine","моя́","твоя́","моя́ кни́га"],["neuter","моё","твоё","моё окно́"]]}}'::jsonb) on conflict (id) do nothing;
