insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('dcd82711-6b5b-5f4e-a506-7586fc02d124', '9001237e-652a-5b11-8ed9-a500f8c5fdaa', 'ruen-plural', 'One book, many books: the plural', 'Plural endings -ы, -и, -а, -я, the seven-letter spelling rule and the irregular plurals you''ll hear every day.', array['Form regular plurals', 'Apply the seven-letter spelling rule', 'Use the common irregular plurals']::text[], 3, 12, 90, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
