insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('017afaff-899d-5215-b411-8cb8f4d7857c', 'dcd82711-6b5b-5f4e-a506-7586fc02d124', 0, 'grammar', 'Masculine and feminine: -ы or -и', '{"md":"Masculine nouns add **-ы**; feminine nouns swap **-а** for **-ы**. Soft endings (-й, -ь, -я) take **-и**.","table":{"headers":["Singular","Plural","Meaning"],"rows":[["стол","столы́","tables"],["ма́ма","ма́мы","mums"],["музе́й","музе́и","museums"],["неде́ля","неде́ли","weeks"],["ночь","но́чи","nights"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('71c8da40-c94a-550d-a3e3-5d6ee229ecea', 'dcd82711-6b5b-5f4e-a506-7586fc02d124', 1, 'tip', 'The seven-letter spelling rule', '{"md":"After **г, к, х, ж, ш, ч, щ** Russian never writes ы: write **и** instead. **кни́га → кни́ги**, **ключ → ключи́**, **каранда́ш → карандаши́** (pencils). This rule will come back again and again."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('4c00422e-4d71-5a48-bc87-80eb889f2d89', 'dcd82711-6b5b-5f4e-a506-7586fc02d124', 2, 'grammar', 'grammar', 'The plural of кни́га is…', '', '{}'::jsonb, 'After г write и, never ы: кни́ги.', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('945026e0-632f-5561-b343-ec947fcf3bd0', '4c00422e-4d71-5a48-bc87-80eb889f2d89', 'кни́ги', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('3788d673-11e0-5451-9651-631b92f36765', '4c00422e-4d71-5a48-bc87-80eb889f2d89', 'кни́гы', 1) on conflict (id) do nothing;
