insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('6ce46d29-4dcb-5855-8b9c-7921dc4bc707', 'dcd82711-6b5b-5f4e-a506-7586fc02d124', 3, 'grammar', 'Neuter: -а or -я', '{"md":"Neuter **-о** becomes **-а**, and **-е** becomes **-я**: **окно́ → о́кна**, **письмо́ → пи́сьма**, **мо́ре → моря́**. The stress often moves in the plural, so always listen."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('8d07a064-3404-53bf-9c1e-79cfd16d85f1', 'dcd82711-6b5b-5f4e-a506-7586fc02d124', 4, 'listen_select', 'listening', 'Listen and choose what you hear.', '', '{"audio_text":"о́кна"}'::jsonb, 'о́кна [OK-na] = windows; окно́ [ak-NO] = window. The stress moved!', 10) on conflict (id) do nothing;
