insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8c055108-b679-574c-a3e7-9a74f83aac8a', 'dcd82711-6b5b-5f4e-a506-7586fc02d124', 5, 'grammar', 'Learn these by heart', '{"md":"Some of the most common words have special plurals: **друг → друзья́** (friends), **челове́к → лю́ди** (people), **ребёнок → де́ти** (children), **дом → дома́** (houses), **го́род → города́** (cities)."}'::jsonb) on conflict (id) do nothing;
