insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('773262e6-8660-5878-90b4-f364734a6953', '8bcc4759-0db1-5101-86b9-bc4363a666ae', 'ruen-u-menya-est', 'У меня́ есть: «I have» the Russian way', 'Russian doesn''t «have»: something «is by you».', array['Say what you have', 'Ask «do you have…?»', 'Use the forms у меня́, у тебя́, у вас…']::text[], 0, 11, 85, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
