insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('2e4bdfc8-72b7-532f-a588-49b38625143e', '773262e6-8660-5878-90b4-f364734a6953', 0, 'grammar', 'Russian doesn''t «have»', '{"md":"To say **I have a cat**, Russian says **У меня́ есть кот** [oo mee-NYA yest'' kot], literally «By me there is a cat». The thing you have is the subject of the sentence. **есть** = there is."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('05a5160d-84d6-5f91-a831-84c61ffab5b2', '773262e6-8660-5878-90b4-f364734a6953', 1, 'table', 'Who has it?', '{"headers":["Person","Russian","English"],"rows":[["я","у меня́ есть","I have"],["ты","у тебя́ есть","you have (informal)"],["он","у него́ есть","he has"],["она́","у неё есть","she has"],["мы","у нас есть","we have"],["вы","у вас есть","you have (polite / plural)"],["они́","у них есть","they have"]]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('32c78b34-3891-5da6-83da-19aad86994e3', '773262e6-8660-5878-90b4-f364734a6953', 2, 'tip', 'него́ is said [nee-VO]', '{"md":"In the endings **-ого** and **-его**, the г sounds like [v]: **у него́** [oo nee-VO], **сего́дня** [see-VOD-nya] (today). It''s one of the few places where Russian spelling and sound don''t match."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('46158d48-7694-5ba6-8a85-fa4694e00b55', '773262e6-8660-5878-90b4-f364734a6953', 3, 'grammar', 'grammar', '___ есть брат. (She has a brother.)', '', '{}'::jsonb, 'she → у неё. у него́ is «he has».', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('15d49ae9-eb24-5662-9231-b1f4ba8b5cbc', '46158d48-7694-5ba6-8a85-fa4694e00b55', 'У неё', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('81d3c9af-72a0-5dbf-8444-f395660747cd', '46158d48-7694-5ba6-8a85-fa4694e00b55', 'Она́', 1) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('00cba201-42bf-5d1d-bdd9-9ffeb9d33858', '46158d48-7694-5ba6-8a85-fa4694e00b55', 'У него́', 2) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('46158d48-7694-5ba6-8a85-fa4694e00b55', '{"correct":"У неё"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('4dca1418-87ba-5612-a6e3-d742aa4d52a6', '773262e6-8660-5878-90b4-f364734a6953', 4, 'example', 'У меня́ есть…', '{"items":[{"ru":"У меня́ есть сестра́.","es":"I have a sister."},{"ru":"У тебя́ есть маши́на?","es":"Do you have a car?"},{"ru":"У нас есть соба́ка.","es":"We have a dog."},{"ru":"У вас есть вайфа́й?","es":"Do you have Wi-Fi?"}]}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ba72e1c5-c29e-5e8c-9744-989004148b17', '773262e6-8660-5878-90b4-f364734a6953', 5, 'grammar', 'Questions and short answers', '{"md":"The question has the same words, only with a rising voice: **У тебя́ есть брат?** Short answer: **Да, есть.** (Yes, I do.) To say you **don''t** have something Russian uses another case, so for now simply answer **Нет.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a3498e7a-677c-5853-954e-6ef538dfc141', '773262e6-8660-5878-90b4-f364734a6953', 6, 'dialogue', 'At a hotel', '{"lines":[{"speaker":"Guest","ru":"Здра́вствуйте! У вас есть вайфа́й?","es":"Hello! Do you have Wi-Fi?"},{"speaker":"Receptionist","ru":"Да, есть.","es":"Yes, we do."},{"speaker":"Guest","ru":"А ко́фе есть?","es":"And is there coffee?"},{"speaker":"Receptionist","ru":"Да, коне́чно. Вот ко́фе.","es":"Yes, of course. Here''s coffee."}]}'::jsonb) on conflict (id) do nothing;
