insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a8071121-5da6-5883-998b-60dbec2c872d', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 0, 'example', 'From 0 to 10', '{"items":[{"ru":"ноль","es":"[nol''] 0"},{"ru":"оди́н","es":"[a-DEEN] 1"},{"ru":"два","es":"[dva] 2"},{"ru":"три","es":"[tree] 3"},{"ru":"четы́ре","es":"[chee-TƗ-ree] 4"},{"ru":"пять","es":"[pyat''] 5"},{"ru":"шесть","es":"[shest''] 6"},{"ru":"семь","es":"[syem''] 7"},{"ru":"во́семь","es":"[VO-seem''] 8"},{"ru":"де́вять","es":"[DYE-veet''] 9"},{"ru":"де́сять","es":"[DYE-seet''] 10"}]}'::jsonb) on conflict (id) do nothing;
