insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('1d60a5fb-4ec4-52b3-95d2-46291711c236', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 2, 'grammar', '11–19: «one-on-ten»', '{"md":"Add **-надцать** («on ten») to the unit: **оди́ннадцать** 11, **двена́дцать** 12, **трина́дцать** 13, **четы́рнадцать** 14, **пятна́дцать** 15, **шестна́дцать** 16, **семна́дцать** 17, **восемна́дцать** 18, **девятна́дцать** 19. Then **два́дцать** 20. Tens: **три́дцать** 30, **со́рок** 40, **пятьдеся́т** 50, **сто** 100."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('5b62120f-b263-5dbe-a059-01c8f1f6d97c', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 3, 'tip', 'Easy stress, silent д', '{"md":"From 12 to 19 the stress falls on **на**: двена́дцать [dvee-NA-tsat''], except **четы́рнадцать** [chee-TƗR-na-tsat'']. And 11 is **оди́ннадцать** [a-DEE-na-tsat'']. And the д in -дцать is silent: say [tsat'']."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('5df9be81-2752-5502-8903-30a157c37a68', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 4, 'match_pairs', 'vocabulary', 'Match the numbers.', '', '{"left":["три","пять","де́сять","двена́дцать","два́дцать"],"right":["10","5","3","20","12"]}'::jsonb, 'три 3, пять 5, де́сять 10, двена́дцать 12, два́дцать 20.', 10) on conflict (id) do nothing;
insert into public.exercise_solutions (exercise_id, solution) values ('5df9be81-2752-5502-8903-30a157c37a68', '{"pairs":{"три":"3","пять":"5","де́сять":"10","двена́дцать":"12","два́дцать":"20"}}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('a8668dbe-517b-5bcb-9af7-edca79c2a237', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 5, 'grammar', 'One and two have genders', '{"md":"**оди́н** брат, **одна́** сестра́, **одно́** окно́. Two: **два** for masculine and neuter, **две** for feminine: **два бра́та**, **две сестры́**. After 2, 3 and 4 the noun takes a special form; you''ll meet it with рубль below."}'::jsonb) on conflict (id) do nothing;
