insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('7b52dfde-8702-5c16-94be-233efdd49eeb', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 7, 'grammar', 'How much is it?', '{"md":"**Ско́лько сто́ит?** [SKOL''-ka STO-eet] = How much is it? The word for rouble changes after numbers: **1 рубль**, **2–4 рубля́**, **5–20 рубле́й**. Above 20, look at the last digit: **21 рубль**, **22 рубля́**, **25 рубле́й**.","table":{"headers":["Number","Form","Example"],"rows":[["1","рубль","оди́н рубль"],["2, 3, 4","рубля́","три рубля́"],["5–20","рубле́й","де́сять рубле́й"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('ca3493d0-6c17-5735-9700-bcbf5dbbcd36', 'a352e4b0-10a6-5967-b86c-144cd4b06f30', 8, 'dialogue', 'At a kiosk', '{"lines":[{"speaker":"Customer","ru":"Здра́вствуйте! Ско́лько сто́ит вода́?","es":"Hello! How much is the water?"},{"speaker":"Seller","ru":"Пятьдеся́т рубле́й.","es":"Fifty roubles."},{"speaker":"Customer","ru":"Вот, пожа́луйста.","es":"Here you are."},{"speaker":"Seller","ru":"Спаси́бо!","es":"Thank you!"}]}'::jsonb) on conflict (id) do nothing;
