insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', '8bcc4759-0db1-5101-86b9-bc4363a666ae', 'ruen-where', 'Where? в, на and your first case', 'Где? + в or на + the prepositional case ending -е.', array['Ask «where?»', 'Choose between в and на', 'Form the prepositional case']::text[], 2, 12, 90, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
