insert into public.exercise_solutions (exercise_id, solution) values ('1199d14e-bd96-5452-9cc7-f191bc101d64', '{"correct":"children"}'::jsonb) on conflict (exercise_id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('8e11ca7d-fdc6-5eaf-bfe1-564f848412d3', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 0, 'text', 'Your first case', '{"md":"In Russian, nouns change their endings depending on their role in the sentence: these forms are called **cases**. English does the same job with word order and prepositions. Don''t worry: you''ll learn them one at a time, starting with the easiest. To say **where** something is, use **в** (in) or **на** (on, at) and change the ending to **-е**. **Где?** [gdye] = Where?"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('fb8c98b9-539d-51d9-abb4-2231e8b7665f', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 1, 'grammar', 'The prepositional case: -е', '{"md":"Most nouns simply end in **-е** after в or на. Nouns in **-ия** and feminine nouns in **-ь** take **-и**.","table":{"headers":["Word","Where?","Meaning"],"rows":[["Москва́","в Москве́","in Moscow"],["дом","в до́ме","in the house"],["шко́ла","в шко́ле","at school"],["парк","в па́рке","in the park"],["Росси́я","в Росси́и","in Russia"],["пло́щадь","на пло́щади","on the square"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('30b4d169-0c35-549b-aea3-5ef2cbb12616', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 2, 'tip', 'в or на?', '{"md":"**в** = inside something, and with cities and countries: **в Москве́**, **в Росси́и**. **на** = on a surface or in an open space: **на у́лице** (outside, in the street), **на пло́щади**. Some places just take на: learn them as set phrases: **на рабо́те** (at work), **на по́чте** (at the post office), **на вокза́ле** (at the station), **на конце́рте** (at a concert)."}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('a31a049b-c044-5269-8472-74efe8269b31', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 3, 'grammar', 'grammar', 'Ма́ма ___ рабо́те. (Mum is at work.)', '', '{}'::jsonb, 'рабо́та always takes на: на рабо́те. And no «is»!', 10) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('74a2fe37-e2eb-5771-8515-8559c0c5f73d', 'a31a049b-c044-5269-8472-74efe8269b31', 'на', 0) on conflict (id) do nothing;
insert into public.exercise_options (id, exercise_id, label, order_index) values ('8a1038ac-bca3-57b3-b150-faa7c65b56fd', 'a31a049b-c044-5269-8472-74efe8269b31', 'в', 1) on conflict (id) do nothing;
