insert into public.exercise_options (id, exercise_id, label, order_index) values ('e1ca8695-9dd5-581d-a1df-ffbe208cd324', '32083412-9789-56a4-a68f-f0fb9390dd53', 'на', 1) on conflict (id) do nothing;
