insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('aae0847a-70fa-52ae-98c6-c4eae52f48e9', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 5, 'tip', 'в sticks to the next word', '{"md":"**в** is pronounced together with the next word, as if it were one: **в Москве́** [vmas-KVYE]. Before a voiceless consonant it sounds [f]: **в шко́ле** [FSHKO-lee], **в па́рке** [FPAR-kee]."}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('28308e20-c290-5868-a45f-a4f94b787f3d', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 6, 'dialogue', 'Where''s everyone?', '{"lines":[{"speaker":"Liza","ru":"Где па́па?","es":"Where''s Dad?"},{"speaker":"Max","ru":"Па́па на рабо́те.","es":"Dad''s at work."},{"speaker":"Liza","ru":"А где А́нна?","es":"And where''s Anna?"},{"speaker":"Max","ru":"Она́ в шко́ле.","es":"She''s at school."}]}'::jsonb) on conflict (id) do nothing;
insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('55abc87b-9b40-5be1-a8dc-9adafe835e05', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 7, 'fill_blank', 'grammar', 'We''re in the park: Мы в ___.', '', '{"sentence":"Мы в ___.","keyboard":true}'::jsonb, 'парк → в па́рке.', 10) on conflict (id) do nothing;
