insert into public.exercises (id, lesson_id, order_index, type, skill, instructions, prompt, data, explanation, points) values ('e3dacd9d-d128-5bdf-ba12-ddfe20c3757b', '998f9bc1-3ce0-50e0-bf5f-a4f887fe0470', 10, 'reading_comprehension', 'reading', 'Where is Mark now?', '', '{"text":"Меня́ зову́т Марк. Я из Ло́ндона, но сейча́с я в Москве́. Мой брат в Берли́не, а сестра́ до́ма. Ма́ма и па́па на рабо́те."}'::jsonb, 'сейча́с я в Москве́ = now I''m in Moscow. He''s from London (из Ло́ндона).', 10) on conflict (id) do nothing;
