insert into public.lessons (id, unit_id, slug, title, summary, objectives, order_index, estimated_minutes, xp_reward, is_premium, status, source, source_ref) values ('a3fe1264-1052-5b48-bf6a-2323d1ba93a3', '8bcc4759-0db1-5101-86b9-bc4363a666ae', 'ruen-verbs', 'Verbs: I know, you read, we work', 'The present tense of first-group verbs: one ending per person and no «do» or «-ing».', array['Conjugate знать, чита́ть, рабо́тать', 'Ask and say what someone is doing', 'Say «I don''t understand»']::text[], 3, 12, 95, false, 'published', 'complementary', null) on conflict (id) do update set order_index = excluded.order_index;
