insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('3e9ba672-432c-5ac1-83b7-fb7e867379ce', 'a3fe1264-1052-5b48-bf6a-2323d1ba93a3', 0, 'grammar', 'Drop -ть, add the ending', '{"md":"Most verbs ending in **-ать** belong to the **first group**. Take off **-ть** and add one ending per person.","table":{"headers":["Person","знать (to know)","Ending"],"rows":[["я","зна́ю","-ю"],["ты","зна́ешь","-ешь"],["он / она́","зна́ет","-ет"],["мы","зна́ем","-ем"],["вы","зна́ете","-ете"],["они́","зна́ют","-ют"]]}}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('83c95383-d884-5178-a9f1-58b7bbf4afe6', 'a3fe1264-1052-5b48-bf6a-2323d1ba93a3', 1, 'tip', 'One present tense', '{"md":"**Я чита́ю** = I read, I am reading and I do read. Russian has **no -ing**, **no «do»** in questions and **no «am»**: never say «Я есть чита́ю». A question is just a statement with a rising voice: **Ты чита́ешь?** To negate, put **не** before the verb: **Я не зна́ю.**"}'::jsonb) on conflict (id) do nothing;
insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('66419270-37a0-5a24-b6bf-38a8de310fe8', 'a3fe1264-1052-5b48-bf6a-2323d1ba93a3', 2, 'example', 'Everyday verbs', '{"items":[{"ru":"Что ты де́лаешь? — Я чита́ю.","es":"What are you doing? I''m reading."},{"ru":"Где вы рабо́таете? — Я рабо́таю в ба́нке.","es":"Where do you work? I work at a bank."},{"ru":"Я не понима́ю.","es":"I don''t understand."},{"ru":"Вы понима́ете по-ру́сски?","es":"Do you understand Russian?"}]}'::jsonb) on conflict (id) do nothing;
