insert into public.lesson_content (id, lesson_id, order_index, kind, title, body) values ('93a69558-0a4f-57f6-8b84-27023b52ee38', 'a3fe1264-1052-5b48-bf6a-2323d1ba93a3', 6, 'dialogue', 'At a café', '{"lines":[{"speaker":"Kate","ru":"Что ты де́лаешь?","es":"What are you doing?"},{"speaker":"Max","ru":"Я чита́ю журна́л. А ты?","es":"I''m reading a magazine. And you?"},{"speaker":"Kate","ru":"Я рабо́таю. Слу́шай, ты зна́ешь, где Ива́н?","es":"I''m working. Listen, do you know where Ivan is?"},{"speaker":"Max","ru":"Не зна́ю. Наве́рное, на рабо́те.","es":"I don''t know. Probably at work."}]}'::jsonb) on conflict (id) do nothing;
